const TANDA_2 = [
  // ----- PROG FUNDACIONAL que te faltaba (la raíz de 'cada disco un mundo') -----
  { name: "King Crimson", genre: "Prog Rock", desc: "Lo concreto de cada etapa: en los setenta, mellotron y saxo sobre improvisación libre; en los ochenta, la formación con Adrian Belew monta dos guitarras tocando patrones entrelazados en métricas distintas a la vez, inspirados en el gamelán indonesio, con Bruford a la batería electrónica; en los noventa, doble trío, con dos guitarras, dos bajos y dos baterías simultáneas. Fripp toca con púa y digitación cruzada, casi sin vibrato. El mapa: In the Court of the Crimson King (1969), Larks' Tongues in Aspic (1973), Starless and Bible Black, Red (1974) y Discipline (1981) son la cumbre, y THRAK (1995) y The Power to Believe (2003) están cerca; Beat, Three of a Perfect Pair y The ConstruKction of Light bajan algo. Entrada: Red o Discipline.", origin: "rec", pick: true, p: 1, y: 1968, via: "Prog raíces", c: 1 },
  { name: "Gentle Giant", genre: "Prog Rock", desc: "El contrapunto vocal está escrito como una fuga: cuatro o cinco voces entrando por turnos con líneas distintas, no armonizando en bloque. Y los músicos se intercambian instrumentos dentro del tema, con violín, chelo, vibráfono y flauta de pico apareciendo como voces reales. De Gentle Giant (1970) a Acquiring the Taste, Three Friends, Octopus, In a Glass House, The Power and the Glory y Free Hand (1975) son siete discos seguidos a ese nivel; los tres últimos, de The Missing Piece (1977) a Civilian (1980), giran al pop y bajan. Entrada: Octopus.", origin: "rec", pick: true, p: 1, y: 1970, via: "Prog raíces", c: 1 },
  { name: "Jethro Tull", genre: "Prog Rock", desc: "Ian Anderson usa la flauta como instrumento principal de una banda de rock, no como color, y escribe en compases impares heredados del folk británico. Thick as a Brick (1972) y A Passion Play son cada uno una sola pieza que ocupa el disco entero, y en Songs from the Wood (1977) giraron a un folk eléctrico con mandolina que era prácticamente otra banda. De Stand Up (1969) a Heavy Horses (1978) es la cumbre; desde los ochenta, de A y Under Wraps a Rock Island, es muy irregular. Entrada: Thick as a Brick.", origin: "rec", pick: true, p: 2, y: 1967, via: "Prog raíces" },
  { name: "Van der Graaf Generator", genre: "Prog Rock", desc: "Prog sin guitarra durante tramos largos, sostenido por órgano y saxo, muy disonante y con la voz de Peter Hammill llevando la tensión. Pawn Hearts (1971) tiene A Plague of Lighthouse Keepers ocupando una cara entera. De The Least We Can Do (1970) y H to He a Pawn Hearts, y de Godbluff (1975) a Still Life y World Record (1976), es la cumbre; la vuelta, de Present (2005) a Do Not Disturb (2016), está a buen nivel, salvo ALT (2012), improvisaciones sueltas. Entra por Pawn Hearts o Godbluff.", origin: "rec", p: 1, y: 1967, c: 2 },
  { name: "Camel", genre: "Prog Rock", desc: "Prog melódico donde la guitarra de Andy Latimer canta la melodía en lugar de la voz: frases largas y sostenidas, muy vocales, sobre teclados cálidos. The Snow Goose es un disco entero instrumental que narra un cuento sin una sola letra, y ahí queda claro que la banda escribe temas que vuelven transformados en vez de canciones. Bello y narrativo, poco agresivo. El mapa: Camel (1973) abre; Mirage (1974), The Snow Goose (1975) y Moonmadness (1976) son la cumbre, y Rain Dances (1977) está cerca; de Breathless (1978) a Stationary Traveller (1984) se van al pop y bajan; Dust and Dreams (1991), Harbour of Tears (1996) y Rajaz (1999) son la vuelta, a buen nivel. Entrada: Moonmadness o The Snow Goose.", origin: "rec", pick: true, p: 2, y: 1971, via: "Prog raíces" },
  { name: "Magma", genre: "Zeuhl / Avant Prog", desc: "Piezas de veinte minutos construidas por acumulación: un coro repite células cortas sobre armonía de jazz mientras todo se va apretando hasta el clímax, con la batería de Christian Vander como motor compositivo y no como acompañamiento (su pulso viene de Coltrane) y el bajo sosteniendo ostinatos durante la pieza entera. Hipnótico y agobiante a propósito, y esa forma de construir no tiene par fuera de sus propios discípulos. De Mekanïk Destruktïw Kommandöh (1973) y Köhntarkösz a Üdü Wüdü y Attahk (1978) es la racha clásica; Merci (1984) es el punto bajo, y desde K.A (2004) vuelven a su nivel hasta Zëss (2019) y Kartëhl (2022). Entrada: Mekanïk Destruktïw Kommandöh.", origin: "rec", p: 1, y: 1969, c: 3 },
  { name: "Cardiacs", genre: "Avant-garde / Experimental", desc: "[Comodín] Lo llaman pronk, punk cruzado con prog: cambian de compás cada pocos compases sin avisar y sin que suene a ejercicio, con armonía que salta a acordes inesperados y varias voces cantando líneas distintas a la vez, todo a velocidad de punk y con un tono luminoso que choca con lo retorcido que es por dentro. De The Seaside a A Little Man and a House and the Whole World Window (1988), On Land and in the Sea, Heaven Born and Ever Bright, Sing to God (1996) y Guns no hay disco flojo, y LSD (2025), terminado tras la muerte de Tim Smith, está a la altura. Entrada: A Little Man and a House and the Whole World Window.", origin: "rec", p: 1, y: 1977, c: 3 },

  // ----- PROG MODERNO (veta Tool / Leprous / Haken / Porcupine Tree) -----
  { name: "Soen", genre: "Prog Metal", desc: "Metal progresivo sueco de grooves hipnóticos en métrica desplazada, con la batería de Martin Lopez construyendo los temas desde el ritmo y la voz de Joel Ekelöf muy al frente. De Lotus (2019) a Reliance (enero de 2026). Entrada: Lotus.", p: 2, origin: "rec", pick: true, y: 2010, via: "Tool/Leprous" },
  { name: "Vola", genre: "Prog Metal / Synth", desc: "Daneses que cruzan riffs de djent con estribillos de synth-pop y producción muy pulida: la guitarra hace de base rítmica y la canción manda sobre la escritura instrumental. Pegadizo y bien hecho, pero de complejidad moderada. Entrada: Witness.", p: 3, origin: "rec", pick: true, y: 2006, via: "Tool/Leprous", c: 2 },
  { name: "Steven Wilson", genre: "Prog Rock / Art", desc: "El cerebro de Porcupine Tree en solitario, y cada disco cambia de piel: el prog setentero con músicos de jazz de Grace for Drowning (2011) y The Raven That Refused to Sing (2013), el conceptual Hand. Cannot. Erase. (2015), el pop art de To the Bone y el electrónico de The Harmony Codex (2023). Solo The Future Bites (2021), electropop, baja claramente; The Overview (2025) vuelve a las piezas largas y Requiem for a Village sale el 6 de noviembre de 2026. Entrada: The Raven That Refused to Sing.", origin: "rec", pick: true, p: 1, y: 2008, via: "Tool/Leprous", c: 1 },
  { name: "Bent Knee", genre: "Avant Art Rock", desc: "Art rock de Boston que salta de lo íntimo a lo explosivo dentro del tema, con la voz enorme de Courtney Swain, violín, bajo y batería escritos en capas y armonías que no resuelven donde se espera. Shiny Eyed Babies (2014), Say So, Land Animal (2017) y You Know What They Mean son la etapa fuerte. Entrada: Land Animal.", p: 2, origin: "rec", pick: true, female: true, y: 2009, via: "Tool/Leprous", c: 1 },
  { name: "Frost*", genre: "Prog Metal", desc: "Prog británico moderno liderado desde el teclado por Jem Godfrey: temas largos con ganchos pop, humor y producción de lujo, pero con secciones instrumentales densas de teclado y guitarra que cambian de métrica. Milliontown (2006), con su pieza titular de veintiséis minutos, Falling Satellites (2016), Day and Age (2021) y Life in the Wires (2024), un disco conceptual, sostienen el nivel; Experiments in Mass Appeal (2008) es el más flojo. Entrada: Milliontown.", p: 2, origin: "rec", pick: true, y: 2004, via: "Tool/Leprous" },

  // ----- PROG / SLUDGE / POST-METAL ATMOSFÉRICO (pilares que te faltan) -----
  { name: "Baroness", genre: "Sludge / Prog Metal", desc: "Sludge que se abrió al prog y al rock: guitarras armonizadas a dos voces, cambios de sección largos y una batería que empuja más que marca. Cada disco lleva un color, de Red y Blue a Purple, Gold & Grey y Stone (2023), y el nivel se mantiene de uno a otro. Con fechas: Red Album (2007), Blue Record (2009), Yellow & Green (2012), Purple (2015), Gold & Grey (2019) y Stone (2023). Entrada: Blue Record.", p: 2, origin: "rec", pick: true, y: 2003, via: "Post-metal", c: 1 },
  { name: "Elder", genre: "Stoner / Prog Rock", desc: "Pasaron de stoner doom a prog psicodélico instrumental y luminoso, y cada disco se aleja más del anterior: los temas duran diez o doce minutos y se desarrollan sin volver al riff inicial. El mapa: Elder (2008) y Dead Roots Stirring (2011) son stoner doom; Lore (2015) abre el giro, y Reflections of a Floating World (2017), Omens (2020) e Innate Passage (2022) son la cumbre; Through Zero (2026) es el último. Entrada: Reflections of a Floating World.", origin: "rec", pick: true, p: 2, y: 2006, via: "Post-metal", c: 1 },
  { name: "Boris", genre: "Experimental / Drone", desc: "Trío japonés que cambia de género disco a disco: drone de amplificador en Amplifier Worship y Flood (2000), rock pesado en Akuma no Uta y Pink (2005), colaboraciones con Sunn O))), shoegaze y pop, y la vuelta al peso en NO (2020). La batería de Atsuo y los volúmenes extremos son la constante. Entrada: Pink, luego Flood.", p: 2, origin: "rec", pick: true, y: 1992, via: "Post-metal", c: 1 },
  { name: "Neurosis", genre: "Post-Metal / Sludge", desc: "Temas de diez minutos construidos por acumulación: una figura de guitarra se repite creciendo en capas y volumen hasta reventar, con percusión tribal, teclados y samples de fondo y varias voces gritando a la vez. De Souls at Zero (1992) y Enemy of the Sun a Through Silver in Blood (1996), Times of Grace, A Sun That Never Sets, The Eye of Every Storm y Given to the Rising (2007) es una racha enorme; Honor Found in Decay y Fires Within Fires bajan, y An Undying Love for a Burning World (marzo de 2026), con Aaron Turner en lugar de Scott Kelly, recupera el nivel. Entrada: Through Silver in Blood o Times of Grace.", origin: "rec", p: 1, y: 1985, c: 2 },
  { name: "Isis", genre: "Post-Metal", desc: "Post-metal donde el riff se repite sin variar mientras todo lo demás cambia alrededor, así que el movimiento viene de las capas y no de la progresión. Oceanic y Panopticon son discos conceptuales con arco, no colecciones de temas. El mapa: Celestial (2000) es sludge más crudo; Oceanic (2002) y Panopticon (2004) son la cumbre, y In the Absence of Truth (2006) y Wavering Radiant (2009) se mantienen. Se separaron en 2010. Entrada: Oceanic.", origin: "rec", pick: true, p: 2, y: 1997, via: "Post-metal" },
  { name: "Russian Circles", genre: "Post-Metal / Instrumental", desc: "Post-metal instrumental de tres personas, sin voz: Mike Sullivan construye con loops de guitarra en capas mientras Dave Turncrantz toca una batería muy protagonista, y Brian Cook al bajo con distorsión hace de segunda guitarra. Del susurro al muro. Muy parejos de Enter (2006) a Memorial (2013), Blood Year, Gnosis (2022) y Nine (agosto de 2026). Entrada: Memorial.", origin: "rec", pick: true, p: 2, y: 2004, via: "Post-metal" },
  { name: "Godspeed You! Black Emperor", genre: "Post-Rock", desc: "Piezas de veinte minutos divididas en movimientos con nombre, construidas por acumulación lentísima: entra un motivo, se van sumando capas de guitarra, violín y contrabajo con arco durante minutos, y el clímax llega tras una espera deliberadamente larga. Usan grabaciones de campo (voces de la calle, predicadores, ruido) como material temático y no como adorno, y el conjunto se acerca más a la música de cámara que al rock. Colectivo de Montreal, sin cantante y sin solista. Muy parejos de F♯ A♯ ∞ (1997) y Lift Your Skinny Fists (2000) a la vuelta, de 'Allelujah! Don't Bend! Ascend! (2012) a No Title as of 13 February 2024 (2024). Entra por Lift Your Skinny Fists Like Antennas to Heaven.", origin: "rec", p: 1, y: 1994, c: 2 },
  { name: "Pallbearer", genre: "Doom Metal", desc: "Doom de Arkansas melódico y emotivo, con dos guitarras armonizadas en temas largos y la voz limpia de Brett Campbell. Sorrow and Extinction (2012), Foundations of Burden (2014), la cumbre, Heartless, Forgotten Days y Mind Burns Alive (2024). Entrada: Foundations of Burden.", origin: "rec", pick: true, p: 2, y: 2008, via: "Post-metal" },
  { name: "YOB", genre: "Doom / Psych Metal", desc: "Doom psicodélico de Oregón de Mike Scheidt: riffs colosales y lentos que se estiran en temas de veinte minutos, con la voz pasando del grito al canto agudo casi meditativo. Muy parejos de The Illusion of Motion (2004) a The Great Cessation, Atma, Clearing the Path to Ascend (2014) y Our Raw Heart (2018), tras una enfermedad grave de Scheidt. Entrada: Clearing the Path to Ascend.", origin: "rec", pick: true, p: 2, y: 1996, via: "Post-metal" },

  // ----- AVANT / DISONANTE / JAZZ-METAL (tu veta Mr. Bungle / Dog Fashion al extremo) -----
  { name: "Igorrr", genre: "Avant-garde / Breakcore", desc: "[Comodín] Gautier Serre mezcla breakcore, ópera barroca, death metal y música balcánica en una misma canción, con voz lírica femenina contra guturales y baterías a velocidades imposibles junto a acordeón y clave. Hallelujah (2012), Savage Sinusoid (2017), Spirituality and Distortion (2020) y Amen (2025). Entrada: Savage Sinusoid.", p: 2, origin: "rec", pick: true, y: 2005, via: "Mr. Bungle", c: 3 },
  { name: "Secret Chiefs 3", genre: "Avant-garde / Experimental", desc: "El proyecto de Trey Spruance, de Mr. Bungle: surf, música persa e india, metal, bandas sonoras y electrónica, con cada disco montado sobre otra instrumentación y escalas de Oriente Medio escritas con la precisión de un arreglo de cámara. Nueve discos sin uno flojo, de First Grand Constitution and Bylaws (1996) y Book M a Book of Horizons, Book of Souls: Folio A (2013) y los de sus subgrupos, como Traditionalists o Ishraqiyun. Entrada: Book of Horizons.", p: 1, origin: "rec", pick: true, y: 1995, via: "Mr. Bungle", c: 1 },
  { name: "Sleepytime Gorilla Museum", genre: "Avant-garde Metal", desc: "[Comodín] Avant-metal que salta de casi silencio a violencia total dentro de un mismo compás, con compases impares constantes, contrapunto de verdad entre guitarra, violín, bajo y percusión, y voces habladas, cantadas y gritadas repartidas entre varios miembros; sus instrumentos construidos están dentro del arreglo, dando percusiones y drones que un kit normal no da. Grand Opening and Closing (2001), Of Natural History (2004), In Glorious Times (2007) y, diecisiete años después, Of the Last Human Being (2024), a la altura de los mejores. Entrada: Of Natural History.", origin: "rec", p: 1, y: 1999, c: 3 },
  { name: "Estradasphere", genre: "Avant-garde / Eclectic", desc: "Eclecticismo de la escuela de Mr. Bungle: surf, metal, klezmer, bluegrass, jazz y música de videojuego dentro del mismo tema, con violín, saxo y trompeta tocando unísonos rapidísimos. It's Understood (2000), Buck Fever, Quadrophonic y Palace of Mirrors (2006), el más compuesto. Entrada: Palace of Mirrors.", p: 2, origin: "rec", pick: true, y: 1998, via: "Mr. Bungle", c: 1 },
  { name: "Naked City", genre: "Avant-garde Jazz", desc: "Composición por fichas: cada corte dura entre uno y quince segundos y el conjunto salta de lounge a grindcore sin transición, pero todo está escrito y ensayado hasta poder tocarse igual dos veces, con Joey Baron sosteniendo cambios de tempo cada pocos segundos. Naked City y Torture Garden (1990), Grand Guignol, Heretic y Radio (1993) sostienen esa exigencia; Leng Tch'e, una sola pieza lenta de grind, y Absinthe, ambiental, son experimentos más áridos. Entrada: Naked City, luego Grand Guignol.", origin: "rec", pick: true, p: 1, y: 1988, via: "Mr. Bungle", c: 1 },
  { name: "Imperial Triumphant", genre: "Avant-garde Metal / Jazz", desc: "Neoyorquinos. Acordes de jazz disonante dentro del black y el death, con la batería de Kenny Grohowski a contratiempo del riff, el bajo de Steve Blanco con líneas propias y arreglos de metales y coro escritos. De Abyssal Gods (2015) y Vile Luxury a Alphaville (2020), Spirit of Ecstasy y Goldstar (2025) sostienen la misma escritura; solo el debut, Abominamentvm, queda por debajo. Entrada: Alphaville.", p: 1, origin: "rec", pick: true, y: 2005, via: "Mr. Bungle", c: 2 },
  { name: "White Ward", genre: "Avant-garde Metal / Jazz", desc: "Black metal atmosférico de Odesa con saxofón de jazz noir como segunda voz, pasajes de piano y bajo en clave de jazz y post-rock, en temas largos que alternan blast beat y club de madrugada. Futility Report (2017), Love Exchange Failure (2019) y False Light (2022), los tres muy bien recibidos. Entrada: Love Exchange Failure.", p: 2, origin: "rec", pick: true, y: 2012, via: "Mr. Bungle" },
  { name: "Shining (NOR)", genre: "Avant-garde Jazz Metal", desc: "De Oslo: empezaron como cuarteto de jazz acústico y Jørgen Munkeby los llevó al blackjazz, metal industrial con saxo desbocado, compases cambiantes y batería de jazz tocando a velocidad de black. In the Kingdom of Kitsch You Will Be a Monster (2005), Grindstone y Blackjazz (2010) son la cumbre y One One One (2013) la versión más compacta; Animal (2018) giró al rock de estribillo y es lo más flojo. Entrada: Blackjazz.", p: 2, origin: "rec", pick: true, y: 1999, via: "Mr. Bungle", c: 3 },
  { name: "Gorguts", genre: "Dissonant Death Metal", desc: "Riffs disonantes construidos sobre intervalos que no resuelven, con Luc Lemay escribiendo por bloques que no vuelven en vez de por estrofas. De Considered Dead (1991) y The Erosion of Sanity al extremo del ruido controlado de Obscura (1998), From Wisdom to Hate y Colored Sands (2013), reconstruido con un cuarteto de cuerda escrito, más el EP de una sola pieza Pleiades' Dust (2016): veinticinco años moviendo el terreno. Entrada: Colored Sands, luego Obscura.", origin: "rec", pick: true, p: 1, y: 1989, via: "Mr. Bungle", c: 3 },
  { name: "Ulcerate", genre: "Dissonant Death Metal", desc: "Neozelandeses. Los riffs no tienen centro tonal y la batería de Jamie Saint Merat toca contra ellos en vez de marcarlos, así que la tensión no resuelve nunca. Lo afinan disco a disco sin repetirse: Everything Is Fire (2009), The Destroyers of All, Vermis, Shrines of Paralysis (2016), Stare Into Death and Be Still (2020) y Cutting the Throat of God (2024). Entrada: Stare Into Death and Be Still.", origin: "rec", pick: true, p: 1, y: 2000, via: "Mr. Bungle" },
  { name: "Oranssi Pazuzu", genre: "Psychedelic Black Metal", desc: "No es black metal con efectos encima: el motor rítmico es krautrock, con bajo y batería repitiendo un patrón hipnótico durante minutos mientras las capas de sintetizador y guitarra se van deformando por encima, y de ahí meten prog, acid house, jazz y ruido de vanguardia sin que ninguna sección vuelva igual. Muy parejos de Kosmonument (2011) a Valonielu, Värähtelijä (2016), Mestarin kynsi (2020), donde menos black metal hay y más raro suena, y Muuntautuja (2024). Finlandeses. Entrada: Mestarin kynsi o Värähtelijä.", origin: "rec", p: 1, y: 2007, c: 1 },
  { name: "Deathspell Omega", genre: "Avant-garde Black Metal", desc: "[Comodín] Riffs construidos sobre tritonos e intervalos que no resuelven, con el compás cambiando dentro de la misma frase y varias guitarras tocando figuras distintas que se cruzan sin encajar del todo, sobre una batería que marca subdivisiones contra el riff en vez de con él. El resultado es que no puedes anticipar dónde cae el golpe siguiente, y eso es intencional. Franceses y anónimos. Los dos primeros discos, Infernal Battles (2000) e Inquisitors of Satan (2002), son black ortodoxo y crudo; el cambio empieza en Si monumentum requires, circumspice (2004), y Fas (2007) y Paracletus (2010) son la cumbre. The Synarchy of Molten Bones (2016), The Furnaces of Palingenesia (2019) y The Long Defeat (2022), más lento y melódico, siguen a gran nivel. Entrada: Paracletus o Fas.", origin: "rec", p: 1, y: 1998, c: 3 },

  // ----- TECH / PROG DEATH que te faltaba -----
  { name: "Children of Bodom", genre: "Melodic Death / Power", desc: "Alexi Laiho y el teclista Janne Wirman se pasaban la voz principal el uno al otro, tocando pasajes neoclásicos al unísono y luego turnándose solos como si fuera un duelo, con líneas tomadas de la armonía barroca y de la menor armónica sobre base de melodeath rápido. Tratar el teclado como segunda guitarra solista casi nadie lo hacía. El mapa: de Something Wild (1997) a Hatebreeder, Follow the Reaper (2000) y Hate Crew Deathroll (2003) está lo mejor; desde Are You Dead Yet? (2005) simplifican hacia riffs más directos. Laiho murió el 29 de diciembre de 2020, a los 41. Entra por Hatebreeder o Follow the Reaper.", origin: "heard", p: 1, y: 1993, c: 2 },
  { name: "Archspire", genre: "Technical Death Metal", desc: "Death técnico canadiense a velocidad imposible y preciso como un reloj, con la voz de Oliver Rae Aleron escupiendo sílabas como una ametralladora. Relentless Mutation (2017), Bleed the Future (2021) y Too Fast to Die (abril de 2026), con Spencer Moore a la batería, son la cumbre; los primeros quedan por debajo. Entrada: Bleed the Future.", p: 2, origin: "rec", pick: true, y: 2009, via: "Tech death" },
  { name: "First Fragment", genre: "Technical Death / Neoclassical", desc: "Death técnico neoclásico de Quebec con guitarra de flamenco y bajo fretless muy presente: shred melódico, armonía barroca y compases cambiantes. Dasein (2016) y Gloire éternelle (2021), la cumbre. Entrada: Gloire éternelle.", p: 2, origin: "rec", pick: true, y: 2007, via: "Tech death" },
  { name: "Alkaloid", genre: "Progressive Death Metal", desc: "Supergrupo alemán de death progresivo y técnico con Hannes Grossmann a la batería y Christian Münzner a la guitarra, ex de Obscura y Necrophagist: temática cósmica, compases cambiantes y ambición compositiva. The Malkuth Grimoire (2015), Liquid Anatomy (2018) y Numen (2023). Entrada: Liquid Anatomy.", p: 2, origin: "rec", pick: true, y: 2014, via: "Tech death" },
  { name: "Black Crown Initiate", genre: "Progressive Death Metal", desc: "Death progresivo de Pensilvania con alternancia de voz limpia y gutural, riffs técnicos y pasajes atmosféricos en la estela de Opeth. The Wreckage of Stars (2014), Selves We Cannot Forgive y Violent Portraits of Doomed Escape (2020). Entrada: Selves We Cannot Forgive.", p: 2, origin: "rec", pick: true, y: 2012, via: "Tech death" },
  { name: "The Faceless", genre: "Progressive Death / Tech", desc: "Death progresivo y técnico californiano: riffs de mucha técnica, voz vocoder y limpia entre guturales y estructuras largas. Akeldama (2006) y Planetary Duality (2008) son la cumbre; Autotheism (2012) y In Becoming a Ghost (2017) bajan algo. Entrada: Planetary Duality.", p: 2, origin: "rec", pick: true, y: 2004, via: "Tech death" },
  { name: "Gorod", genre: "Technical Death Metal", desc: "Death técnico de Burdeos con groove jazzístico y melodía: riffs de Mathieu Pascal que cambian de compás con un aire casi bailable y armonía luminosa dentro de lo extremo. Muy parejos de Leading Vision (2006) y Process of a New Decline a A Maze of Recycled Creeds, Æthra, The Orb (2023) y The Ember Gone (agosto de 2026). Entrada: A Maze of Recycled Creeds.", p: 2, origin: "rec", pick: true, y: 1997, via: "Tech death" },

  // ----- FOLK / MELODEATH ÉPICO -----
  { name: "Ensiferum", genre: "Folk / Power Metal", desc: "Folk/melodeath finlandés épico: melodías de guitarra a dos voces sobre acordeón y coros heroicos, con estructuras largas de aire narrativo, pero cada vez más dentro del molde. Iron (2004) y Victory Songs (2007) son la cumbre; desde Unsung Heroes (2012) se repiten. Winter Storm (2024) es el último. Entrada: Iron o Victory Songs.", origin: "rec", pick: true, p: 3, y: 1995, via: "Melodeath" },

  // ----- METALCORE / POST-HARDCORE MODERNO (huecos clave) -----
  { name: "Thrice", genre: "Post-Hardcore / Alt Rock", desc: "Del post-hardcore técnico al rock experimental y atmosférico, con cambios reales de disco a disco. The Artist in the Ambulance (2003) y Vheissu (2005) son la cumbre, The Alchemy Index (cuatro volúmenes, uno por elemento) su proyecto más ambicioso, y de Beggars a Horizons/East y Horizons/West (2025) mantienen un nivel alto y estable. Entrada: Vheissu.", p: 2, origin: "rec", pick: true, y: 1998, via: "Metalcore" },

  // ----- INSTRUMENTAL PROG / FUSIÓN (tu lado 'instrumental interesante') -----
  { name: "Scale the Summit", genre: "Prog / Instrumental", desc: "Prog metal instrumental sin voz: dos guitarras tocando líneas melódicas independientes que se cruzan, con Mark Michell al bajo haciendo contrapunto en vez de doblar. Todo melódico y paisajístico, sin agresividad. Entrada: The Migration.", p: 3, origin: "rec", pick: true, y: 2004, via: "Instrumental" },
  { name: "The Aristocrats", genre: "Jazz Fusion / Instrumental", desc: "Trío de fusión instrumental con Guthrie Govan a la guitarra, Bryan Beller al bajo y Marco Minnemann a la batería: los tres componen, y los temas saltan de estilo y de compás con mucho humor. Muy parejos: The Aristocrats (2011), Culture Clash (2013), Tres Caballeros (2015), You Know What...? (2019) y Duck (2024). Entrada: Culture Clash.", origin: "rec", pick: true, p: 2, y: 2011, via: "Instrumental" },

  // ----- HIP-HOP ECLÉCTICO (extiende tu RM / Agust D / Hamilton) -----
  { name: "Kendrick Lamar", genre: "Hip-Hop / Jazz Rap", desc: "To Pimp a Butterfly usa más músicos en vivo que samples: Terrace Martin dirigiendo, con Robert Glasper al piano, Ambrose Akinmusire a la trompeta, Kamasi Washington al saxo (y arreglando y dirigiendo las cuerdas) y Thundercat al bajo, los tres últimos ya en el catálogo. Solos de jazz que aparecen sin avisar, cambios de compás dentro del tema y grooves que respiran como banda tocando en directo en vez de repetir un loop. El mapa: Section.80 (2011) abre; good kid, m.A.A.d city (2012), To Pimp a Butterfly (2015), la cumbre, untitled unmastered. (2016) y DAMN. (2017) siguen arriba; Mr. Morale & the Big Steppers (2022) y GNX (2024) son más directos. Entra por To Pimp a Butterfly.", origin: "rec", p: 1, y: 2011, c: 1 },
  { name: "Tyler, the Creator", genre: "Hip-Hop / Neo-Soul", desc: "Arregla y produce él, y cada disco monta una paleta distinta: IGOR va de sintetizador saturado y coros, Flower Boy usa armonía de jazz con acordes extendidos, y CHROMAKOPIA vuelve a lo percusivo. El mapa: Bastard (2009), Goblin (2011) y Wolf (2013) son la etapa cruda; Cherry Bomb (2015) abre el giro; Flower Boy (2017), IGOR (2019) y Call Me If You Get Lost (2021) son la cumbre; CHROMAKOPIA (2024) se mantiene, y DON'T TAP THE GLASS (2025) es un disco corto de baile. Entrada: IGOR.", origin: "rec", pick: true, p: 2, y: 2009, via: "RM/BTS", c: 1 },
  { name: "Death Grips", genre: "Experimental Hip-Hop", desc: "[Comodín] Quien está a la batería es Zach Hill, el mismo de Hella, y no programa, toca en vivo a una densidad brutal por debajo de bases distorsionadas hasta el recorte digital, con la voz de MC Ride gritada y saturada al mismo nivel que los instrumentos en vez de por encima. La mezcla está deliberadamente en rojo. Abrasivo y agotador a propósito. El mapa: Exmilitary (2011), The Money Store (2012) y No Love Deep Web (2012) son la cumbre; Government Plates (2013), The Powers That B (2015), Bottomless Pit (2016) y Year of the Snitch (2018) siguen; en noviembre de 2025 anunciaron que graban disco nuevo. Entra por The Money Store.", origin: "rec", p: 2, y: 2010, c: 3 },
  { name: "clipping.", genre: "Experimental Hip-Hop", desc: "Rap sobre bases hechas con ruido y grabaciones de campo en vez de samples musicales: hay temas construidos solo con estática, silbidos o el sonido de un incendio, y Daveed Diggs rapea encima a velocidad muy alta. Conceptual y de ciencia ficción. El mapa: CLPPNG (2014) abre; Splendor & Misery (2016) es la cumbre; There Existed an Addiction to Blood (2019), Visions of Bodies Being Burned (2020) y Dead Channel Sky (2024) siguen arriba. Entrada: Splendor & Misery.", origin: "rec", pick: true, p: 2, y: 2010, via: "RM/BTS" },
  { name: "JPEGMAFIA", genre: "Experimental Hip-Hop", desc: "Se produce él todo, y las bases cambian de estructura a mitad de tema: cortes secos, samples que entran desafinados y silencios colocados donde debería seguir el ritmo. El mapa: Black Ben Carson (2016) abre; Veteran (2018) y All My Heroes Are Cornballs (2019) son la cumbre; LP! (2021), Scaring the Hoes (2023, con Danny Brown) e I Lay Down My Life for You (2024) siguen arriba. Entrada: All My Heroes Are Cornballs.", origin: "rec", pick: true, p: 2, y: 2015, via: "RM/BTS", c: 1 },

  // ----- K-ROCK / K-ECLÉCTICO (extiende tu BTS / RM) -----

  // ----- SYMPHONIC / GOTHIC CON VOZ FEMENINA (extiende tu filtro ♀) -----
  { name: "Within Temptation", genre: "Symphonic / Gothic Metal", desc: "Sinfónico gótico holandés con la voz de Sharon den Adel, épico y cinematográfico, cada vez más cerca del pop rock de estadio. Mother Earth (2000) y The Silent Force (2004) son lo mejor; desde Hydra la orquesta se retira y quedan los estribillos. Bleed Out (2023) es el último. Entrada: Mother Earth. (voz femenina)", origin: "rec", pick: true, female: true, p: 3, y: 1996, via: "Symphonic fem" },
  { name: "The Gathering", genre: "Atmospheric / Symphonic Rock", desc: "Cambiaron de lenguaje dos veces y en cada cambio se quedaron con lo que funcionaba. Con Anneke van Giersbergen pasaron del death/doom a un rock atmosférico de guitarras en capas y tempos lentos, y desde How to Measure a Planet? (1998), con una pista titular de casi media hora, se meten en texturas de trip-hop y post-rock donde el ritmo es lo que hipnotiza. El mapa: Always (1992) y Almost a Dance son death/doom convencional y flojo; de Mandylion (1995) a Nighttime Birds, How to Measure a Planet?, if_then_else (2000), Souvenirs (2003) y Home (2006) está lo mejor; con Silje Wergeland a la voz, The West Pole (2009), Disclosure (2012) y Beautiful Distortion (2022) son más suaves y se mantienen. Entra por Mandylion o How to Measure a Planet?. (voz femenina)", origin: "rec", pick: true, female: true, p: 2, y: 1989, via: "Symphonic fem" },
  { name: "Lacuna Coil", genre: "Gothic / Symphonic Metal", desc: "Gótico italiano a dos voces, Cristina Scabbia y Andrea Ferro, atmosférico y pegadizo, pero de canción corta y riff sencillo. Comalies (2002) es lo mejor, y lo regrabaron entero como Comalies XX en 2022. Sleepless Empire (2025) es el último. Entrada: Comalies. (voz femenina)", origin: "rec", female: true, p: 3, y: 1994, via: "Symphonic fem" },
  { name: "Tarja", genre: "Symphonic Metal", desc: "La ex-voz operística de Nightwish en solitario: soprano de formación clásica sobre metal sinfónico con orquesta, más dramático y menos pop que su etapa en la banda. My Winter Storm (2007) y What Lies Beneath (2010) son lo mejor; Frisson noir (2026) es el último. Entrada: My Winter Storm. (voz femenina)", origin: "rec", female: true, p: 3, y: 2005, via: "Symphonic fem" },

  // ----- EXPERIMENTAL / MATH / ART ROCK (extiende alt-J / Radiohead / King Gizzard) -----
  { name: "black midi", genre: "Experimental Rock", desc: "Rock experimental londinense de math rock, jazz y prog en caída libre, con Morgan Simpson a la batería llevando la banda: cambia de subdivisión y de dinámica cada pocos compases y hace de motor compositivo, no de base. Tres discos, Schlagenheim (2019), Cavalcade (2021) y Hellfire (2022), cada uno más escrito y más teatral que el anterior, sin bajar. En agosto de 2024 anunciaron un parón indefinido y Geordie Greep siguió en solitario con The New Sound. Entrada: Cavalcade, luego Hellfire.", p: 1, origin: "rec", pick: true, y: 2017, via: "Radiohead/alt-J", c: 1 },
  { name: "Black Country, New Road", genre: "Experimental / Chamber Rock", desc: "Rock de cámara londinense: violín, saxo, piano y dos guitarras en crescendos largos que cruzan post-rock, klezmer y folk. For the First Time y Ants from Up There (los dos de 2022) son con Isaac Wood a la voz; tras su marcha, Forever Howlong (2025) reparte la voz entre tres miembros y gira hacia algo más barroco y luminoso. Entrada: Ants from Up There.", p: 2, origin: "rec", pick: true, y: 2018, via: "Radiohead/alt-J" },
  { name: "Battles", genre: "Math Rock / Experimental", desc: "Math rock instrumental hipnótico: bucles de guitarra y teclado construidos en directo y superpuestos hasta que el patrón se desfasa, con John Stanier tocando contra esos loops con una precisión de máquina. El mapa: los EP B y C (2004) y Mirrored (2007), con la voz tratada de Tyondai Braxton, son la cumbre; Gloss Drop (2011), ya en trío y con invitados a la voz, y La Di Da Di (2015), instrumental, se mantienen; Juice B Crypts (2019), como dúo, es el más irregular. Entrada: Mirrored.", origin: "rec", pick: true, p: 2, y: 2002, via: "Radiohead/alt-J" },

  // ----- DARKSYNTH (extiende tu Dance with the Dead) -----
  { name: "Perturbator", genre: "Darksynth / Synthwave", desc: "Arpegios de sintetizador sobre bombo a negras, capas de pads oscuros y estructura de estrofa y estribillo sin voz. Está muy bien producido y la atmósfera cyberpunk funciona, pero el género es pastiche ochentero por diseño: el atractivo es la estética y la nostalgia, no la escritura. Entra por The Uncanny Valley.", origin: "rec", p: 3, y: 2012, c: 2 },
  { name: "Carpenter Brut", genre: "Darksynth / Synthwave", desc: "Bajado con el resto del synthwave. Es el más agresivo de los tres: mete guitarras distorsionadas y batería real encima del sintetizador, y algunos temas tiran casi a heavy. Pero la base sigue siendo la misma fórmula de arpegio y bombo a negras, con la película ochentera como referente principal. Entretenidísimo, poco exigente. Entra por Leather Teeth.", origin: "rec", p: 3, y: 2012, c: 2 },

  // ----- TEATRAL / ECLÉCTICO EXTRA -----
];

// ===========================================================================
// === TANDA 3 (junio 2026) — EL REPASO: 2ª vuelta de cada rama + barrido =====
// internacional. Backlog que quedó pendiente del chat "Musica". Sin repetir
// nada del catálogo ni de NEW_RECS/TANDA_2. Marco de 3 categorías aplicado.
// ===========================================================================
const TANDA_3 = [
  // ----- MUSICALES (2ª vuelta + internacionales) -----
  { name: "Natasha, Pierre & the Great Comet of 1812", genre: "Musical / Electropop Opera", desc: "Ópera electropop sobre un fragmento de Guerra y Paz, con folk, clásica rusa, rock, electrónica e indie conviviendo en la misma obra y orquestaciones densas. La electrónica es teatral, no de pista de baile, y la banda toca repartida entre el público. ▸ Versión: el elenco original Off-Broadway de 2013 (con Phillipa Soo, la más completa); el de Broadway de 2016 trae a Josh Groban como Pierre.", origin: "rec", pick: true, p: 1, y: 2012, via: "Musicales", c: 1 },
  { name: "Ride the Cyclone", genre: "Musical / Pastiche", desc: "Musical de culto oscuro donde cada canción es el pastiche de un género distinto (cabaret, synth-pop, balada ucraniana, hip-hop); el eclecticismo es la gracia, pero cada número se queda en su molde. ▸ Versión: la grabación del elenco original de 2016; buena parte de su culto creció desde ahí.", origin: "rec", pick: true, p: 3, y: 2015, via: "Musicales", c: 1 },
  { name: "Caroline, or Change", genre: "Musical (Jeanine Tesori)", desc: "Cantado de principio a fin, y cada personaje tiene su propio idioma musical: la lavadora canta Motown, la radio es un trío de coristas a lo Supremes, la secadora es soul, la protagonista canta blues y spiritual, y la familia judía trae el klezmer. Jeanine Tesori hace convivir esas músicas dentro de la misma escena en vez de repartirlas por números. Entrada: Lot's Wife, el número final de Caroline. ▸ Versión: el Original Broadway Cast de 2004 (Tonya Pinkins); el revival de 2021 con Sharon D. Clarke es igual de aclamado.", origin: "rec", pick: true, female: true, p: 2, y: 2003, via: "Musicales", c: 1 },
  { name: "Into the Woods", genre: "Musical (Sondheim)", desc: "Los personajes tienen motivos propios que se transforman y se cruzan, así que en los números de conjunto suenan varias líneas melódicas distintas a la vez y cada una identifica a quien la canta. El segundo acto desmonta el cuento que el primero construyó, y la música hace lo mismo con sus temas. Sondheim. ▸ Versión: el Original Broadway Cast de 1987 (Bernadette Peters, completo); la película de Disney de 2014 recorta canciones.", origin: "rec", pick: true, p: 2, y: 1987, via: "Musicales" },
  { name: "Sunday in the Park with George", genre: "Musical (Sondheim)", desc: "La escritura imita la técnica del cuadro: notas cortas y repetidas que por separado no son melodía y que forman la textura al superponerse, igual que los puntos de Seurat forman la imagen. Y el segundo acto cambia de época y de lenguaje musical entero. Sondheim. ▸ Versión: el Original Broadway Cast de 1984 (Mandy Patinkin y Bernadette Peters, la definitiva).", origin: "rec", pick: true, p: 1, y: 1984, via: "Musicales" },
  { name: "Assassins", genre: "Musical (Sondheim)", desc: "Sondheim oscuro: cada asesino de presidente canta en el estilo musical americano de su época, así que la partitura es un recorrido por la música del país: marcha de Sousa, balada de bluegrass para Booth, cakewalk para Guiteau, cuarteto de barbería en The Gun Song y balada pop de los setenta en Unworthy of Your Love, hasta Another National Anthem, donde los asesinos cantan juntos contra el estribillo del narrador. Entrada: The Ballad of Booth. ▸ Versión: el revival de Broadway de 2004 (más completo, añade Something Just Broke); o el Off-Broadway original de 1990.", origin: "rec", pick: true, p: 2, y: 1990, via: "Musicales" },
  { name: "Adam Guettel", genre: "Musical / Compositor", desc: "De los compositores de musical más sofisticados en armonía: acordes extendidos que no resuelven donde se espera, melodías de intervalos amplios y difíciles de cantar, y orquestación de cámara. El mapa: Floyd Collins (1996) cruza bluegrass y folk apalache con disonancia, con la voz del protagonista respondida por su propio eco dentro de la cueva; Myths and Hymns (1998) es un ciclo de canciones sobre himnos antiguos; The Light in the Piazza (2005) es la cumbre; Days of Wine and Roses (2023) es más jazzístico e íntimo. Floyd Collins llegó por fin a Broadway en 2025. ▸ Versión: empieza por The Light in the Piazza (Original Broadway Cast de 2005), luego Floyd Collins (elenco original).", origin: "rec", pick: true, p: 2, y: 1996, via: "Musicales" },
  { name: "Jason Robert Brown", genre: "Musical / Compositor", desc: "Compositor y pianista que escribe partes de piano muy exigentes, casi de concierto, con armonía de jazz y pop y ritmos sincopados que empujan la canción en vez de acompañarla. El mapa: Songs for a New World (1995) es un ciclo de canciones sueltas; Parade (1998) es lo más ambicioso, con marchas, blues y góspel del sur de Estados Unidos; The Last Five Years (2001) es la obra de cámara; 13 (2008) y Honeymoon in Vegas son menores; The Bridges of Madison County (2014) es lo más cercano a la ópera, y The Connector (2024) vuelve al formato de banda. ▸ Versión: empieza por The Last Five Years (elenco Off-Broadway de 2002); para Parade, el revival de 2023 con Ben Platt o el original de 1998.", origin: "rec", pick: true, p: 2, y: 1995, via: "Musicales" },
  { name: "Next to Normal", genre: "Musical / Rock", desc: "Tom Kitt escribe rock dramático sobre salud mental con motivos que vuelven y números que se superponen, sólido y muy bien construido, aunque el lenguaje es de pop-rock. Ganó el Pulitzer en 2010. Entrada: I Miss the Mountains. ▸ Versión: el Original Broadway Cast Recording de 2009 (Alice Ripley, la definitiva).", origin: "rec", pick: true, p: 3, y: 2008, via: "Musicales" },
  { name: "The Band's Visit", genre: "Musical / Jazz-Árabe", desc: "David Yazbek escribe con música árabe dentro del musical, no como decorado: oud, darbuka y violín tocan en los modos del maqam para la banda egipcia, y las canciones de los israelíes van en jazz y pop, así que los dos mundos se oyen distintos hasta que se mezclan. Silencios largos y dinámica muy contenida. Entrada: Omar Sharif, luego Answer Me. ▸ Versión: el Original Broadway Cast Recording de 2018 (Katrina Lenk y Tony Shalhoub).", origin: "rec", pick: true, p: 2, y: 2016, via: "Musicales" },
  { name: "The Rocky Horror Show", genre: "Musical / Glam Rock", desc: "Glam rock teatral camp con devoción al rock and roll de los cincuenta y a la ciencia ficción de serie B, con banda de rock en vivo y números que parodian estilos concretos. ▸ Versión: el soundtrack de la película de 1975 con Tim Curry, la icónica.", origin: "rec", pick: true, p: 3, y: 1973, via: "Musicales" },
  { name: "Little Shop of Horrors", genre: "Musical (Alan Menken)", desc: "Comedia de terror con planta carnívora, escrita por Alan Menken en clave doo-wop, Motown y rock sesentero, con un trío de coristas que hace de coro griego comentando la acción. ▸ Versión: el Original Off-Broadway Cast de 1982 (Ellen Greene); el soundtrack de la película de 1986 (también Ellen Greene) es otra gran opción.", origin: "rec", pick: true, female: true, p: 3, y: 1982, via: "Musicales" },
  { name: "Bat Out of Hell: The Musical", genre: "Musical / Rock Opera", desc: "Recoge las canciones de Jim Steinman (el de Meat Loaf): bombast rock operística. Teatralidad-Queen al máximo. ▸ Versión: el Original Cast de 2018; pero ojo, la fuente son los álbumes 'Bat Out of Hell' de Meat Loaf (ya en la página), superiores al musical.", origin: "rec", pick: true, p: 3, y: 2017, via: "Musicales" },
  { name: "Starmania", genre: "Musical / Ópera Rock (FR)", desc: "Ópera rock francesa de Michel Berger y Luc Plamondon, ambiciosa de tema y melódica, pero de canción pop de radio. Le blues du businessman y Les uns contre les autres son lo mejor. ▸ Versión: el álbum concepto original de 1978 (Daniel Balavoine, France Gall, la clásica); el revival de 2022 para una producción moderna.", origin: "rec", pick: true, p: 3, y: 1979, via: "Musicales" },
  { name: "Mozart, l'opéra rock", genre: "Musical / Rock (FR)", desc: "Musical de rock francés sobre Mozart que cita sus temas dentro de canciones pop; el cruce con lo clásico es de superficie. L'Assasymphonie es lo mejor. ▸ Versión: la grabación del elenco original de 2009.", origin: "rec", pick: true, p: 3, y: 2009, via: "Musicales", c: 2 },
  { name: "Tanz der Vampire", genre: "Musical / Gótico (DE)", desc: "Musical gótico de vampiros con música de Jim Steinman: bombast teatral, coros enormes y baladas de estructura larga reutilizando material de su repertorio de rock. ▸ Versión: el elenco original de Viena de 1997 (en alemán, la definitiva); evita la adaptación de Broadway de 2002 (Dance of the Vampires), que fracasó.", origin: "rec", pick: true, p: 3, y: 1997, via: "Musicales" },
  { name: "Elisabeth", genre: "Musical / Gótico (AT)", desc: "Musical vienés de Sylvester Levay y Michael Kunze, oscuro y gótico, con la Muerte como personaje; baladas de pop europeo con orquesta, más drama que escritura. Entrada: Ich gehör nur mir. ▸ Versión: el elenco original de Viena de 1992 (Pia Douwes y Uwe Kröger, la clásica); el revival vienés de 2005 también es muy querido.", origin: "rec", pick: true, p: 3, y: 1992, via: "Musicales" },

  // ----- QUEEN PESADO (2ª vuelta + internacionales) -----
  { name: "Rhapsody of Fire", genre: "Symphonic Power Metal (IT)", desc: "Power sinfónico italiano con orquesta, coros, narración de fantasía y shred neoclásico: bombástico y bien arreglado, pero de melodía de plantilla. Symphony of Enchanted Lands (1998) y Power of the Dragonflame (2002) son lo mejor; tras las salidas de Luca Turilli y Fabio Lione sigue Alex Staropoli, y Challenge the Wind (2024) es el último. Entrada: Symphony of Enchanted Lands.", origin: "rec", pick: true, p: 3, y: 1993, via: "Queen pesado" },
  { name: "Powerwolf", genre: "Power Metal (DE)", desc: "Power alemán con órgano de iglesia, coros de himno y estribillo de estadio; el molde es siempre el mismo. Blessed & Possessed (2015) es lo más representativo. Wake Up the Wicked (2024) es el último. Entrada: Blessed & Possessed.", origin: "rec", pick: true, p: 3, y: 2004, via: "Queen pesado" },
  { name: "Edguy", genre: "Power Metal (DE)", desc: "Power melódico alemán de Tobias Sammet, teatral y con humor, de gancho fácil y estructura convencional. Theater of Salvation (1999) y Hellfire Club (2004) son lo mejor; no sacan disco desde Space Police (2014). Entrada: Hellfire Club.", origin: "rec", pick: true, p: 3, y: 1992, via: "Queen pesado" },
  { name: "Beast in Black", genre: "Melodic / Power Metal (FI)", desc: "Heavy/power finlandés que cruza power con synth ochentero y estribillos enormes: muy pegadizo, de molde. Berserker (2017) es lo mejor. Su cuarto disco, Fear the Beast, sale en noviembre de 2026. Entrada: Berserker.", origin: "rec", pick: true, p: 3, y: 2015, via: "Queen pesado" },
  { name: "Dimmu Borgir", genre: "Symphonic Black Metal (NO)", desc: "Black sinfónico noruego, grandioso y bombástico, con orquesta real desde Puritanical Euphoric Misanthropia (2001); la orquesta pesa más que la escritura del riff. Enthrone Darkness Triumphant (1997) y Death Cult Armageddon (2003) son lo mejor. Grand Serpent Rising, de mayo de 2026, es su primer disco en ocho años. Entrada: Enthrone Darkness Triumphant.", origin: "rec", pick: true, p: 3, y: 1993, via: "Queen pesado" },
  { name: "Haggard", genre: "Symphonic / Classical Metal (DE)", desc: "Colectivo de hasta una veintena de músicos que escribe death/doom con cuerda, viento de madera, clave y coro clásico reales tocando líneas de inspiración medieval y barroca en contrapunto con las guitarras, no una orquesta de teclado encima. Pasan de pasajes de cámara a riff pesado dentro de la misma pieza, y las voces alternan soprano, coro y gutural. El mapa: cuatro discos muy parejos, And Thou Shalt Trust... the Seer (1997), Awaking the Centuries (2000), la cumbre, Eppur Si Muove (2004) y Tales of Ithiria (2008); no han sacado disco largo desde entonces. Entrada: Awaking the Centuries.", origin: "rec", pick: true, p: 2, y: 1991, via: "Queen pesado", c: 2 },
  { name: "Stolen Babies", genre: "Avant-garde Metal", desc: "Metal avant teatral de Los Ángeles con acordeón, la voz versátil de Dominique Persi y estética de circo oscuro: cabaret y metal alternando dentro del tema. There Be Squabbles Ahead (2006) y Naught (2012). Entrada: There Be Squabbles Ahead.", p: 3, origin: "rec", pick: true, female: true, y: 2002, via: "Queen pesado" },
  { name: "Carach Angren", genre: "Symphonic Black Metal (NL)", desc: "Black sinfónico holandés escrito como banda sonora: la orquestación de teclado, cuerda y coro cambia de escena dentro del tema, y el black va detrás marcando el ritmo de la narración; cada disco es una historia de fantasmas completa. El mapa: Lammendam (2008), Death Came Through a Phantom Ship (2010), Where the Corpses Sink Forever (2012) y This Is No Fairytale (2015) son lo mejor; Dance and Laugh Amongst the Rotten (2017) y Franckensteina Strataemontanus (2020), el último, simplifican un poco. Entrada: Where the Corpses Sink Forever.", origin: "rec", pick: true, p: 2, y: 2003, via: "Queen pesado" },
  { name: "Delain", genre: "Symphonic Metal (NL)", desc: "Sinfónico melódico holandés, luminoso y de gancho vocal, con canciones cortas de estribillo. Lucidity (2006) y April Rain (2009) son lo mejor; tras el cambio de formación de 2021, Dark Waters (2023), con Diana Leah a la voz, es el último. Entrada: April Rain. (voz femenina)", origin: "rec", pick: true, female: true, p: 3, y: 2002, via: "Queen pesado" },
  { name: "Xandria", genre: "Symphonic Metal (DE)", desc: "Sinfónico alemán operístico y orquestal, con soprano; bien producido y de plantilla, cerca de Nightwish. Tras rehacer la formación entera volvieron con The Wonders Still Awaiting (2023), y Eclipse (2026) es el último. Entrada: Neverworld's End. (voz femenina)", origin: "rec", pick: true, female: true, p: 3, y: 1997, via: "Queen pesado" },
  { name: "Versailles", genre: "Symphonic Power / Visual Kei (JP)", desc: "Visual kei japonés barroco y teatral, con guitarras gemelas neoclásicas en armonía y arreglos orquestales; espectacular, pero de estructura de canción convencional. Jubilee (2010) es lo mejor. Entrada: Jubilee.", origin: "rec", pick: true, p: 3, y: 2007, via: "Queen pesado" },
  { name: "Devil Doll", genre: "Avant-garde Rock Opera (SI/IT)", desc: "[Comodín] Cada disco es UNA sola pieza de entre cuarenta y setenta minutos, sin cortes, escrita por Mr. Doctor para banda de rock más orquesta, coro y piano, con la voz pasando de susurro a grito y de narración hablada a canto lírico, en inglés e italiano mezclados. Del primer álbum se prensó una única copia. La estructura es de ópera, no de rock. El mapa: The Girl Who Was... Death (1989), Eliogabalus (1990), Sacrilegium (1992), The Sacrilege of Fatal Arms (1993) y Dies Irae (1996), la cumbre. Entrada: Sacrilegium o Dies Irae.", p: 2, origin: "rec", pick: true, y: 1987, via: "Queen pesado", c: 3 },
  { name: "Tristania", genre: "Symphonic / Gothic Metal (NO)", desc: "Gótico sinfónico noruego con soprano, voz limpia masculina y gutural en capas, y coro y violín reales en los primeros discos. Beyond the Veil (1999) es la cumbre; después se vuelven más convencionales. No sacan disco desde Darkest White (2013). Entrada: Beyond the Veil. (voz femenina)", origin: "rec", pick: true, female: true, p: 3, y: 1996, via: "Queen pesado" },
  { name: "Twilight Force", genre: "Symphonic Power Metal (SE)", desc: "Power sinfónico sueco de fantasía, bombástico y melódico al extremo, con orquestación y guitarras neoclásicas, de molde. Heroes of Mighty Magic (2016) es lo más representativo; At the Heart of Wintervale (2023) es el último. Entrada: Heroes of Mighty Magic.", origin: "rec", pick: true, p: 3, y: 2011, via: "Queen pesado" },

  // ----- GOJIRA (2ª vuelta + internacionales) -----
  { name: "Cave In", genre: "Alt / Space / Prog Metal", desc: "De Boston, y cambiaron de piel de verdad: del metalcore caótico de Until Your Heart Stops (1998) al space rock de Jupiter (2000), al rock alternativo y de vuelta al peso en Heavy Pendulum (2022). El bajista Caleb Scofield murió en 2018 y su último material salió en Final Transmission. Entrada: Jupiter.", p: 2, origin: "rec", pick: true, y: 1995, via: "Gojira", c: 1 },
  { name: "Textures", genre: "Prog / Djent (NL)", desc: "Holandeses de riff percusivo y groove sincopado, de la órbita de Meshuggah y Gojira, con capas atmosféricas y voz que alterna limpio y gutural; Silhouettes (2008) y Dualism (2011) son su cumbre. Volvieron tras una década con Genotype (enero de 2026). Entrada: Silhouettes.", p: 2, origin: "rec", pick: true, y: 2001, via: "Gojira" },
  { name: "Oceans of Slumber", genre: "Prog / Doom Metal", desc: "De Houston, fundada por el baterista Dobber Beverly, que compone desde la batería con dinámica de doom y fraseo técnico; la voz de Cammie Beverly lleva el peso melódico sobre prog y doom de aire gótico sureño. El mapa: Aetherial (2013) es más prog metal técnico; Winter (2016) y The Banished Heart (2018) son la cumbre; Oceans of Slumber (2020) y Starlight and Ash (2022), más sureño y gótico, bajan algo, y Where Gods Fear to Speak (2024) vuelve a endurecerse. Entrada: The Banished Heart.", p: 2, origin: "rec", pick: true, female: true, y: 2011, via: "Gojira" },
  { name: "Hypno5e", genre: "Cinematic Post-Metal (FR)", desc: "Metal de Montpellier cinematográfico y complejo: riffs pesados con acentos desplazados y cambios de compás, pasajes de guitarra acústica de aire clásico y español, y muestras de diálogos de películas que hilan cada disco como una narración. Muy parejos y cada uno con su concepto: Acid Mist Tomorrow (2012), Shores of the Abstract Line (2016), Alba - Les ombres errantes (2018), una banda sonora acústica, A Distant (Dark) Source (2019), Sheol (2023) y Trame Noire (2026). Entrada: Acid Mist Tomorrow.", origin: "rec", pick: true, p: 1, y: 2003, via: "Gojira" },
  { name: "Astronoid", genre: "Dream Thrash / Blackgaze", desc: "Thrash de velocidad extrema con atmósfera de shoegaze y voces limpias soñadoras, pesado y bello a la vez. Entrada: Air.", origin: "rec", pick: true, p: 3, y: 2012, via: "Gojira" },
  { name: "Toundra", genre: "Post-Rock / Post-Metal (ES)", desc: "Post-rock y post-metal instrumental madrileño, cinematográfico y pesado, con riffs de verdad y no solo crescendos. II (2010), III (2012) y IV (2015) son lo mejor. Entrada: III.", origin: "rec", pick: true, p: 2, y: 2007, via: "Gojira" },
  { name: "Jardín de la Croix", genre: "Math / Post-Rock (ES)", desc: "Math rock instrumental madrileño de temas largos: guitarras armónicas en capas que se entrelazan sobre una batería que cambia de métrica dentro del tema, con desarrollos que crecen hacia el post-rock. El mapa: Ocean Cosmonauts (2011), 187 Steps to Cross the Universe (2013) y Circadia (2016). Entrada: 187 Steps to Cross the Universe.", origin: "rec", pick: true, p: 2, y: 2008, via: "Gojira" },
  { name: "sleepmakeswaves", genre: "Post-Rock / Metal (AU)", desc: "Post-rock y post-metal instrumental australiano, dinámico, de lo etéreo a lo demoledor, dentro de la curva clásica del género. Entrada: Love of Cartography.", origin: "rec", pick: true, p: 3, y: 2006, via: "Gojira" },

  // ----- BEHEMOTH (2ª vuelta + internacionales / escena polaca) -----
  { name: "Tribulation", genre: "Blackened Death / Gothic (SE)", desc: "De death crudo a un death gótico y teatral, casi rock gótico con guturales: guitarras melódicas en armonía, órgano y atmósfera de cine de terror antiguo. Cada disco se aleja del anterior, de The Formulas of Death (2013) a The Children of the Night (2015), Down Below, Where the Gloom Becomes Sound y Sub Rosa in Æternum (2024). Entrada: The Children of the Night.", p: 2, origin: "rec", pick: true, y: 2005, via: "Behemoth", c: 1 },
  { name: "Emperor", genre: "Symphonic Black Metal (NO)", desc: "Ihsahn escribe riffs de trémolo que cambian de armonía cada pocos compases en lugar de repetir un patrón, con teclados que doblan y contradicen a la guitarra a la vez, y estructuras que se acumulan sin volver al principio; la batería de Trym va a una densidad que tapa el compás a propósito. Anthems to the Welkin at Dusk está grabado como un muro donde cuesta separar los instrumentos, y eso es intencional. El mapa: cuatro discos y ninguno sobra. In the Nightside Eclipse (1994) y Anthems (1997) son la cumbre; IX Equilibrium (1999) va más directo, con más riff de thrash, y Prometheus (2001), escrito casi entero por Ihsahn, se vuelve progresivo y abre lo que haría después en solitario. Desde entonces, solo reuniones en directo. Entra por In the Nightside Eclipse, luego Anthems.", origin: "rec", p: 1, y: 1991, c: 2 },
  { name: "Nile", genre: "Technical Death Metal", desc: "Death técnico con temática e instrumentación del antiguo Egipto: pasajes de escalas orientales, coros rituales y la batería de George Kollias, de las más rápidas y precisas del género. Black Seeds of Vengeance (2000), In Their Darkened Shrines y Annihilation of the Wicked (2005) son la cumbre, At the Gate of Sethu (2012) el bajón, y The Underworld Awaits Us All (2024) recupera el nivel. Entrada: Annihilation of the Wicked.", p: 2, origin: "rec", pick: true, y: 1993, via: "Behemoth" },
  { name: "Mgła", genre: "Atmospheric Black Metal (PL)", desc: "Black metal atmosférico polaco muy cohesivo: riffs de trémolo melódicos y melancólicos repetidos hasta la hipnosis, con la batería de Darkside, muy musical y llena de redobles, como motor. With Hearts Toward None (2012), Exercises in Futility (2015) y Age of Excuse (2019). Entrada: Exercises in Futility.", origin: "rec", pick: true, p: 2, y: 2000, via: "Behemoth" },
  { name: "Dissection", genre: "Melodic Blackened Death (SE)", desc: "Death y black melódico sueco: trémolos de guitarra con melodías de raíz clásica sobre blast beats, frío y majestuoso. The Somberlain (1993) y Storm of the Light's Bane (1995) son la obra fuerte; Reinkaos (2006) queda muy por debajo. Entrada: Storm of the Light's Bane.", p: 2, origin: "rec", pick: true, y: 1989, via: "Behemoth" },
  { name: "Watain", genre: "Black Metal (SE)", desc: "Black metal sueco ortodoxo y ritualista, oscuro y ceremonial, de riffs rápidos bien escritos dentro del molde. Casus Luciferi (2003) y Lawless Darkness (2010) son lo mejor. Entrada: Lawless Darkness.", origin: "rec", pick: true, p: 3, y: 1998, via: "Behemoth" },
  { name: "Immolation", genre: "Dissonant Death Metal", desc: "Death disonante de Nueva York: los riffs de Robert Vigna se retuercen en intervalos raros y cambios de tempo, con armonías torcidas a propósito, y la batería (Steve Shalaty desde 2003) sigue esos giros en vez de marcar. Doce discos sin un bajón serio, de Dawn of Possession (1991) y Here in After a Close to a World Below (2000), Unholy Cult, Majesty and Decay, Atonement (2017), Acts of God y Descent (abril de 2026). Entrada: Close to a World Below.", p: 1, origin: "rec", pick: true, y: 1988, via: "Behemoth" },
  { name: "Myrkur", genre: "Atmospheric Black Metal (DK)", desc: "Black atmosférico y folk nórdico de Amalie Bruun, que alterna lo etéreo con la crudeza del black y arreglos folk. Mareridt (2017) y Folkesange (2020). Entrada: Mareridt.", origin: "rec", pick: true, female: true, p: 3, y: 2014, via: "Behemoth" },
  { name: "Batushka", genre: "Ritual Black Metal (PL)", desc: "[Comodín] Black metal con cantos ortodoxos eslavos, estructurado como una liturgia: teatral, hipnótico y ceremonial. Litourgiya (2015) es el disco que importa; después la banda se partió en dos por una disputa entre sus miembros. Entrada: Litourgiya.", origin: "rec", pick: true, p: 3, y: 2015, via: "Behemoth", c: 3 },
  { name: "Schammasch", genre: "Avant-garde Black Metal (CH)", desc: "Black de vanguardia suizo de tono ritual: del black extremo a pasajes ambientales y meditativos, con coros y estructuras largas. Triangle (2016) es un triple que recorre ese arco entero. El mapa: Sic Lvceat Lvx (2010) es black más convencional; Contradiction (2014), Triangle (2016) y Hearts of No Light (2019) son la cumbre, y The Maldoror Chants: Old Ocean (2024) sigue esa línea. Entrada: Triangle.", origin: "rec", pick: true, p: 2, y: 2009, via: "Behemoth" },
  { name: "Chelsea Wolfe", genre: "Doom / Gothic Rock", desc: "Doom, gótico y folk atmosférico y oscuro con su voz hipnótica, de producción densa pero de escritura sencilla. Abyss (2015) y She Reaches Out to She Reaches Out to She (2024). Entrada: Abyss.", origin: "rec", pick: true, female: true, p: 3, y: 2010, via: "Behemoth" },
  { name: "Hate", genre: "Blackened Death Metal (PL)", desc: "Blackened death polaco majestuoso, de trémolos y blast beats con melodías oscuras, en la línea de Behemoth. Anaclasis (2005) y Morphosis son lo mejor. Entrada: Anaclasis.", origin: "rec", pick: true, p: 3, y: 1990, via: "Behemoth" },
  { name: "Vader", genre: "Death Metal (PL)", desc: "Death metal clásico polaco, veloz y contundente, muy parejo durante tres décadas: riffs de thrash acelerado y batería a toda velocidad dentro de una estructura de manual. The Ultimate Incantation (1992), De Profundis (1995) y Litany (2000) son lo mejor. Entrada: De Profundis.", origin: "rec", pick: true, p: 3, y: 1983, via: "Behemoth" },
  { name: "Azarath", genre: "Blackened Death Metal (PL)", desc: "Blackened death polaco del batería de Behemoth, Inferno: brutal, veloz y muy bien tocado, dentro del molde. Entrada: Blasphemers' Maledictions.", origin: "rec", pick: true, p: 3, y: 1998, via: "Behemoth" },
  { name: "Blut Aus Nord", genre: "Experimental Black Metal (FR)", desc: "Black metal experimental francés, prácticamente de una sola persona, Vindsval: guitarras disonantes que se deforman como líquido, cajas de ritmos industriales y, según el disco, atmósfera o ruido. De The Work Which Transforms God (2003) a la trilogía 777 (2011-2012), con un disco metálico, uno industrial y uno atmosférico, Hallucinogen (2019) y Disharmonium (2022); la serie Memoria Vetusta es su cara más melódica. Entrada: The Work Which Transforms God.", origin: "rec", p: 1, y: 1995, c: 1 },
  { name: "The Great Old Ones", genre: "Atmospheric Black Metal (FR)", desc: "Black atmosférico francés de temática lovecraftiana, cinematográfico y envolvente, con tres guitarras. EOD: A Tale of Dark Legacy (2017) es la cumbre. El mapa: Al Azif (2012) y Tekeli-li (2014) abren; EOD (2017) es la cumbre, Cosmicism (2019) baja algo y Kadath (2025) vuelve arriba. Entrada: EOD: A Tale of Dark Legacy.", origin: "rec", pick: true, p: 2, y: 2009, via: "Behemoth" },
  { name: "Cult of Fire", genre: "Ritual Black Metal (CZ)", desc: "Black metal checo de temática hindú, con letras en sánscrito e instrumentos indios integrados en un black atmosférico y ceremonial. El mapa: Triumvirát (2012) y Ascetic Meditation of Death (2013) son la cumbre; Moksha y Nirvana (2020), dos discos publicados a la vez, son más contemplativos y bajan, y el de 2025 vuelve a la intensidad. Entrada: Ascetic Meditation of Death (2013).", origin: "rec", pick: true, p: 2, y: 2011, via: "Behemoth" },
  { name: "Furia", genre: "Avant-garde Black Metal (PL)", desc: "Black metal polaco de vanguardia con letras en polaco muy poéticas, riffs que se retuercen hacia el rock y la psicodelia y estructuras que cambian de un disco a otro. Księżyc milczy luty (2016) es la referencia. El mapa: Martwa polska jesień (2007) y Grudzień za grudniem (2009) son black más crudo; Marzannie, królowej Polski (2012) y Nocel (2014) abren el giro; Księżyc milczy luty (2016) es la cumbre, y W śnialni (2021) y Huta Luna (2023) siguen explorando. Entrada: Księżyc milczy luty.", origin: "rec", pick: true, p: 2, y: 2003, via: "Behemoth", c: 1 },

  // ----- PROTEST THE HERO (3ª vuelta + internacionales) -----
  { name: "Tera Melos", genre: "Math Rock / Experimental", desc: "Math rock experimental de Sacramento que cambia de textura constantemente: la guitarra pasa por loops y efectos que la convierten en otra cosa a mitad de frase, sobre métricas rotas y una batería que no suelta. El mapa: el debut Tera Melos (2005) y el EP Drugs to the Dear Youth son math instrumental puro y rapidísimo; desde Patagonian Rats (2010) meten voz y melodía pop sin perder el caos, con X'ed Out (2013) como cumbre y Trash Generator (2017) cerca. Entrada: Patagonian Rats.", origin: "rec", pick: true, p: 2, y: 2004, via: "PTH", c: 1 },
  { name: "The Number Twelve Looks Like You", genre: "Mathcore", desc: "Mathcore caótico y ecléctico que salta del jazz y los ritmos latinos a la brutalidad y a lo melódico en segundos, con una voz limpia y otra gritada que se cruzan. El mapa: Put On Your Rosy Red Glasses (2004) y Nuclear. Sad. Nuclear. (2005) son más crudos; Mongrel (2007) es la cumbre, y Worse Than Alone (2009) y Wild Gods (2019) se mantienen. Howls from the Holographic Heart sale el 16 de octubre de 2026. Entrada: Mongrel.", origin: "rec", pick: true, p: 2, y: 2003, via: "PTH", c: 1 },
  { name: "After the Burial", genre: "Djent / Prog Metalcore", desc: "Djent y metalcore progresivo de Minnesota: riffs de ocho cuerdas en polirritmia, solos técnicos y groove muy pesado. Rareform (2008) es la cumbre, e In Dreams, Wolves Within y Dig Deep (2016) sostienen el nivel; su guitarrista y compositor Justin Lowe murió en 2015. Entrada: Rareform.", p: 2, origin: "rec", pick: true, y: 2004, via: "PTH" },
  { name: "Tricot", genre: "Math Rock (JP)", desc: "Math rock japonés con voz femenina: guitarras entrelazadas en compases que cambian, melodías brillantes y energía luminosa, pero con estructura de canción pop. T H E (2013) y 3 (2017) son lo mejor. Entrada: T H E. (voz femenina)", origin: "rec", pick: true, female: true, p: 3, y: 2010, via: "PTH" },
  { name: "Sithu Aye", genre: "Prog / Instrumental (UK)", desc: "Prog y djent instrumental británico, brillante y de mucho tapping, luminoso y melódico.", origin: "rec", pick: true, p: 3, y: 2011, via: "PTH" },
  { name: "Standards", genre: "Math Rock / Instrumental", desc: "Dúo instrumental de Los Ángeles, formado en 2017: Marcos Mena hace todo el trabajo armónico con tapping a dos manos sobre batería, sin bajo, y las piezas duran dos minutos y no se repiten. Todos sus discos llevan título de fruta: Fruit Town, Fruit Island y Fruit Galaxy (2024). Entrada: Fruit Town.", origin: "rec", pick: true, p: 3, y: 2017, via: "PTH" },
  { name: "Tigran Hamasyan", genre: "Jazz / Prog (AM)", desc: "Pianista armenio que cruza jazz, folk armenio y un groove de riff casi metalero: la mano izquierda toca patrones en métricas impares contra la derecha y los temas cambian de compás sin aviso. Lo sostiene en discos muy distintos: Red Hail (2009) y Shadow Theater con banda y voz, Mockroot (2015) y The Call Within (2020) en lo más cercano al prog metal, An Ancient Observer casi a piano solo y The Bird of a Thousand Voices (2024) como obra conceptual. Solo los discos de cámara más contemplativos bajan la intensidad. Entrada: Mockroot.", p: 1, origin: "rec", pick: true, y: 2006, via: "PTH", c: 3 },
  { name: "Paledusk", genre: "Prog Metalcore (JP)", desc: "Metalcore japonés caótico y ecléctico: salta de breakdown a jazz, pop, electrónica y hardcore en pocos segundos, con guitarras técnicas y mucho humor. Happy Talk, Palehell y sus EPs. El mapa: hasta ahora sacan EP, Happy Talk (2020) y PALEHELL (2024), el más completo. Entrada: Palehell.", p: 2, origin: "rec", pick: true, y: 2015, via: "PTH", c: 1 },
  { name: "Elephant Gym", genre: "Math Rock (TW)", desc: "Taiwaneses, instrumentales. El bajo de KT Chang no marca la raíz: lleva la melodía principal con acordes y armónicos mientras la guitarra hace figuras cortas por encima, sobre métricas que cambian sin que suene forzado. El mapa: Angle (2014), Underwater (2018) y World (2023); en 2026 sacaron un directo. Entrada: Underwater.", origin: "rec", pick: true, female: true, p: 2, y: 2012, via: "PTH" },
  { name: "toe", genre: "Math Rock (JP)", desc: "Math rock instrumental japonés con la batería de Takashi Kashikura al frente, llena de notas fantasma y fraseo de jazz, y dos guitarras limpias que se entrelazan en arpegios en vez de tocar riffs: cálido y melódico sin dejar de cambiar de métrica. El mapa: The Book About My Idle Plot on a Vague Anxiety (2005) y For Long Tomorrow (2009) son la cumbre, Hear You (2015) mete más voces y electrónica, y NOW I SEE THE LIGHT (2024), el primero en nueve años, vuelve a la tensión instrumental. Entrada: The Book About My Idle Plot on a Vague Anxiety.", origin: "rec", pick: true, p: 2, y: 2000, via: "PTH" },
  { name: "David Maxim Micić", genre: "Prog / Djent (RS)", desc: "Guitarrista serbio de prog y djent instrumental cinematográfico: melodía de guitarra muy cantable sobre base djent y arreglos orquestales. Bien escrito, pero luminoso y de complejidad más melódica que rítmica. Entrada: Bilo.", p: 3, origin: "rec", pick: true, y: 2011, via: "PTH" },
  { name: "Disperse", genre: "Prog / Fusion (PL)", desc: "Prog polaco luminoso de guitarra limpia y tapping, con fusión suave y voz: técnico pero amable, en la línea de Plini. Entrada: Living Mirrors.", p: 3, origin: "rec", pick: true, y: 2007, via: "PTH" },
  { name: "mouse on the keys", genre: "Math / Jazz (JP)", desc: "Trío japonés de dos teclistas y batería: math rock instrumental con armonía de jazz, unísonos rapidísimos de piano sobre compases irregulares y la batería de Akira Kawasaki llevando el peso, a veces con vientos. El mapa: an anxious object (2009), the flowers of romance (2015), Tres (2018) y midnight (2024), muy parejos; en su vigésimo aniversario sacan el EP Portrait of Impulse (septiembre de 2026). Entrada: an anxious object.", origin: "rec", pick: true, p: 2, y: 2006, via: "PTH" },

  // ----- DREAM THEATER (2ª vuelta + internacionales) -----
  { name: "Madder Mortem", genre: "Prog / Doom (NO)", desc: "Prog y doom noruego construido alrededor de la voz de Agnete Kjølsrud, que pasa del susurro al grito sin perder el control, con guitarras que saltan de lo pesado a lo atmosférico y a pasajes casi folk dentro del mismo tema. Mercury (1999) es el más verde; de All Flesh Is Grass (2001) y Deadlands a Desiderata, Eight Ways, Red in Tooth and Claw, Marrow y Old Eyes, New Heart (2024) el nivel no baja. Entrada: Deadlands.", p: 2, origin: "rec", pick: true, female: true, y: 1997, via: "Dream Theater", c: 1 },
  { name: "Subterranean Masquerade", genre: "Oriental Prog Metal (IL)", desc: "Prog israelí que mezcla death, prog, folk de Oriente Medio y jazz en temas largos, con voces limpias y guturales y escalas orientales que salen de la escritura, no de un adorno encima. Suspended Animation Dreams (2005), The Great Bazaar (2015), Vagabond (2017) y Mountain Fever (2021). Entrada: Suspended Animation Dreams.", p: 2, origin: "rec", pick: true, y: 1997, via: "Dream Theater", c: 1 },
  { name: "Evergrey", genre: "Prog / Power Metal (SE)", desc: "Prog y power sueco oscuro y melancólico, de identidad emocional fuerte y buena guitarra; Architects of a New Weave (2026) sigue esa línea. Entrada: The Inner Circle.", p: 3, origin: "rec", pick: true, y: 1995, via: "Dream Theater" },
  { name: "Angra", genre: "Prog / Power Metal (BR)", desc: "Power y prog brasileño que integra percusión y ritmos de su país en temas técnicos: Holy Land (1996) los mete en la estructura misma de los temas, y Temple of Shadows (2004), conceptual, es su disco más complejo. De Rebirth a Ømni (2018) y Cycles of Pain (2023) mantienen la ambición, con baterías de primera como Aquiles Priester y Bruno Valverde; Aqua (2010) es el bajón. Entrada: Holy Land, luego Temple of Shadows.", p: 2, origin: "rec", pick: true, y: 1991, via: "Dream Theater" },
  { name: "Galneryus", genre: "Power / Prog Metal (JP)", desc: "Power y prog japonés de virtuosismo extremo: la guitarra neoclásica de Syu y los teclados de Yuhki se doblan y se contestan en secciones instrumentales largas, con estructura de power metal pero mucha más densidad instrumental de lo habitual en el género. Lo sostienen en más de quince discos, de The Flag of Punishment (2003) a Resurrection (2010), el primero con Masatoshi Ono a la voz, Angel of Salvation (2012), Under the Force of Courage (2015) y Union Gives Strength (2021). Entrada: Resurrection.", p: 2, origin: "rec", pick: true, y: 2001, via: "Dream Theater" },
  { name: "Kingcrow", genre: "Prog Metal (IT)", desc: "Prog italiano atmosférico y melódico, de texturas muy cuidadas y ritmo contenido. Entrada: Eidos.", p: 3, origin: "rec", pick: true, y: 1996, via: "Dream Theater" },
  { name: "Iamthemorning", genre: "Chamber Prog (RU)", desc: "Prog de cámara ruso: el piano de Gleb Kolyadin, de formación clásica y escritura muy virtuosa, lleva la armonía y el contrapunto junto a cuerdas y maderas, bajo la voz cristalina de Marjana Semkina. Sin peso de metal, pero con arreglos que cambian de clima dentro de la canción. ~ (2012), Belighted (2014), Lighthouse (2016), con Gavin Harrison a la batería, y The Bell (2019) sostienen el nivel. Entrada: Lighthouse.", p: 2, origin: "rec", pick: true, female: true, y: 2010, via: "Dream Theater" },
  { name: "Anubis Gate", genre: "Prog Metal (DK)", desc: "Prog metal danés melódico y atmosférico, sólido y luminoso, dentro de la escuela clásica del género. Entrada: Andromeda Unchained.", p: 3, origin: "rec", pick: true, y: 2001, via: "Dream Theater" },
  { name: "Adagio", genre: "Neoclassical Prog Metal (FR)", desc: "Prog metal neoclásico francés: guitarra de escalas barrocas y teclados sinfónicos, virtuoso y oscuro pero de estructura power. Entrada: Underworld.", p: 3, origin: "rec", pick: true, y: 2000, via: "Dream Theater" },
  { name: "Andromeda", genre: "Technical Prog Metal (SE)", desc: "Prog metal sueco técnico y oscuro, de la escuela de Dream Theater pero más pesado: largas secciones instrumentales donde guitarra y teclado se doblan y se contestan en compases cambiantes. Extension of the Wish (2001), II=I (2003) y Chimera (2006) son su etapa fuerte. Entrada: II=I.", p: 2, origin: "rec", pick: true, y: 1999, via: "Dream Theater" },
  { name: "Liquid Tension Experiment", genre: "Prog / Instrumental", desc: "Prog metal instrumental sin formato canción: teclado y guitarra se intercambian el papel principal y el Chapman Stick de Tony Levin da un bajo de ataque distinto al normal. La mitad es composición de verdad (Acid Rain, Universal Mind) y la otra mitad jams de estudio donde el virtuosismo va por delante de la idea. El mapa: Liquid Tension Experiment (1998) y 2 (1999), y tras veinte años, LTE3 (2021). Entrada: el primer disco (1998).", origin: "rec", p: 2, y: 1997, c: 2 },
  { name: "Goblin", genre: "Prog Rock / Soundtrack (IT)", desc: "Prog italiano instrumental hecho para cine de terror: patrones cortos de teclado y bajo repetidos en métricas irregulares que crean tensión por acumulación en vez de por melodía. El mapa: Profondo Rosso (1975), Roller (1976), Suspiria (1977) e Il fantastico viaggio del bagarozzo Mark (1978) son la cumbre; las bandas sonoras que siguieron, de Zombi (1978) a Tenebre (1982) y Phenomena (1985), son irregulares. Entrada: Profondo Rosso.", origin: "rec", pick: true, p: 2, y: 1972, via: "Dream Theater" },

  // ----- TRIVIUM (2ª vuelta + internacionales) -----
  { name: "Carcass", genre: "Melodic Death (UK)", desc: "De goregrind ilegible a Heartwork, con guitarras gemelas armonizadas y solos escritos como melodía y no como exhibición. Symphonies of Sickness (1989) y Necroticism (1991) ya encadenaban riffs en estructuras largas, Heartwork (1993) es la cumbre y Swansong (1996), con su giro al rock, baja; Surgical Steel (2013) y Torn Arteries (2021) volvieron con esa escritura intacta. Entrada: Heartwork.", origin: "rec", pick: true, p: 1, y: 1985, via: "Trivium", c: 1 },
  { name: "Testament", genre: "Thrash Metal", desc: "Alex Skolnick viene del jazz y eso se nota en sus solos, que son melódicos y con desarrollo en vez de ráfagas, y ese es el mejor argumento que tienen. Pero por debajo es thrash de la Bay Area muy bien hecho y bastante ortodoxo, con riffs de palm mute, estructuras de estrofa y estribillo y poca sorpresa rítmica. Excelente dentro del molde. Para Bellum (octubre de 2025), con el joven Chris Dovas a la batería, fue de los discos de thrash mejor recibidos del año. El mapa: The Legacy (1987) y The New Order (1988) son la cumbre; Practice What You Preach (1989) y Souls of Black (1990) se acomodan; The Ritual (1992) es el más blando y Demonic (1997) el más flojo; Low (1994) y The Gathering (1999) endurecen el sonido, y de The Formation of Damnation (2008) a Para Bellum (2025) vuelven a un buen nivel. Entrada: The New Order o The Legacy.", origin: "rec", p: 2, y: 1983, c: 2 },
  { name: "Annihilator", genre: "Technical Thrash (CA)", desc: "Thrash técnico alrededor de Jeff Waters, guitarrista virtuoso: riffs intrincadísimos y solos vertiginosos. Alice in Hell (1989) y Never, Neverland (1990) son lo que importa; después, con cambios constantes de formación, es muy irregular. Entrada: Alice in Hell.", origin: "rec", pick: true, p: 2, y: 1984, via: "Trivium" },
  { name: "Coroner", genre: "Progressive Thrash (CH)", desc: "Thrash suizo tocado con lógica de jazz: Tommy Vetterli mete acordes de jazz y solos de fraseo casi clásico sobre riffs que cambian de compás a mitad, y la batería subdivide contra la guitarra en vez de marcar el galope. De Punishment for Decadence a No More Color y Mental Vortex cada disco aprieta más, Grin (1993) lo abre a groove y textura, y Dissonance Theory (2025), su vuelta tras treinta y dos años con Diego Rappachietti a la batería, supera en ambición a Grin según la crítica. Entrada: Mental Vortex.", p: 1, origin: "rec", pick: true, y: 1985, via: "Trivium", c: 2 },
  { name: "Kalmah", genre: "Melodic Death (FI)", desc: "Melodeath finlandés con shred neoclásico a dos guitarras y teclados que se turnan los solos, en la línea de Children of Bodom pero con un aire folk propio. Muy parejos de Swamplord (2000) a Swampsong (2003), The Black Waltz, 12 Gauge, Seventh Swamphony y Kalmah (2023). Entrada: Swampsong.", origin: "rec", pick: true, p: 2, y: 1998, via: "Trivium" },
  { name: "Aephanemer", genre: "Symphonic Melodic Death (FR)", desc: "Melodeath sinfónico francés con Marion Bascoul a la voz: melodías muy trabajadas, guitarras neoclásicas y orquestación. Prokopton (2019), A Dream of Wilderness (2021), la cumbre, y Utopie (2025). Entrada: A Dream of Wilderness.", origin: "rec", pick: true, female: true, p: 2, y: 2014, via: "Trivium" },
  { name: "Mekong Delta", genre: "Technical / Prog Thrash (DE)", desc: "Thrash técnico alemán escrito como música de cámara: el bajista y compositor Ralph Hubert mete compases imposibles, contrapunto entre guitarras y adaptaciones de piezas clásicas, como Una noche en el Monte Pelado de Músorgski. The Music of Erich Zann (1988) y Dances of Death (1990) son lo más ambicioso. Entrada: Dances of Death.", p: 2, origin: "rec", pick: true, y: 1985, via: "Trivium" },
  { name: "Watchtower", genre: "Progressive Thrash", desc: "El bajo de Doug Keyser no acompaña: lleva líneas independientes mientras la batería cambia de compás dentro de la frase, sobre thrash tocado con lógica de jazz. Solo tienen dos discos, Energetic Disassembly (1985) y Control and Resistance (1989), y los dos sostienen esa escritura. Entrada: Control and Resistance.", origin: "rec", pick: true, p: 1, y: 1982, via: "Trivium", c: 3 },
  { name: "Crystal Viper", genre: "Heavy / Power Metal (PL)", desc: "Heavy/power polaco clásico con Marta Gabriel a la voz y la guitarra, melódico y épico, en la línea del heavy de los ochenta y sin salirse de ella. The Silver Key (2024) es el último. Entrada: The Cult. (voz femenina)", origin: "rec", pick: true, female: true, p: 3, y: 2003, via: "Trivium" },

  // ----- AVENGED SEVENFOLD (repaso de la rama madre) -----
  { name: "Buckethead", genre: "Avant / Instrumental Guitar", desc: "Guitarrista de técnica enorme, con tapping, killswitch y fraseo de shred, y una obra de más de trescientos discos que salta del metal al funk, al ambient y a lo avant. Es muy desigual: lo mejor está en Monsters and Robots (1999), Colma, Electric Tears, Enter the Chicken y Crime Slunk Scene, y buena parte de la serie de pikes es improvisación de relleno. Entrada: Crime Slunk Scene.", p: 2, origin: "rec", pick: true, y: 1991, via: "A7X", c: 1 },
  { name: "Marty Friedman", genre: "Instrumental Guitar (US/JP)", desc: "El ex Megadeth en solitario: fraseo con escalas japonesas y árabes, bends muy expresivos y discos instrumentales que van del metal a la música pop japonesa reescrita. Dragon's Kiss (1988), Scenes (1992), Introduction (1994) y Drama (2024). Entrada: Dragon's Kiss.", origin: "rec", pick: true, p: 2, y: 1988, via: "A7X" },
  { name: "Lovebites", genre: "Power / Melodic Metal (JP)", desc: "Banda femenina japonesa de power/melodic con guitarras gemelas neoclásicas vertiginosas, muy en la onda de los solos de City of Evil, sobre canciones de molde. Electric Pentagram (2020) es lo mejor; Outstanding Power (2026) es el último. Entrada: Electric Pentagram. (voz femenina)", origin: "rec", pick: true, female: true, p: 3, y: 2016, via: "A7X" },
  { name: "Band-Maid", genre: "Hard Rock (JP)", desc: "Hard rock japonés técnico y ajustadísimo: riffs intrincados con paradas al milímetro, dos guitarras repartiéndose líneas distintas y una batería que sostiene cambios constantes. El mapa: Just Bring It (2017), World Domination (2018), Conqueror (2019) y Unseen World (2021) son la cumbre, y Epic Narratives (2024) está cerca; tras la gira mundial de 2026 paran hasta 2028. Entrada: World Domination.", origin: "rec", pick: true, female: true, p: 2, y: 2013, via: "A7X" },
  { name: "Black Label Society", genre: "Blues / Heavy Metal", desc: "Zakk Wylde, virtuoso del blues-metal: riffs pesados y solos con feeling. The Blessed Hellride.", origin: "rec", pick: true, p: 3, y: 1998, via: "A7X" },
  { name: "Steve Vai", genre: "Instrumental Guitar", desc: "Guitarra instrumental teatral y experimental: hace hablar al instrumento con la palanca y los armónicos, mete compases raros, orquestaciones y humor, y cada disco busca algo distinto. Passion and Warfare (1990) es la cumbre, y Fire Garden (1996), Real Illusions: Reflections (2005), The Story of Light (2012) e Inviolate (2022) están cerca. Entrada: Passion and Warfare.", origin: "rec", pick: true, p: 2, y: 1984, via: "A7X" },
  { name: "Nemophila", genre: "Melodic Death / Metal (JP)", desc: "Japonesas de metal con toques de melodeath: voz que alterna limpio potente y gutural, guitarras técnicas y mucha energía. Revive (2021), Seize the Fate (2022) y Evolve (2024). Entrada: Seize the Fate.", origin: "rec", pick: true, female: true, p: 3, y: 2019, via: "A7X" },

  // ----- CAGE THE ELEPHANT (2ª vuelta + internacionales) -----
  { name: "Café Tacvba", genre: "Alt Rock (MX)", desc: "Rock alternativo mexicano que cambia de lenguaje dentro de la misma canción: en Re (1994), un disco doble, cruzan huapango, son jarocho, norteño, ska, punk y fusión jazz, y El Aparato arranca como huapango, entra un sintetizador y termina en cuerdas y cantos panafricanos. Café Tacvba (1992), Re, Revés/Yo soy (1999), la cumbre experimental, y Cuatro caminos (2003) sostienen ese nivel; de Sino (2007) a Jei Beibi (2017) la escritura se vuelve más de canción y baja. Entrada: Re.", origin: "rec", pick: true, p: 1, y: 1989, via: "Cage the Elephant", c: 1 },
  { name: "Pond", genre: "Psych Rock (AU)", desc: "Psych rock australiano ecléctico y prolífico, colorido y experimental, con miembros que pasaron por Tame Impala. The Weather (2017). Entrada: The Weather.", p: 3, origin: "rec", pick: true, y: 2008, via: "Cage the Elephant", c: 1 },
  { name: "Unknown Mortal Orchestra", genre: "Psych / Funk (NZ/US)", desc: "Psicodelia y funk lo-fi de Ruban Nielson, un guitarrista muy bueno: melodías retorcidas, groove y atmósfera cálida, con una producción casera deliberadamente saturada. II (2013) y Multi-Love (2015) son lo mejor. Entrada: Multi-Love.", origin: "rec", pick: true, p: 3, y: 2010, via: "Cage the Elephant" },
  { name: "The Black Angels", genre: "Psych Rock", desc: "Psych rock oscuro de Austin, de drones y riffs repetidos hasta la hipnosis. Passover (2006). Entrada: Passover.", origin: "rec", pick: true, p: 3, y: 2004, via: "Cage the Elephant" },
  { name: "Warpaint", genre: "Atmospheric Indie Rock", desc: "Banda femenina: atmosférico e hipnótico con guitarras entrelazadas, bajo protagonista y ritmos intrincados. Sutil y moody. The Fool.", p: 3, origin: "rec", pick: true, female: true, y: 2004, via: "Cage the Elephant" },
  { name: "Blues Pills", genre: "Blues / Psych Rock (SE)", desc: "Blues/psych retro con Elin Larsson (voz poderosa) y guitarra con feeling. Cálido y orgánico. Lady in Gold.", origin: "rec", pick: true, female: true, p: 3, y: 2011, via: "Cage the Elephant" },
  { name: "Hinds", genre: "Garage Rock (ES)", desc: "Banda madrileña de garage rock crudo y melódico, con armonías vocales y energía desenfadada. Entrada: Leave Me Alone.", origin: "rec", pick: true, female: true, p: 3, y: 2011, via: "Cage the Elephant" },

  // ----- METALCORE (2ª vuelta + internacionales) -----
  { name: "The Chariot", genre: "Chaotic Metalcore", desc: "Metalcore grabado casi en directo y a propósito sin cuadricular, con cortes bruscos a silencio, feedback usado como parte del tema y estructuras que no repiten el estribillo ni una vez. Josh Scogin grita por encima de riffs que se desmontan a mitad. De Everything Is Alive (2004) a The Fiancée, Wars and Rumors of Wars, Long Live (2010) y One Wing (2012) cada disco es más escrito; hay más energía que desarrollo, pero no hay uno flojo. Entrada: Long Live.", origin: "rec", p: 2, y: 2003, c: 1 },
  { name: "Converge", genre: "Metalcore / Mathcore", desc: "Kurt Ballou escribe riffs disonantes que cambian de figura cada pocos segundos y nunca vuelven al mismo sitio, y Ben Koller toca la batería como una voz más, cambiando de patrón bajo el mismo riff y metiendo redobles que rompen el compás en vez de marcarlo. Jane Doe alterna esa violencia con pasajes largos y lentos dentro del mismo disco. El mapa: Halo in a Haystack (1994) y Petitioning the Empty Sky son hardcore metálico todavía verde; When Forever Comes Crashing (1998) afila la escritura, y de Jane Doe (2001) a You Fail Me, No Heroes, Axe to Fall (2009), All We Love We Leave Behind (2012) y The Dusk in Us (2017) está la cumbre. Bloodmoon: I (2021), con Chelsea Wolfe, es un aparte lento y gótico, y Love Is Not Enough (febrero de 2026) vuelve a lo corto y directo. Entra por Jane Doe.", origin: "rec", p: 1, y: 1990, c: 2 },
  { name: "Botch", genre: "Mathcore", desc: "Riffs angulares en métricas que no se repiten y canciones que acaban en un sitio distinto del que empezaron, sin volver nunca a la primera sección. El mapa: dos discos y un EP, American Nervoso (1998), We Are the Romans (1999), la cumbre, y An Anthology of Dead Ends (2002). Volvieron en 2022 con un tema nuevo, One Twenty Two, y se despidieron del todo en junio de 2024 en Seattle; ese concierto salió como el directo 061524 en 2025. Entrada: We Are the Romans.", origin: "rec", pick: true, p: 1, y: 1993, via: "Metalcore" },
  { name: "Pupil Slicer", genre: "Mathcore / Noise (UK)", desc: "Mathcore y grind caótico y técnico con Kate Davies, que en el segundo disco gira hacia lo progresivo y lo atmosférico. Mirrors (2021) y Blossom (2023). Entrada: Blossom.", p: 2, origin: "rec", pick: true, female: true, y: 2019, via: "Metalcore" },
  { name: "Frontierer", genre: "Dissonant Mathcore", desc: "Mathcore disonante y glitchy: capas de guitarra recortadas digitalmente, samples de ruido metidos como percusión y riffs que cambian de figura cada compás, todo mezclado como una pared saturada. Abrasivo de principio a fin. El mapa: Orange Mathematics (2016), Unloved (2018) y Oxidized (2021); Ultraviolet Parasite sale el 23 de octubre de 2026. Entrada: Unloved.", origin: "rec", pick: true, p: 2, y: 2012, via: "Metalcore" },
  { name: "Vildhjarta", genre: "Thall / Djent (SE)", desc: "Thall: afinaciones gravísimas, riffs de ritmo entrecortado que funcionan casi como percusión y capas de ambiente disonante entre golpe y golpe. Måsstaden (2011), Måsstaden under vatten (2021) y + Där skogen sjunger under evighetens granar + (2025). Entrada: Måsstaden under vatten.", p: 2, origin: "rec", pick: true, y: 2005, via: "Metalcore" },

  // ----- BE'LAKOR / MELODEATH ATMOSFÉRICO (2ª vuelta + internacionales) -----
  { name: "Katatonia", genre: "Atmospheric Prog Metal (SE)", desc: "Empezaron en el doom-death y acabaron en un rock atmosférico y melancólico de capas de guitarra limpia y voz baja: instrumentalmente es contención deliberada, no complejidad, con el interés en la textura y en cómo la batería sostiene tempos lentos. Anders Nyström, cofundador y guitarrista durante casi treinta y cinco años, se fue en marzo de 2025; Nightmares as Extensions of the Waking State salió tres meses después. El mapa: Dance of December Souls (1993) y Brave Murder Day (1996) son doom-death; de Discouraged Ones (1998) a Tonight's Decision, Last Fair Deal Gone Down (2001), Viva Emptiness (2003) y The Great Cold Distance (2006) está la cumbre; Night Is the New Day (2009), Dead End Kings (2012) y The Fall of Hearts (2016) se mantienen, y City Burials (2020), Sky Void of Stars (2023) y Nightmares as Extensions of the Waking State (2025) son más de canción. Entrada: The Great Cold Distance.", origin: "rec", p: 2, y: 1991, c: 1 },
  { name: "Borknagar", genre: "Prog Folk / Viking Metal (NO)", desc: "Black y viking noruego que fue incorporando prog: voces limpias en armonía a varias voces contra guturales, teclados de Lars Nedland haciendo contrapunto y estructuras largas con cambios de clima. Empiricism (2001) y Winter Thrice (2016) son dos etapas del mismo crecimiento. Entrada: Empiricism.", p: 2, origin: "rec", pick: true, y: 1995, via: "Be'lakor", c: 1 },
  { name: "An Abstract Illusion", genre: "Prog Death (SE)", desc: "Death progresivo sueco atmosférico y sinfónico, con teclados y canciones larguísimas que son viajes completos. Illuminate the Path (2016) y Woe (2022) son la cumbre, y The Sleeping City (2025) queda algo por debajo. Entrada: Woe.", p: 2, origin: "rec", pick: true, y: 2013, via: "Be'lakor" },
  { name: "Eternal Storm", genre: "Prog Melodic Death (ES)", desc: "Madrileños de melodeath progresivo y atmosférico en la órbita de Be'lakor: temas largos que se desarrollan en vez de repetir, con guitarras limpias entre lo pesado. Come the Tide (2019) y A Giant Bound to Fall (2024). Entrada: Come the Tide.", origin: "rec", pick: true, p: 2, y: 2008, via: "Be'lakor" },
  { name: "October Tide", genre: "Melodic Death/Doom (SE)", desc: "Nacido de Jonas Renkse y Fredrik Norrman, de Katatonia: death/doom melancólico con guitarras melódicas lentas. Rain Without End (1997) es la cumbre; desde A Thin Shell (2010), con Norrman al mando, sigue a buen nivel. Entrada: Rain Without End.", origin: "rec", pick: true, p: 2, y: 1995, via: "Be'lakor" },
  { name: "Moonsorrow", genre: "Pagan / Folk Metal (FI)", desc: "Pagan/folk finlandés de piezas de diez a treinta minutos que avanzan por secciones sin estribillo, con acordeón y coros de muchas voces metidos dentro de la estructura y riff de black debajo. V: Hävitetty (2007) son solo dos temas, de más de veinticinco minutos cada uno. El mapa: Suden uni y Voimasta ja kunniasta (2001) son más de canción; Kivenkantaja (2003), Verisäkeet (2005) y V: Hävitetty son la cumbre; Varjoina kuljemme kuolleiden maassa (2011) y Jumalten aika (2016), el último, se mantienen cerca. Entrada: Kivenkantaja o V: Hävitetty.", origin: "rec", pick: true, p: 2, y: 1995, via: "Be'lakor" },
  { name: "Draconian", genre: "Gothic Doom Metal (SE)", desc: "Gothic doom sueco atmosférico y melancólico con voz femenina limpia y gutural masculina. Lento y hermoso, dentro del molde. Entrada: Sovran.", origin: "rec", pick: true, female: true, p: 3, y: 1994, via: "Be'lakor" },
  { name: "Trees of Eternity", genre: "Gothic Doom (SE/FI)", desc: "Doom gótico atmosférico con la voz etérea de Aleah Stanbridge; un solo disco, Hour of the Nightingale (2016), publicado tras su muerte. Melancólico y lento. Entrada: Hour of the Nightingale.", origin: "rec", pick: true, female: true, p: 3, y: 2014, via: "Be'lakor" },
  { name: "Fractal Universe", genre: "Prog Death (FR)", desc: "Death progresivo francés con saxofón y jazz integrados en la estructura, técnico y ambicioso. Rhizomes of Insanity (2019) y The Impassable Horizon (2021). Entrada: The Impassable Horizon.", p: 2, origin: "rec", pick: true, y: 2014, via: "Be'lakor" },

  // ----- PANIC! AT THE DISCO (2ª vuelta + internacionales) -----
  { name: "David Bowie", genre: "Art Rock / Glam (UK)", desc: "En Low la cara B son piezas casi instrumentales con los sintetizadores tratados como textura y sin estructura de canción; en Heroes la guitarra de Robert Fripp está grabada con retroalimentación controlada según la distancia al amplificador; y Blackstar lo grabó con el cuarteto de jazz de Donny McCaslin, con el saxo llevando líneas principales en compases irregulares. Ziggy y Aladdin Sane tienen a Mick Ronson escribiendo los arreglos de cuerda. Cinco décadas cambiando de sistema; el bache es la etapa de Let's Dance (1983), Tonight y Never Let Me Down, y de Outside (1995) a Blackstar (2016) vuelve a arriesgar. Entra por Low o Blackstar.", origin: "rec", p: 1, y: 1967, c: 1 },
  { name: "Roxy Music", genre: "Art / Glam Rock (UK)", desc: "Art rock británico elegante y raro: el sintetizador de Brian Eno tratando los instrumentos, el oboe y el saxo de Andy Mackay y la guitarra de Phil Manzanera sobre canciones que no siguen la forma habitual. Roxy Music (1972) y For Your Pleasure (1973) son los más experimentales; Stranded, Country Life y Siren (1975) siguen arriba, y Avalon (1982) es su cara más pulida. Entrada: For Your Pleasure.", origin: "rec", pick: true, p: 2, y: 1971, via: "Panic!", c: 1 },
  { name: "Scott Walker", genre: "Baroque / Avant Pop", desc: "De crooner barroco orquestal a la vanguardia más oscura. Scott 1 a Scott 4 (1967-1969) son canción de cámara con arreglos de cuerda muy escritos y su voz de barítono al frente; tras unos setenta de discos de encargo muy flojos, Nite Flights (1978) abre la etapa final, que en Tilt (1995), The Drift (2006) y Bish Bosch (2012) es disonancia, silencio y percusión rara al servicio de una voz casi operística. Entrada: Scott 4, luego Tilt.", p: 2, origin: "rec", pick: true, y: 1967, via: "Panic!", c: 1 },
  { name: "10cc", genre: "Art Pop (UK)", desc: "Art pop británico ingenioso e instrumentalmente inventivo, con técnicas de estudio muy adelantadas, como los muros de voces en bucle de I'm Not in Love, y canciones que cambian de estilo a mitad. De Sheet Music (1974) a How Dare You! (1976) es lo mejor. Entrada: The Original Soundtrack.", origin: "rec", pick: true, p: 2, y: 1972, via: "Panic!" },
  { name: "Sufjan Stevens", genre: "Baroque Chamber Pop", desc: "Folk de cámara con orquestaciones ornamentadas de vientos, cuerdas y coros, discos conceptuales y compases que cambian dentro de la canción, y a veces electrónica rota, como en The Age of Adz (2010). Illinois (2005) es la cumbre, y Carrie & Lowell (2015) y Javelin (2023) están cerca. Entrada: Illinois.", origin: "rec", pick: true, p: 2, y: 2000, via: "Panic!" },
  { name: "Father John Misty", genre: "Baroque Singer-Songwriter", desc: "Cantautor barroco y orquestal, teatral, ingenioso y mordaz, con arreglos lujosos. Entrada: I Love You, Honeybear.", origin: "rec", pick: true, p: 3, y: 2012, via: "Panic!" },
  { name: "Andrew Bird", genre: "Baroque Chamber Pop", desc: "Pop de cámara construido en directo con bucles de violín pizzicato y con arco, silbido y guitarra, capa sobre capa, con arreglos intrincados. Muy parejo de The Mysterious Production of Eggs (2005) y Armchair Apocrypha (2007) a Break It Yourself (2012) y Sunday Morning Put-On (2024). Entrada: Armchair Apocrypha.", origin: "rec", pick: true, p: 2, y: 1996, via: "Panic!" },
  { name: "Tori Amos", genre: "Baroque Piano Pop", desc: "El piano lleva la armonía completa sin banda debajo en buena parte de su obra, con compases que cambian dentro de la frase y una voz que salta de registro contra ese piano en vez de apoyarse en él. Little Earthquakes, Boys for Pele y From the Choirgirl Hotel son tres planteamientos distintos del mismo instrumento; después es más irregular, hasta In Times of Dragons (mayo de 2026). El mapa: Little Earthquakes (1992), Under the Pink (1994), Boys for Pele (1996) y From the Choirgirl Hotel (1998) son la cumbre; To Venus and Back (1999) y Scarlet's Walk (2002) están cerca, y lo posterior, hasta Ocean to Ocean (2021), es irregular. Entrada: Boys for Pele.", origin: "rec", pick: true, female: true, p: 2, y: 1990, via: "Panic!" },
  { name: "Babasónicos", genre: "Alt Rock (AR)", desc: "Rock alternativo argentino ecléctico y sensual, de producción muy trabajada, que se reinventa: de la psicodelia de Trance Zomba y Dopádromo a Miami (1999), Jessico (2001) e Infame (2003), la cumbre, y Anoche y Mucho; lo último baja. Entrada: Jessico.", p: 2, origin: "rec", pick: true, y: 1991, via: "Panic!" },
  { name: "Fiona Apple", genre: "Art / Baroque Pop", desc: "[Comodín] Piano de armonía jazzística y estructuras imprevisibles, y en sus dos últimos discos algo que nadie más hace: The Idler Wheel... (2012) está construido casi solo con piano y percusión seca, y Fetch the Bolt Cutters (2020) convierte golpes, objetos de la casa y coros en la base rítmica de canciones que cambian de tempo y de forma. Cinco discos, todos a gran nivel. Entrada: Fetch the Bolt Cutters.", origin: "rec", pick: true, female: true, p: 2, y: 1996, via: "Panic!", c: 3 },
  { name: "The Tiger Lillies", genre: "Dark Cabaret (UK)", desc: "Dark cabaret de tres personas: acordeón, contrabajo y percusión mínima bajo el falsete grotesco de Martyn Jacques, con temática siniestra y fraseo de cabaret de Weimar. Sin guitarra y sin batería de rock. Entrada: Shockheaded Peter.", origin: "rec", pick: true, p: 3, y: 1989, via: "Panic!" },
  { name: "Dir En Grey", genre: "Visual Kei / Experimental (JP)", desc: "Japoneses que empezaron en el visual kei y se convirtieron en metal extremo y progresivo: estructuras largas que pasan de la brutalidad a la balada, afinaciones graves y la voz de Kyo, que va del falsete al gutural con un rango casi sin par. Uroboros (2008) y Dum Spiro Spero (2011) son la cumbre, con Kisou, Vulgar, Arche y The Insulated World cerca; el debut, Gauze, y The Marrow of a Bone quedan por debajo. Entrada: Uroboros.", p: 2, origin: "rec", pick: true, y: 1997, via: "Panic!" },

  // ----- MUSE (2ª vuelta + internacionales) -----
  { name: "Twelve Foot Ninja", genre: "Eclectic Prog Metal (AU)", desc: "Prog metal australiano de eclecticismo desbocado: salta a funk, latin, reggae, jazz y djent dentro de una misma canción, con técnica y humor. Divertido y bien tocado, pero el salto de estilo es el recurso y las secciones duran poco: Silent Machine (2012), Outlier (2016) y Vengeance (2021). Entrada: Silent Machine.", p: 3, origin: "rec", pick: true, y: 2008, via: "Muse", c: 1 },
  { name: "Archive", genre: "Electronic / Prog Rock (UK)", desc: "Rock electrónico y prog de escala cinematográfica: temas largos que crecen por capas y arreglos orquestales reales, con la voz rotando entre varios cantantes de disco a disco. El mapa: Londinium (1996) y Take My Head (1999) son trip-hop; You All Look the Same to Me (2002), Noise (2004) y Lights (2006) abren el giro al prog; Controlling Crowds (2009, en cuatro partes) es la cumbre, y With Us Until You're Dead (2012), Axiom (2014), The False Foundation (2016), Call to Arms & Angels (2022) y Glass Minds (2026) siguen a buen nivel. Entrada: Controlling Crowds.", origin: "rec", pick: true, p: 2, y: 1994, via: "Muse" },
  { name: "Zoé", genre: "Psych Alt Rock (MX)", desc: "Rock alternativo mexicano psicodélico y espacial, atmosférico y de producción cuidada. Memo Rex Commander y el Corazón Atómico de la Vía Láctea (2006) y Reptilectric (2008) son la cumbre. Entrada: Memo Rex Commander y el Corazón Atómico de la Vía Láctea.", p: 3, origin: "rec", pick: true, y: 1997, via: "Muse" },
  { name: "Elbow", genre: "Orchestral Alt Rock (UK)", desc: "Alt rock orquestal de Manchester, sofisticado y emotivo, de arreglos muy cuidados y crescendos grandes, pero de escritura contenida. The Seldom Seen Kid (2008). Entrada: The Seldom Seen Kid.", p: 3, origin: "rec", pick: true, y: 1997, via: "Muse" },
  { name: "Placebo", genre: "Alt Rock (UK)", desc: "Alt rock británico dramático y andrógino, de riffs directos y melancolía. Placebo (1996) y Without You I'm Nothing (1998) son lo mejor. Entrada: Without You I'm Nothing.", p: 3, origin: "rec", pick: true, y: 1994, via: "Muse" },
  { name: "Amplifier", genre: "Space / Prog Rock (UK)", desc: "Space rock y prog británico denso y de riff, hipnótico y pesado. The Octopus (2011), un doble, es lo más ambicioso. Entrada: The Octopus.", origin: "rec", pick: true, p: 3, y: 1999, via: "Muse" },
  { name: "VUUR", genre: "Prog Metal (NL)", desc: "Prog metal pesado y dramático construido alrededor de la voz de Anneke van Giersbergen. Entrada: In This Moment We Are Free – Cities.", p: 3, origin: "rec", pick: true, female: true, y: 2016, via: "Muse" },
  { name: "65daysofstatic", genre: "Post-Rock / Electronic (UK)", desc: "Post-rock de Sheffield con electrónica integrada de verdad, breakbeats y ritmos de math rock bajo guitarras que estallan. The Fall of Math (2004), One Time for All Time (2005) y la banda sonora de No Man's Sky (2016), generativa. Entrada: The Fall of Math.", origin: "rec", pick: true, p: 2, y: 2001, via: "Muse" },
  { name: "Stream of Passion", genre: "Prog Metal (MX/NL)", desc: "Prog metal melódico y atmosférico con Marcela Bovio, mexicana de formación clásica: dramático y elegante, pero dentro del molde del metal gótico sinfónico. Entrada: Embrace the Storm.", p: 3, origin: "rec", pick: true, female: true, y: 2005, via: "Muse" },

  // ----- ICE NINE KILLS (2ª vuelta + internacionales) -----
  { name: "King Diamond", genre: "Theatrical Heavy Metal (DK)", desc: "Andy LaRocque escribe guitarras armonizadas con giros neoclásicos y las canciones encadenan varias partes sin repetirlas. Pero el peso de la banda está en la narración y la puesta en escena más que en la escritura instrumental, y Mercyful Fate hace lo mismo instrumentalmente y mejor. Abigail (1987) es la cumbre y de Fatal Portrait (1986) a The Eye (1990) no bajan; lo posterior es más irregular. Su disco nuevo, Saint Lucifer's Hospital 1920, se espera para 2027. Entrada: Abigail.", origin: "rec", p: 2, y: 1985, c: 2 },
  { name: "Lorna Shore", genre: "Symphonic Deathcore", desc: "Deathcore sinfónico de escala cinematográfica: orquestación con coro y cuerda escrita como capa protagonista, no de fondo, sobre blast beats constantes, y Will Ramos alternando gutural profundo, agudo desgarrado y ese trino gutural que lo hizo famoso. Grandilocuente hasta el exceso, y a propósito. El mapa: Psalms (2015) y Flesh Coffin (2017) son deathcore más convencional; Immortal (2020) abre la etapa sinfónica; con Will Ramos, el EP ...And I Return to Nothingness (2021) y Pain Remains (2022) son la cumbre, e I Feel the Everblack Festering Within Me (septiembre de 2025) sigue la misma línea. Entrada: Pain Remains.", origin: "rec", pick: true, p: 2, y: 2009, via: "Ice Nine Kills" },
  { name: "Once Human", genre: "Melodic Death / Metalcore", desc: "Melodeath y metalcore de Los Ángeles con Logan Mader, ex Machine Head, a la guitarra: agresivo y melódico. Su cantante, Lauren Hart, es desde 2026 también la voz de Arch Enemy. The Life I Remember (2015), Evolution (2017) y Scar Weaver (2022). Entrada: Evolution.", origin: "rec", pick: true, female: true, p: 3, y: 2014, via: "Ice Nine Kills" },
  { name: "Mercyful Fate", genre: "Theatrical Heavy Metal (DK)", desc: "Hank Shermann y Michael Denner escriben temas de siete y ocho minutos encadenando cuatro o cinco secciones distintas que no vuelven, con guitarras armonizadas en intervalos incómodos y cambios de tempo dentro de la frase, cuando en 1984 el resto del heavy hacía estrofa y estribillo. Melissa (1983) y Don't Break the Oath (1984) son la cumbre, y a la vuelta In the Shadows (1993) y Time (1994) están a su altura; Into the Unknown, Dead Again y 9 (1999) bajan un poco. Preparan disco nuevo, el primero desde 1999. Entrada: Don't Break the Oath.", origin: "rec", p: 1, y: 1981, c: 2 },
  { name: "Lordi", genre: "Hard Rock / Horror (FI)", desc: "Hard rock de monstruos con disfraces y teatralidad de terror serie B. Pegadizo y camp (ganaron Eurovisión). El mapa: Get Heavy (2002), The Monsterican Dream (2004) y The Arockalypse (2006) son lo más conocido, y siguen con la misma fórmula hasta Limited Deadition (2025).", origin: "rec", pick: true, p: 3, y: 1992, via: "Ice Nine Kills" },

  // ----- IN FLAMES (2ª vuelta + internacionales) -----
  { name: "Myrath", genre: "Oriental Prog Metal (TN)", desc: "Power y prog tunecino con instrumentación y escalas de Oriente Medio integradas en los arreglos, cuerdas, percusión y los melismas de Zaher Zorgati, sobre una base de power metal melódico. Suena exótico, pero la estructura es de estribillo grande y el nivel es parejo de Legacy (2016) y Shehili (2019) a Karma (2024). Entrada: Legacy.", p: 3, origin: "rec", pick: true, y: 2006, via: "In Flames", c: 2 },
  { name: "Orbit Culture", genre: "Melodic Death / Groove (SE)", desc: "Suecos de melodeath moderno cruzado con el groove de Gojira: riffs muy pesados y rítmicos, atmósfera y voces limpias. Nija (2020) es la cumbre; Descent (2023) y Death Above Life (octubre de 2025). Entrada: Nija.", origin: "rec", pick: true, p: 2, y: 2013, via: "In Flames" },
  { name: "Wolfheart", genre: "Melodic Death (FI)", desc: "Melodeath atmosférico finlandés de Tuomas Saukkonen, que él llama winter metal: épico, frío y con melodías preciosas, dentro del molde. Winterborn (2013) y Wolves of Karelia (2020). Entrada: Winterborn.", origin: "rec", pick: true, p: 3, y: 2013, via: "In Flames" },
  { name: "Dimension Zero", genre: "Melodic Death (SE)", desc: "Melodeath de Gotemburgo agresivo y muy rápido, sin teclados ni estribillos limpios: riffs de trémolo melódicos y guitarras gemelas en la línea de The Jester Race, pero más secos. Silent Night Fever (2002) es lo mejor. Entrada: Silent Night Fever.", origin: "rec", pick: true, p: 3, y: 1995, via: "In Flames" },
  { name: "Norther", genre: "Melodic Death (FI)", desc: "Melodeath finlandés con teclados y shred neoclásico, melódico y enérgico, en la veta de Children of Bodom. Dreams of Endless War (2002) y Mirror of Madness (2003) son lo mejor; los últimos bajan. Entrada: Mirror of Madness.", origin: "rec", pick: true, p: 3, y: 1996, via: "In Flames" },
  { name: "Frantic Amber", genre: "Melodic Death (SE)", desc: "Melodeath de Gotemburgo con Elizabeth Andrews a la voz, agresivo y melódico con buenas guitarras. Burning Insight (2015), Bellatrix (2019) y Death Becomes Her (2025). Entrada: Bellatrix.", origin: "rec", pick: true, female: true, p: 3, y: 2008, via: "In Flames" },
  { name: "Mercenary", genre: "Melodic Death / Power (DK)", desc: "Daneses de melodeath cruzado con power y prog: temas largos con mucha melodía vocal limpia y aguda, teclados y guitarras que cambian de sección. De Everblack (2002) a 11 Dreams (2004), la cumbre, The Hours That Remain y Architect of Lies (2008); desde Metamorphosis (2011) bajan. Entrada: 11 Dreams.", origin: "rec", pick: true, p: 2, y: 1991, via: "In Flames" },

  // ----- SIAMES (cierre del repaso + barrido latino/atmosférico) -----
  { name: "Usted Señálemelo", genre: "Alt Rock (AR)", desc: "Trío argentino de rock alternativo técnico y atmosférico, con guitarras en capas, sintetizadores y cambios de compás, que cambia mucho de un disco a otro. El mapa: Usted Señálemelo (2015) abre, II (2017) es la cumbre y Tripolar (2023) el último. Entrada: II.", p: 2, origin: "rec", pick: true, y: 2012, via: "Siames", c: 1 },
  { name: "Beach House", genre: "Dream Pop", desc: "Dream pop de Baltimore: capas de órgano y guitarras con reverb bajo la voz de Victoria Legrand, lujoso y melancólico pero de escritura estática. Teen Dream (2010) y Bloom (2012). Entrada: Teen Dream.", p: 3, origin: "rec", pick: true, female: true, y: 2004, via: "Siames" },
  { name: "Hello Seahorse!", genre: "Alt Rock (MX)", desc: "Alt rock mexicano con Lo Blondo a la voz, atmosférico y electrónico, de texturas interesantes. Entrada: Bestia.", origin: "rec", pick: true, female: true, p: 3, y: 2005, via: "Siames" },
  { name: "DIIV", genre: "Dream Pop / Shoegaze", desc: "Dream pop y shoegaze de Brooklyn con guitarras entrelazadas e hipnóticas. Oshin (2012), Deceiver (2019) y Frog in Boiling Water (2024). Entrada: Deceiver.", p: 3, origin: "rec", pick: true, y: 2011, via: "Siames" },
  { name: "Bándalos Chinos", genre: "Indie Pop/Rock (AR)", desc: "Indie pop y rock argentino sofisticado y de groove, de producción cuidada. Entrada: Bach.", origin: "rec", pick: true, p: 3, y: 2009, via: "Siames" },
  { name: "Rhye", genre: "Atmospheric Soul / Indie", desc: "Soul atmosférico y sensual, sofisticado y minimalista pero con arreglos elegantes. Para el lado nocturno. Woman, Blood.", origin: "rec", pick: true, p: 3, y: 2012, via: "Siames" },
  { name: "Wild Beasts", genre: "Art Rock (UK)", desc: "Art rock británico con el falsete de Hayden Thorpe, guitarras angulares entrelazadas y atmósfera sensual y oscura. Two Dancers (2009) y Smother (2011) son lo mejor; se separaron en 2018. Entrada: Two Dancers.", origin: "rec", pick: true, p: 2, y: 2004, via: "Siames" },
  { name: "Mitski", genre: "Indie Rock", desc: "Indie rock que va de lo íntimo a lo explosivo, con arreglos creativos: Puberty 2 (2016) y Be the Cowboy (2018). Entrada: Be the Cowboy.", p: 3, origin: "rec", pick: true, female: true, y: 2012, via: "Siames" },
  { name: "Diamante Eléctrico", genre: "Alt / Blues Rock (CO)", desc: "Colombianos: alt y blues rock con groove, riffs sucios y atmósfera, con la voz rasgada de Juan Galeano y una producción que deja mucho aire. El mapa: Diamante Eléctrico (2013) abre; B (2015) y La gran oscilación (2016) ganaron el Latin Grammy al mejor disco de rock; siguen Buitres (2018), Mira lo que me hiciste hacer (2021), Leche de tigre (2023) y Malhablado (2024). Entrada: Buitres.", origin: "rec", pick: true, female: true, p: 2, y: 2012, via: "Siames" }
];

// ===========================================================================
// === TANDA 4 (junio 2026) — Iron Maiden + Dethklok + Death metal (anti-CC)
// + 1ª vuelta de Siames que faltaba. Campos nuevos: p (prioridad 1-4),
// y (año formación/estreno), via (rama de origen de la recomendación).
// ===========================================================================
const TANDA_4 = [
  // ----- IRON MAIDEN (bajo líder / épico-narrativo / prog) -----
  { name: "Thin Lizzy", genre: "Hard Rock (IE)", y: 1969, p: 1, via: "Iron Maiden", desc: "Phil Lynott canta y toca el bajo a la vez, con líneas melódicas que se mueven contra la voz en vez de sostenerla, y las dos guitarras tocan armonizadas en terceras como una sola voz doble. Jailbreak, Johnny the Fox y Black Rose sostienen esa escritura. El mapa: los tres primeros (1971-1973) son folk rock más suelto; Nightlife (1974) abre la etapa de dos guitarras; Fighting (1975), Jailbreak (1976), Johnny the Fox, Bad Reputation (1977) y Black Rose (1979) son la cumbre; Chinatown (1980) y Renegade (1981) bajan, y Thunder and Lightning (1983), el último, vuelve a subir. Phil Lynott murió en 1986. Entrada: Jailbreak.", origin: "rec", pick: true },
  { name: "Voivod", genre: "Prog / Avant Metal (CA)", y: 1982, p: 2, via: "Iron Maiden", desc: "Acordes disonantes abiertos de Piggy sobre la batería de Away, que mete cambios de compás y fraseo de jazz dentro del thrash, y un bajo que va por su cuenta en vez de doblar el riff. El mapa es desigual: Killing Technology (1987), Dimension Hatröss y Nothingface son un metal espacial sin par, y Angel Rat y The Outer Limits lo llevan a un prog más limpio; de Negatron (1995) a Infini (2009) la escritura se vuelve más directa y plana, y es lo más flojo. Con Chewy a la guitarra recuperan el nivel en Target Earth (2013), The Wake (2018) y Synchro Anarchy (2022). Entrada: Nothingface.", origin: "rec", pick: true, c: 3 },
  { name: "Atheist", genre: "Tech Death / Jazz Fusion", y: 1987, p: 1, via: "Iron Maiden", desc: "[Comodín] Death técnico cruzado con fusión jazz, con el bajo fretless como co-líder, Roger Patterson en Piece of Time y Tony Choy en Unquestionable Presence tras la muerte de Patterson, y Steve Flynn a la batería cambiando de compás sin parar. Piece of Time (1990), Unquestionable Presence (1991) y Elements (1993), con percusión latina, son la cumbre; Jupiter (2010), la vuelta, baja algo. Entrada: Unquestionable Presence.", origin: "rec", pick: true, c: 3 },
  { name: "Primus", genre: "Funk Metal / Experimental", y: 1984, p: 2, via: "Iron Maiden", desc: "[Comodín] Les Claypool toca el bajo como instrumento líder, con slap, tapping y armónicos llevando el tema entero mientras la guitarra de Larry LaLonde hace de textura y la batería va contra el bajo en vez de con él. Frizzle Fry (1990), Sailing the Seas of Cheese y Tales from the Punchbowl son la cumbre y The Desaturating Seven (2017) está cerca; Pork Soda, el Brown Album y Antipop bajan, y el disco de Willy Wonka es de versiones. Tim Alexander dejó la batería a finales de 2024 y desde febrero de 2025 la toca John Hoffman. Entrada: Sailing the Seas of Cheese.", origin: "rec", pick: true, c: 3 },
  { name: "Diamond Head", genre: "NWOBHM (UK)", y: 1976, p: 2, via: "Iron Maiden", desc: "NWOBHM ambicioso y de riff: Lightning to the Nations (1980), con temas largos que cambian de sección, es media base del thrash, y Metallica versionó cuatro de sus canciones. Lo que vino después, de Borrowed Time a la vuelta, es irregular. El mapa: Lightning to the Nations (1980) es la obra; Borrowed Time (1982) y Canterbury (1983) se van al rock melódico, lo de los noventa y dos mil baja, y con Rasmus Bom Andersen a la voz, Diamond Head (2016) y The Coffin Train (2019) recuperan el nivel. Entrada: Lightning to the Nations.", origin: "rec", pick: true },
  { name: "Satan", genre: "NWOBHM (UK)", y: 1980, p: 1, via: "Iron Maiden", desc: "NWOBHM técnico: Russ Tippins y Steve Ramsey escriben riffs muy enrevesados y dos guitarras que se reparten melodía y contramelodía, con cambios de sección continuos y una base rítmica que no se limita a galopar. Court in the Act (1983) es de los grandes discos del heavy británico, y lo raro es que la vuelta está a su altura: Life Sentence (2013), Atom by Atom (2015), Cruel Magic (2018), Earth Infernal (2022) y Songs in Crimson (2024), sin un disco flojo. Entrada: Court in the Act, luego Life Sentence.", origin: "rec", pick: true },
  { name: "Cirith Ungol", genre: "Epic Heavy / Doom", y: 1972, p: 3, via: "Iron Maiden", desc: "Heavy y doom épico de culto de California, con la voz rasgada y singular de Tim Baker. King of the Dead (1984) y One Foot in Hell, y la vuelta con Forever Black (2020), aclamada. Entrada: King of the Dead.", origin: "rec", pick: true },
  { name: "Slough Feg", genre: "Celtic Heavy Metal", y: 1990, p: 2, via: "Iron Maiden", desc: "Heavy metal de San Francisco con las guitarras gemelas de Thin Lizzy, escalas y aires del folk celta y la época de Di'Anno en Iron Maiden: temas con muchas secciones y galope, cantados con voz de narrador. Muy parejos de Twilight of the Idols (1998) a Down Among the Deadmen (2000), Traveller (2003), un disco conceptual de ciencia ficción, y Hardworlder (2007). Entrada: Traveller.", origin: "rec", pick: true },
  { name: "Atlantean Kodex", genre: "Epic Heavy Metal (DE)", y: 2005, p: 2, via: "Iron Maiden", desc: "Epic metal alemán monumental y atmosférico: temas largos, lentos y narrativos, con guitarras gemelas y coros. The Golden Bough (2010), The White Goddess (2013), la cumbre, y The Course of Empire (2019). Entrada: The White Goddess.", origin: "rec", pick: true },
  { name: "Visigoth", genre: "Epic Heavy Metal", y: 2010, p: 2, via: "Iron Maiden", desc: "Epic heavy metal de Salt Lake City, melódico, épico y con pegada: The Revenant King (2015) y Conqueror's Oath (2018). Entrada: Conqueror's Oath.", origin: "rec", pick: true },
  { name: "Eternal Champion", genre: "Epic Heavy Metal", y: 2012, p: 2, via: "Iron Maiden", desc: "Epic heavy metal de Texas, de espada y brujería, con riffs muy bien escritos y la voz de Jason Tarpey: The Armor of Ire (2016) y Ravening Iron (2020). En marzo de 2026 sacaron el EP Friend of War y anunciaron su tercer disco para este año. Entrada: Ravening Iron.", origin: "rec", pick: true },
  { name: "Nevermore", genre: "Prog / Power Metal", y: 1992, p: 2, via: "Iron Maiden", desc: "Metal progresivo y oscuro de Seattle: Jeff Loomis escribe riffs de siete cuerdas con disonancia y solos técnicos, y Van Williams toca con dinámica real bajo la voz dramática de Warrel Dane. Dead Heart in a Dead World (2000) y This Godless Endeavor (2005) son lo más completo. Warrel Dane murió en 2017. Entrada: Dead Heart in a Dead World.", origin: "rec", pick: true },
  { name: "Crimson Glory", genre: "Prog Metal", y: 1982, p: 2, via: "Iron Maiden", desc: "Metal progresivo de los ochenta construido sobre la voz aguda de Midnight, que canta como un instrumento solista por encima de guitarras gemelas armonizadas y estructuras de varias partes. Su obra fuerte son dos discos, Crimson Glory (1986) y Transcendence (1988); lo posterior pierde ese nivel. Entrada: Transcendence.", origin: "rec", pick: true },
  { name: "Khemmis", genre: "Doom / Heavy Metal", y: 2012, p: 3, via: "Iron Maiden", desc: "Doom y heavy melódico de Denver con guitarras gemelas y mucha emoción, muy parejo pero dentro del molde. Hunted (2016). Entrada: Hunted.", origin: "rec", pick: true },
  { name: "Unto Others", genre: "Gothic Heavy Metal", y: 2017, p: 2, via: "Iron Maiden", desc: "Heavy melódico con tinte gótico y post-punk que evoluciona disco a disco, antes llamados Idle Hands: Mana (2019, como Idle Hands), Strength (2021) y Never, Neverland (2024). Entrada: Strength.", origin: "rec", pick: true },
  { name: "Sadus", genre: "Technical Thrash", y: 1984, p: 2, via: "Iron Maiden", desc: "Thrash con el bajo fretless de Steve DiGiorgio al frente, melódico y vertiginoso bajo riffs muy rápidos. Illusions (1988), Swallowed in Black (1990) y A Vision of Misery (1992), los tres a gran nivel; lo de 1997 y 2006 baja, y The Shadow Inside (2023) vuelve bien. Entrada: Swallowed in Black.", origin: "rec", pick: true },
  { name: "Smoulder", genre: "Epic Doom Metal (CA)", y: 2013, p: 3, via: "Iron Maiden", desc: "Doom y heavy épico canadiense de espada y brujería, con Sarah Ann al frente, grandilocuente y dentro del molde. Entrada: Times of Obscene Evil and Wild Daring.", origin: "rec", pick: true, female: true },
  { name: "In Solitude", genre: "Heavy / Gothic Metal (SE)", y: 2002, p: 2, via: "Iron Maiden", desc: "De culto a Mercyful Fate a un heavy oscuro con post-punk gótico: In Solitude (2008), The World. The Flesh. The Devil (2011) y Sister (2013), cada uno distinto del anterior. Se separaron en 2015. Entrada: Sister.", origin: "rec", pick: true, c: 1 },

  // ----- DETHKLOK (melodeath técnico-melódico / batería monstruosa) -----
  { name: "Brendon Small's Galaktikon", genre: "Melodic Death / Prog", y: 2012, p: 2, via: "Dethklok", desc: "Ópera espacial en forma de melodeath progresivo, escrita por Brendon Small con Gene Hoglan a la batería: más melódica y con más desarrollo que Dethklok, sin la caricatura, con temas largos, guitarras armonizadas y solos con recorrido. Galaktikon (2012) y Galaktikon II: Become the Storm (2017). Entrada: Galaktikon II.", origin: "rec", pick: true },
  { name: "The Black Dahlia Murder", genre: "Melodic Death", y: 2001, p: 2, via: "Dethklok", desc: "Melodeath de Michigan rápido y técnico, con riffs de trémolo melódicos, blast beats y la voz de Trevor Strnad alternando grave y agudo. Muy parejos de Nocturnal (2007) a Verminous (2020); Strnad murió en 2022, y Servitude (2024), con Brian Eschbach a la voz, mantiene el nivel. Entrada: Nocturnal.", origin: "rec", pick: true },
  { name: "Inferi", genre: "Technical Melodic Death", y: 2006, p: 2, via: "Dethklok", desc: "Tech death melódico de Nashville, épico y teatral, con shred neoclásico a dos guitarras y teclados orquestales. The Path of Apotheosis (2014) es la cumbre; Revenant (2018), Vile Genesis (2021) y Heaven Wept (2026) siguen la línea. Entrada: The Path of Apotheosis.", origin: "rec", pick: true },
  { name: "Arsis", genre: "Technical Melodic Death", y: 2000, p: 2, via: "Dethklok", desc: "Death melódico y técnico con leads neoclásicos vertiginosos, y la escritura de guitarra de James Malone en el debut es densa y melódica a la vez. Pero la carrera no lo sostiene: A Celebration of Guilt (2004) tuvo elogio casi unánime y lo que vino después se recibió bastante peor, con Starve for the Devil descrito como más simple que lo anterior. El mapa: A Celebration of Guilt (2004) es la cumbre; United in Regret (2006) está cerca; We Are the Nightmare (2008), Starve for the Devil (2010) y Unwelcome (2013) simplifican, y Visitant (2018) recupera algo de la densidad del principio. Entra por A Celebration of Guilt.", origin: "rec", pick: true },
  { name: "Aenimus", genre: "Prog / Tech Death", y: 2009, p: 2, via: "Dethklok", desc: "Death técnico y progresivo sinfónico y conceptual de California, melódico y muy técnico. El mapa: dos discos, Transcendence (2016) y Dreamcatcher (2019), el más ambicioso. Entrada: Dreamcatcher.", origin: "rec", pick: true },
  { name: "Equipoise", genre: "Neoclassical Tech Death", y: 2016, p: 2, via: "Dethklok", desc: "Supergrupo de death técnico neoclásico con guitarra de raíz flamenca y shred melódico. Demiurgus (2019). Entrada: Demiurgus.", origin: "rec", pick: true },
  { name: "Gloryhammer", genre: "Symphonic Power Metal", y: 2010, p: 3, via: "Dethklok", desc: "Power sinfónico cómico-épico de fantasía espacial, técnicamente impecable, con el humor como forma; la música en sí es power de plantilla. Tales from the Kingdom of Fife (2013) y Space 1992: Rise of the Chaos Wizards (2015) son lo mejor; Space 1993: Wrath of Kor-Virliath (2026) es el último. Entrada: Space 1992.", origin: "rec", pick: true },
  { name: "Powerglove", genre: "Instrumental / VGM Metal", y: 2005, p: 3, via: "Dethklok", desc: "Metal instrumental con temas de música de videojuegos, técnico y juguetón, dentro de una fórmula fija. Entrada: Metal Kombat for the Mortal Man.", origin: "rec", pick: true },
  { name: "Aether Realm", genre: "Melodic Death / Folk", y: 2011, p: 2, via: "Dethklok", desc: "Melodeath y folk de Carolina del Norte con guitarras muy técnicas y un rango real, de lo épico y serio a lo cómico, sin perder identidad. Tarot (2017) y Redneck Vikings from Hell (2020); Season of Bloodshed es de 2026. Entrada: Tarot.", origin: "rec", pick: true },

  // ----- DEATH METAL (el anti-Cannibal Corpse: claridad, sustancia, evolución) -----
  { name: "Blood Incantation", genre: "Progressive Death Metal", y: 2011, p: 1, via: "Death metal", desc: "Piezas de veinte minutos construidas por secciones que no vuelven, con la producción abierta a propósito para que se distinga cada capa. Starspawn (2016) y Hidden History of the Human Race (2019) son death progresivo de primer nivel, Timewave Zero (2022) es un disco ambiental de sintetizadores, y Absolute Elsewhere (2024) integra el sintetizador analógico como instrumento estructural, con la crítica muy dividida entre la euforia y el rechazo. Entrada: Hidden History of the Human Race.", origin: "rec", pick: true, c: 1 },
  { name: "Bolt Thrower", genre: "Death Metal (UK)", desc: "Riffs a medio tiempo muy graves sobre doble bombo sencillo, melodías de guitarra cortas y efectivas, y un peso enorme sostenido sin cambiar de marcha. Hacían una sola cosa a propósito y la hacían muy bien, pero de complejidad instrumental hay poca. Entra por Those Once Loyal.", origin: "rec", p: 3, y: 1986, c: 2 },
  { name: "Pestilence", genre: "Death / Jazz Fusion (NL)", y: 1986, p: 2, via: "Death metal", desc: "Evolucionaron de thrash-death a death con fusión jazz: en Spheres (1993) meten sintetizador de guitarra y bajo fretless, con armonía que se sale del género por completo. Malleus Maleficarum (1988), Consuming Impulse, Testimony of the Ancients y Spheres son cuatro discos de primer nivel, cada uno distinto; la vuelta desde 2009 es muy floja. Entrada: Testimony of the Ancients, luego Spheres.", origin: "rec", pick: true, c: 1 },
  { name: "Entombed", genre: "Death / Death'n'Roll (SE)", y: 1987, p: 2, via: "Death metal", desc: "Inventaron el sonido de guitarra sierra del death sueco en Left Hand Path (1990) y Clandestine, y luego viraron al death'n'roll en Wolverine Blues (1993), un cambio de género real. Lo posterior es desigual, con buenos discos como Uprising y Morning Star. Entrada: Left Hand Path.", origin: "rec", pick: true, c: 1 },
  { name: "Tomb Mold", genre: "Progressive Death (CA)", y: 2016, p: 2, via: "Death metal", desc: "De Toronto: pasaron del death de la vieja escuela de Primordial Malignity (2017) y Manor of Infinite Forms a un death progresivo, atmosférico y con aire de jazz en Planetary Clairvoyance (2019) y The Enduring Spirit (2023). Entrada: The Enduring Spirit.", origin: "rec", pick: true, c: 1 },
  { name: "Horrendous", genre: "Progressive Death Metal", y: 2009, p: 2, via: "Death metal", desc: "Death de Filadelfia con melodía, progresión y composición excelente, en una producción limpia y cálida; cada disco crece. Ecdysis (2014), Anareta (2015), Idol (2018) y Ontological Mysterium (2023). Entrada: Anareta.", origin: "rec", pick: true },
  { name: "Sweven (Morbus Chron)", genre: "Progressive Death (SE)", y: 2007, p: 2, via: "Death metal", desc: "Morbus Chron pasó del death de la vieja escuela de Sleepers in the Rift (2011) al death psicodélico y progresivo de Sweven (2014), atmosférico y bello, y su cantante y guitarrista Robert Andersson siguió esa línea con el proyecto Sweven en The Eternal Resonance (2020). Entrada: Sweven.", origin: "rec", pick: true, c: 1 },
  { name: "Autopsy", genre: "Death / Doom Metal", y: 1987, p: 2, via: "Death metal", desc: "Death y doom sucios con muchísimo carácter: tempos que pasan del arrastre al galope, riffs raros y memorables y Chris Reifert tocando la batería y cantando. Severed Survival (1989) y Mental Funeral (1991) son la cumbre, y la vuelta desde Macabre Eternal (2011) mantiene un nivel sólido. Entrada: Mental Funeral.", origin: "rec", pick: true },
  { name: "Asphyx", genre: "Death / Doom (NL)", y: 1987, p: 2, via: "Death metal", desc: "Death y doom holandés demoledor, de riffs memorables y la voz inconfundible de Martin van Drunen, con la pesadez al servicio de la identidad. The Rack (1991) y Last One on Earth son la cumbre, y Deathhammer (2012) y Necroceros (2021) mantienen el nivel. Entrada: The Rack.", origin: "rec", pick: true },
  { name: "Defeated Sanity", genre: "Brutal Tech Death (DE)", y: 1994, p: 2, via: "Death metal", desc: "Brutal death alemán con armonía de jazz y fusión y una batería espectacular, la de su fundador Lille Gruber, que cambia de figura constantemente bajo riffs de subdivisión retorcida. Passages into Deformity (2013), Disposal of the Dead // Dharmata (2016), la mitad de ella de death técnico de la vieja escuela, The Sanguinary Impetus (2020) y Chronicles of Lunacy (2024) son la cumbre. Entrada: Passages into Deformity.", origin: "rec", pick: true },
  { name: "Artificial Brain", genre: "Dissonant Tech Death", y: 2011, p: 2, via: "Death metal", desc: "Death técnico disonante y cósmico de Nueva York: riffs de acordes abiertos y disonantes que se estiran como ciencia ficción, con la batería cambiando de figura sin parar. Labyrinth Constellation (2014), Infrared Horizon y Artificial Brain (2022); Antillia sale en noviembre de 2026. Entrada: Labyrinth Constellation.", origin: "rec", pick: true },
  { name: "Demilich", genre: "Avant Death Metal (FI)", y: 1990, p: 2, via: "Death metal", desc: "[Comodín] Death finlandés de otro planeta: una voz gutural tan grave que parece un efecto, riffs de guitarra con cambios de compás y figuras que nadie más tocaba en 1993, y títulos kilométricos. Un solo disco, Nespithe (1993), y nada suena igual. Entrada: Nespithe.", origin: "rec", pick: true, c: 3 },
  { name: "StarGazer", genre: "Avant Death / Black (AU)", y: 1997, p: 2, via: "Death metal", desc: "[Comodín] Death y black avant australiano donde el bajo de Damon Good lleva la voz principal con fraseo jazzístico y sonido limpio, no distorsionado, sobre estructuras que no se repiten y batería de aire progresivo. The Scream That Tore the Sky (2005), A Great Work of Ages (2010) y Psychic Secretions (2014), muy parejos. Entrada: A Great Work of Ages.", origin: "rec", pick: true, c: 3 },

  // ----- SIAMES 1ª vuelta (atmosférico/moody, electrónica bien integrada) -----
  { name: "The Neighbourhood", genre: "Alt Rock / Moody", y: 2011, p: 3, via: "Siames", desc: "Alt rock oscuro y atmosférico de California con toques de R&B y electrónica, de canciones sencillas y producción muy cuidada. I Love You. (2013) y Wiped Out! (2015). Entrada: Wiped Out!", origin: "rec", pick: true },
  { name: "Half Moon Run", genre: "Indie Rock (CA)", y: 2010, p: 2, via: "Siames", desc: "Indie canadiense de arreglos intrincados: armonías vocales a tres voces, percusiones repartidas entre varios miembros y guitarras que se cruzan en ritmos desplazados. Dark Eyes (2012) y Sun Leads Me On (2015) son lo mejor. Entrada: Dark Eyes.", origin: "rec", pick: true },
  { name: "Daughter", genre: "Indie / Atmospheric (UK)", y: 2010, p: 3, via: "Siames", desc: "Indie atmosférico británico: guitarras con reverb que se construyen en crescendos y la voz frágil de Elena Tonra. Bonito y cinematográfico, pero de escritura sencilla. If You Leave (2013), Not to Disappear y Stereo Mind Game (2023). Entrada: If You Leave.", origin: "rec", pick: true, female: true },
  { name: "Men I Trust", genre: "Dream Pop / Indie (CA)", y: 2014, p: 2, via: "Siames", desc: "Dream pop de Montreal con acordes de jazz, el bajo de Jessy Caron llevando grooves melódicos y una atmósfera nocturna: más interesante instrumentalmente de lo que parece por la calma. Oncle Jazz (2019), Untourable Album y la pareja Equus Asinus y Equus Caballus (2025). Entrada: Oncle Jazz.", origin: "rec", pick: true, female: true },
  { name: "Crumb", genre: "Psych Indie / Jazz", y: 2016, p: 3, via: "Siames", desc: "Indie psicodélico de Brooklyn con acordes de jazz, líneas de bajo que se mueven solas y una atmósfera densa y onírica. Jinx (2019), Ice Melt (2021) y AMAMA (2024). Entrada: Jinx.", origin: "rec", pick: true, female: true },
  { name: "The Marías", genre: "Dream Pop / Psych Soul", y: 2016, p: 3, via: "Siames", desc: "Dream pop y soul psicodélico de Los Ángeles, bilingüe, con producción muy cuidada y arreglos elegantes pero sencillos. CINEMA (2021) y Submarine (2024). Entrada: Submarine.", origin: "rec", pick: true, female: true },
  { name: "Khruangbin", genre: "Psych Funk / Instrumental", y: 2010, p: 3, via: "Siames", desc: "Trío de funk psicodélico casi instrumental: el bajo de Laura Lee lleva el groove, la guitarra de Mark Speer toma escalas tailandesas, surf y dub, y la batería es mínima a propósito. Atmosférico y elegante, pero sencillo por dentro. Con Todo el Mundo (2018) y A La Sala (2024). Entrada: Con Todo el Mundo.", origin: "rec", pick: true },
  { name: "Joywave", genre: "Indie Electronic Rock", y: 2010, p: 3, via: "Siames", desc: "Indie electrónico y alt rock de Rochester, atmosférico y sarcástico. Entrada: Content.", origin: "rec", pick: true },
  { name: "Metronomy", genre: "Indie Electronic (UK)", y: 1999, p: 3, via: "Siames", desc: "Indie electrónico británico que cambia de piel entre discos, con groove raro y producción ingeniosa, dentro de la canción pop. The English Riviera (2011). Entrada: The English Riviera.", origin: "rec", pick: true, c: 1 },
  { name: "El Mató a un Policía Motorizado", genre: "Indie / Noise Pop (AR)", y: 2003, p: 3, via: "Siames", desc: "Indie y noise pop argentino de La Plata, atmosférico y melódico, de guitarras con fuzz en capas y canciones sencillas. La síntesis O'Konor (2017). Entrada: La síntesis O'Konor.", origin: "rec", pick: true }
];

// ===========================================================================
// === REPASO 2026 — auditoría de huecos (10 tandas) =========================
// Ancestros que faltaban, géneros coloreados sin sus fundadores, y el sesgo
// anti-Cannibal Corpse corregido. Categoría verificada con test estricto de
// comodín: (A) Cat1 Y Cat2 a la vez, o (B) la música misma no tiene par.
// ===========================================================================
const REPASO_2026 = [
  // ----- RAÍCES PERDIDAS / ART ROCK -----
  { name: "Björk", genre: "Art Pop / Experimental", y: 1993, p: 2, c: 1, female: true, via: "Art rock", desc: "Cada disco monta un sistema instrumental distinto y compone dentro de él: Homogenic son cuerdas contra beats rotos, Vespertine microbeats y arpa, Medúlla casi solo voces, Utopia un banco de flautas, y la voz va escrita como línea melódica compleja, no como recitado encima. De Debut (1993) a Post, Homogenic y Vespertine (2001) es una racha impecable; después alterna aciertos como Vulnicura con discos más dispersos como Volta o Fossora. Entrada: Homogenic.", origin: "rec", pick: true },
  { name: "Talking Heads", genre: "Art Rock / Post-Punk", y: 1975, p: 1, c: 1, via: "Art rock", desc: "De post-punk esquelético a orquesta polirrítmica en cuatro años. Remain in Light está construido al revés de lo normal: cada músico toca una sola figura corta que se repite sin variar, y la pieza surge de superponerlas hasta que se desfasan entre sí, con Chris Frantz y Tina Weymouth sosteniendo un groove afrobeat inalterable mientras Adrian Belew mete guitarra tratada por encima. Byrne canta como si declamara. El mapa: Talking Heads: 77 (1977) es el post-punk esquelético; More Songs About Buildings and Food (1978), Fear of Music (1979) y Remain in Light (1980) son la cumbre, y Speaking in Tongues (1983) está cerca; Little Creatures (1985), True Stories (1986) y Naked (1988) van al pop y bajan. Entrada: Remain in Light.", origin: "rec", pick: true },
  { name: "Peter Gabriel", genre: "Art Rock / Art Pop (UK)", y: 1977, p: 2, c: 1, via: "Art rock", desc: "En solitario fue mucho más raro que en Genesis: en su tercer disco prohibió los platillos a Phil Collins y de ahí salió el sonido de batería con compuerta que marcó los ochenta, y el cuarto se construye sobre el Fairlight y polirritmias de percusión africana. So y Us lo llevaron al pop sin perder esa base rítmica. El mapa: los cuatro primeros, Peter Gabriel 1 a 4 (1977-1982), son la cumbre; So (1986) es su cara pop, Passion (1989), la banda sonora de La última tentación de Cristo, es lo más aventurado, y Us (1992), Up (2002) e i/o (2023) se mantienen. Entrada: III (Melt).", origin: "rec", pick: true },
  { name: "Tom Waits", genre: "Experimental / Art Rock", y: 1973, p: 2, c: 1, via: "Art rock", desc: "De crooner de jazz a una percusión de chatarrería: desde Swordfishtrombones (1983) graba con marimbas, objetos metálicos y bombos golpeados, sobre la guitarra angulosa de Marc Ribot y metales desafinados a propósito, con su voz rota como centro teatral. Swordfishtrombones, Rain Dogs, Bone Machine (1992), Mule Variations y Blood Money (2002) son la etapa fuerte. Entrada: Rain Dogs.", origin: "rec", pick: true },
  { name: "Deep Purple", genre: "Hard Rock (clásico)", y: 1968, p: 1, via: "Raíces perdidas", desc: "Jon Lord toca el órgano Hammond a través de amplificadores Marshall y con distorsión, así que compite con la guitarra en volumen y timbre en lugar de acompañar, y él y Blackmore se turnan solos largos improvisados en directo como si fuera un duelo de jazz. Ian Paice a la batería toca con mano izquierda rapidísima y swing, no a golpe recto. El mapa: los tres primeros (1968-1969) son rock psicodélico; con Gillan y Glover, In Rock (1970), Fireball, Machine Head (1972) y el directo Made in Japan son la cumbre; con Coverdale y Hughes, Burn (1974) y Stormbringer están cerca, y Come Taste the Band (1975), con Tommy Bolin, cierra la primera vida; Perfect Strangers (1984) es la mejor vuelta, lo de finales de los ochenta y los noventa baja, y con Steve Morse, de Purpendicular (1996) a Whoosh! (2020), y con Simon McBride en =1 (2024), se mantienen dignos. Entrada: Machine Head, y Made in Japan para los duelos.", origin: "rec", pick: true },
  { name: "Portishead", genre: "Trip-Hop / Experimental", y: 1991, p: 2, c: 1, female: true, via: "Art rock", desc: "Trip-hop de Bristol con instrumentación de verdad: scratches y samples de bandas sonoras sobre batería tocada y guitarras de spaghetti western, bajo la voz de Beth Gibbons. Dummy (1994) y Portishead (1997) fijan el género, y once años después Third (2008) lo rompe con krautrock motorik y sintetizadores abrasivos. Entrada: Third, luego Dummy.", origin: "rec", pick: true },
  { name: "Brian Eno", genre: "Ambient / Art Rock", desc: "En los discos de canción como Another Green World alterna piezas cortas de rock angular con miniaturas instrumentales tratadas hasta que el instrumento original no se reconoce, y en los ambientales monta bucles de cinta de duraciones distintas que se desfasan entre sí, de modo que la combinación tarda horas en repetirse y la pieza nunca suena igual dos veces. El mapa: la etapa de canción va de Here Come the Warm Jets (1974) y Taking Tiger Mountain a Another Green World (1975) y Before and After Science (1977); la ambiental, de Discreet Music (1975) y Music for Airports (1978) a Apollo (1983) y Thursday Afternoon (1985). Lo de los noventa es más irregular, y vuelve bien con Reflection (2017) y FOREVERANDEVERNOMORE (2022). Entra por Another Green World o Music for Airports.", origin: "rec", p: 1, y: 1971, c: 1 },
  { name: "Massive Attack", genre: "Trip-Hop / Electronic", y: 1988, p: 2, via: "Art rock", desc: "Trip-hop de Bristol construido sobre un bajo de dub como cimiento, breaks lentos y samples de soul y de rock, con voces invitadas que cambian de tema a tema; en Mezzanine meten guitarras distorsionadas y una atmósfera claustrofóbica y oscura. El mapa: Blue Lines (1991) abre; Protection (1994) sigue; Mezzanine (1998) es la cumbre; 100th Window (2003), casi solo de Robert Del Naja, y Heligoland (2010) bajan; tras el EP Eutopia (2020) sacaron Boots on the Ground con Tom Waits (abril de 2026), y han anunciado más material para 2026, fuera de Spotify. Entrada: Mezzanine.", origin: "rec", pick: true },
  { name: "Arca", genre: "Experimental / Electronic", y: 2012, p: 3, c: 1, female: true, via: "Art rock", desc: "Alejandra Ghersi: electrónica de diseño sonoro fragmentado, con el reguetón, la ópera y el club deconstruidos sin métrica estable y su voz procesada encima. Arca (2017) y la serie KiCk (2020-2021). Es electrónica pura, donde la textura y la producción pesan más que la escritura instrumental. Entrada: KiCk i.", origin: "rec", pick: true },
  { name: "SOPHIE", genre: "Experimental / Electronic", y: 2013, p: 3, c: 1, female: true, via: "Art rock", desc: "Inventó un lenguaje de diseño sonoro: en vez de samples, sintetizaba texturas físicas (metal golpeado, plástico, burbujas) desde cero, dentro de canciones de pop. Su único disco es Oil of Every Pearl's Un-Insides (2018); murió en 2021. Electrónica pura, más de textura que de escritura instrumental. Entrada: Oil of Every Pearl's Un-Insides.", origin: "rec", pick: true },
  { name: "Captain Beefheart", genre: "Avant-garde / Experimental", y: 1964, p: 1, c: 3, via: "Art rock", desc: "[Comodín] Blues del Delta desmontado: en Trout Mask Replica (1969) cada instrumento toca en su propio compás y tonalidad a la vez, con dos guitarras que se cruzan en líneas angulosas escritas nota a nota y la batería de John French sosteniendo el conjunto. Lo sostienen Safe as Milk, Lick My Decals Off, Baby, Clear Spot y, tras el bache de los dos discos de 1974 (Unconditionally Guaranteed y Bluejeans & Moonbeams), Shiny Beast, Doc at the Radar Station e Ice Cream for Crow (1982), el último. Entrada: Clear Spot, luego Trout Mask Replica.", origin: "rec", pick: true },
  { name: "Dead Can Dance", genre: "Art Pop / Ethereal / Gothic", desc: "[Comodín] Piezas lentas y modales sobre instrumentación medieval, bizantina y del norte de África, construidas por repetición y drone, con la voz flotando encima. Muy bello y muy hipnótico, pero armónicamente estático y sin apenas desarrollo ni cambios de estructura: es atmósfera, no complejidad, en un mundo sonoro que no tiene par. Entra por Within the Realm of a Dying Sun.", origin: "rec", p: 3, y: 1981, c: 3 },
  { name: "The Residents", genre: "Avant-garde / Experimental", desc: "[Comodín] Deconstruyen la canción popular americana dejándola deliberadamente tosca y desafinada, con electrónica primitiva, melodías de canción infantil retorcidas y voces procesadas hasta lo desagradable. Es incómodo a propósito y estructuralmente simple. Eskimo (1979) y The Commercial Album son lo más logrado de una obra enorme y muy irregular. Entrada: Eskimo.", origin: "rec", p: 3, y: 1969, c: 3 },

  // ----- CANTERBURY / RIO / ZEUHL -----
  { name: "Soft Machine", genre: "Prog Rock / Jazz Fusion", y: 1966, p: 1, c: 1, via: "Canterbury/RIO", desc: "Mutación brutal en pocos años: de pop psicodélico en The Soft Machine (1968) y Volume Two a suites de jazz-rock en Third (1970), cuatro caras con una sola pieza cada una, y de ahí a la fusión instrumental de Fourth, Fifth, Six, Seven y Bundles (1975), con Allan Holdsworth. Robert Wyatt era el batería y el cantante hasta 1971. Solo Land of Cockayne (1981) baja; la formación actual volvió con Hidden Details (2018), Other Doors (2023) y Thirteen (marzo de 2026). Entrada: Third.", origin: "rec", pick: true },
  { name: "Gong", genre: "Prog Rock / Psychedelic", y: 1967, p: 2, c: 1, via: "Canterbury/RIO", desc: "Dos bandas en una. La trilogía Radio Gnome de Daevid Allen, Flying Teapot, Angel's Egg y You (1973-1974), es space rock psicodélico con glissando de guitarra, saxo y mucho humor; Pierre Moerlen's Gong, de Gazeuse! (1976) a Expresso II, es fusión instrumental liderada por vibráfono, marimba y percusión. Allen murió en 2015 y el grupo sigue con Kavus Torabi. Entrada: Angel's Egg, luego Gazeuse!", origin: "rec", pick: true },
  { name: "Robert Wyatt", genre: "Canterbury / Art Rock (UK)", y: 1970, p: 3, c: 1, via: "Canterbury/RIO", desc: "Tras Soft Machine y Matching Mole, su obra en solitario convierte los teclados y la percusión en texturas: Rock Bottom (1974) son piezas lentas y frágiles sobre capas de teclado, con la trompeta de Mongezi Feza y la viola de Fred Frith entrando como voces sueltas. Es un disco único, pero lo que sigue, de Ruth Is Stranger Than Richard a Shleep y Comicopera, es sobre todo canción frágil de voz y textura, con poca sustancia instrumental. Entrada: Rock Bottom.", origin: "rec", pick: true },
  { name: "Hatfield and the North", genre: "Prog Rock (Canterbury)", y: 1972, p: 2, via: "Canterbury/RIO", desc: "El corazón cálido del Canterbury: Pip Pyle a la batería, Richard Sinclair al bajo y la voz y Dave Stewart a los teclados, complejidad con humor y las Northettes usadas como textura instrumental. Dos discos, Hatfield and the North (1974) y The Rotters' Club (1975), los dos a gran nivel. Entrada: The Rotters' Club.", origin: "rec", pick: true },
  { name: "National Health", genre: "Prog Rock (Canterbury)", y: 1975, p: 2, via: "Canterbury/RIO", desc: "El mismo Dave Stewart en modo compositor de cámara: casi todo instrumental, escritura densa, con compases cambiantes y sin concesiones. National Health (1978), Of Queues and Cures (1978), la cumbre, y D.S. al Coda (1982), homenaje a Alan Gowen. Entrada: Of Queues and Cures.", origin: "rec", pick: true },
  { name: "Henry Cow", genre: "Avant-garde / Experimental", y: 1968, p: 1, via: "Canterbury/RIO", desc: "Avant-prog cruzado con música de cámara y free jazz: partes escritas nota a nota que se abren de golpe a improvisación colectiva, con la guitarra de Fred Frith, el fagot de Lindsay Cooper, la batería de Chris Cutler y compases que no se asientan nunca. Legend (1973), In Praise of Learning (1975), con Dagmar Krause a la voz, y Western Culture (1979), el más compuesto, son la cumbre; Unrest (1974), con más montaje de estudio e improvisación, queda algo por debajo. Entrada: Western Culture, luego In Praise of Learning.", origin: "rec", pick: true, c: 2 },
  { name: "Univers Zero", genre: "Avant-garde / Chamber Rock", y: 1974, p: 1, via: "Canterbury/RIO", desc: "Música de cámara oscura tocada por un grupo de rock: fagot, armonio, violín, clarinete y bajo sobre la batería de Daniel Denis, que fundó y dirige el grupo y hace que el pulso mande sobre todo, en piezas que suenan a réquiem gótico en compases irregulares. Lo sostienen cuarenta años sin un disco flojo, de 1313 (1977) y Heresie a Uzed, Heatwave, The Hard Quest, Implosion y Phosphorescent Dreams (2014). Entrada: Heresie, luego Uzed.", origin: "rec", pick: true, c: 2 },
  { name: "Present", genre: "Avant-garde / Chamber Rock", y: 1979, p: 1, via: "Canterbury/RIO", desc: "El grupo que montó Roger Trigaux al dejar Univers Zero: rock de cámara más agresivo e hipnótico, con riffs disonantes repetidos en compases impares hasta volverse trance y piano, guitarra y batería golpeando juntos como una sola máquina. Prácticamente math rock en 1980. Triskaïdékaphobie (1980), Le poison qui rend fou (1985), No. 6, High Infidelity, Barbaro (ma non troppo) (2009) y su disco de 2024 sostienen ese nivel. Entrada: Triskaïdékaphobie, luego Barbaro.", origin: "rec", pick: true },
  { name: "Banco del Mutuo Soccorso", genre: "Prog Rock (IT)", y: 1969, p: 2, via: "Canterbury/RIO", desc: "Dos teclistas a la vez repartiéndose líneas distintas en lugar de doblarse, con Francesco Di Giacomo cantando en registro casi operístico por encima de estructuras que encadenan secciones sin repetirlas. De Banco del Mutuo Soccorso (1972) y Darwin! a Io sono nato libero (1973), Garofano rosso y Come in un'ultima cena (1976) es la cumbre; en los ochenta se fueron al pop y bajan mucho, una etapa entera. Di Giacomo murió en 2014 y Vittorio Nocenzi volvió con Transiberiana (2019) y Orlando: Le forme dell'amore (2022), a buen nivel. Entrada: Darwin!", origin: "rec", pick: true },
  { name: "Koenjihyakkei", genre: "Avant-garde / Zeuhl (JP)", desc: "[Comodín] Es Magma tocado al doble de velocidad: temas que cambian de compás cada pocos segundos, bajo y teclado al unísono en intervalos incómodos, voces femeninas operísticas en idioma inventado y Tatsuya Yoshida a una batería que no baja el ritmo. Cinco discos y ninguno flojo, de Hundred Sights of Koenji (1994) y II a Viva Koenji!, Angherr Shisspa (2005) y Dhorimviskha (2018). Entrada: Angherr Shisspa.", origin: "rec", p: 1, y: 1991, c: 3 },
  { name: "Ruins", genre: "Avant-garde / Zeuhl (JP)", y: 1985, p: 2, c: 3, via: "Canterbury/RIO", desc: "[Comodín] Dúo de bajo y batería, sin guitarra ni teclados: Tatsuya Yoshida, el de Koenjihyakkei, toca y canta en un idioma inventado sobre un bajo distorsionado que hace de riff, en temas de zeuhl-punk que cambian de compás cada pocos segundos. La obra es enorme y desigual: Burning Stone (1992), Hyderomastgroningem (1995), Symphonica (1998) y Pallaschtom (2000) son lo mejor, y buena parte del resto y de las colaboraciones repite la fórmula. Entrada: Hyderomastgroningem.", origin: "rec", pick: true },
  { name: "Area", genre: "Avant Prog / Jazz Rock (IT)", desc: "Jazz-rock italiano de los setenta y de lo más difícil de seguir del género: modos griegos y balcánicos sobre compases impares que cambian dentro del mismo tema, con secciones de free jazz donde la banda se suelta y vuelve a encajar, y Demetrio Stratos usando la voz como un instrumento más, con armónicos y registros que no suenan a canto convencional. Los cinco discos con él, de Arbeit Macht Frei (1973) a Caution Radiation Area, Crac!, Maledetti y 1978 gli dei se ne vanno, gli arrabbiati restano!, sostienen esa densidad; tras su muerte en 1979, Tic & Tac y Chernobyl 7991 quedan muy por debajo. Entrada: Arbeit Macht Frei.", origin: "rec", p: 1, y: 1972, c: 3 },

  // ----- FUSIÓN JAZZ -----
  { name: "Mahavishnu Orchestra", genre: "Jazz Fusion", y: 1971, p: 2, via: "Fusión jazz", desc: "Billy Cobham toca compases imposibles con potencia de rock y no de jazz, y Jan Hammer al teclado y Jerry Goodman al violín se turnan solos con John McLaughlin a velocidad absurda, todo sobre armonía modal india. The Inner Mounting Flame (1971) y Birds of Fire (1973) son dos de los discos más importantes de la fusión, y The Lost Trident Sessions (grabado en 1973, publicado en 1999) está a su altura. La segunda formación, con Apocalypse (1974) y Visions of the Emerald Beyond (1975), sigue a buen nivel; Inner Worlds (1976) divide, y los dos discos de los ochenta con el mismo nombre bajan mucho. Entrada: The Inner Mounting Flame.", origin: "rec", pick: true },
  { name: "Weather Report", genre: "Jazz Fusion", y: 1970, p: 2, via: "Fusión jazz", desc: "Jaco Pastorius convirtió el bajo fretless en voz cantante principal, con armónicos y acordes, mientras Joe Zawinul usaba los sintetizadores como sección de vientos y Wayne Shorter escribía y soplaba por encima. El grupo cambió de formato varias veces, de la improvisación abstracta de los primeros discos a la escritura densa de Black Market y Heavy Weather. El mapa: de Weather Report (1971) a Heavy Weather (1977), más Night Passage (1980), a gran nivel; Mr. Gone (1978) y la última etapa, de Weather Report (1982) a This Is This (1986), bajan mucho. Entrada: Black Market, luego Heavy Weather.", origin: "rec", pick: true },
  { name: "Return to Forever", genre: "Jazz Fusion", y: 1972, p: 1, via: "Fusión jazz", desc: "Stanley Clarke usa el bajo como voz solista con la agilidad de un saxo, desde 1973 Lenny White lleva la batería con potencia de rock, y las piezas están escritas con temas que vuelven transformados entre los solos, no como cabeza-solo-cabeza. De Return to Forever (1972) a Romantic Warrior (1976) no hay disco flojo; solo Musicmagic (1977), con sección de vientos y más canción, baja. Entrada: Romantic Warrior.", origin: "rec", pick: true },
  { name: "Brand X", genre: "Jazz Fusion", y: 1975, p: 2, via: "Fusión jazz", desc: "Phil Collins tocando fusión de verdad, con compases compuestos y mucho swing, y Percy Jones al bajo fretless, uno de los grandes ignorados del instrumento: líneas melódicas retorcidas, con armónicos y glissandos, en la órbita de Jaco pero más raro. Unorthodox Behaviour (1976), Moroccan Roll (1977) y Masques (1978) son la cumbre; de Product (1979) en adelante bajan. Entrada: Unorthodox Behaviour.", origin: "rec", pick: true },
  { name: "Snarky Puppy", genre: "Jazz Fusion / Funk", y: 2004, p: 2, via: "Fusión jazz", desc: "Big band de fusión grabada en directo en el estudio, con público, dirigida por el bajista Michael League: secciones de vientos y teclados muy escritas, varios baterías y percusionistas y solos que crecen sobre grooves complejos pero respirables. We Like It Here (2014), Culcha Vulcha (2016), Empire Central (2022) y Somni (2025), con la Metropole Orkest. Entrada: We Like It Here, empezando por Lingus.", origin: "rec", pick: true },
  { name: "Hiatus Kaiyote", genre: "Jazz Funk / Soul", y: 2011, p: 2, female: true, via: "Fusión jazz", desc: "Nai Palm al frente de un soul futurista con desplazamientos rítmicos salvajes y armonía retorcida bajo melodías preciosas, con el bajo de Paul Bender muy al frente. Muy parejos: Choose Your Weapon (2015), Mood Valiant (2021) y Love Heart Cheat Code (2024). Entrada: Choose Your Weapon.", origin: "rec", pick: true },
  { name: "Jaga Jazzist", genre: "Jazz Fusion / Electronic (NO)", y: 1994, p: 2, via: "Fusión jazz", desc: "Nu jazz noruego: una big band de unos diez músicos cruzada con post-rock y electrónica bien integrada, con capas y capas de arreglo. A Livingroom Hush (2001), What We Must (2005), One-Armed Bandit (2010) y Pyramid (2020). Entrada: A Livingroom Hush.", origin: "rec", pick: true },
  { name: "DOMi & JD Beck", genre: "Jazz Fusion", y: 2018, p: 2, female: true, via: "Fusión jazz", desc: "Dúo de teclados y batería: DOMi toca armonía de jazz densa con técnica de conservatorio y JD Beck es un fenómeno de la batería, con precisión casi de máquina y fraseo de beat. NOT TiGHT (2022) y WHO ASKED? (31 de julio de 2026), con orquesta en varios temas y una versión instrumental aparte, You Asked!. Entrada: NOT TiGHT.", origin: "rec", pick: true },
  { name: "Egberto Gismonti", genre: "Jazz / Fusion (BR)", y: 1969, p: 2, c: 1, via: "Fusión jazz", desc: "Brasileño que cruza clásica de conservatorio, jazz y música indígena amazónica, y compone igual para piano de concierto que para guitarra de diez cuerdas, con bajo, armonía y melodía tocados a la vez. Muy parejo en ECM: Dança das Cabeças (1977, a dúo con Naná Vasconcelos), Sol do Meio Dia y Infância. El mapa: Dança das Cabeças (1977), con Naná Vasconcelos, Sol do Meio Dia (1978) y Solo (1979) son la cumbre; Sanfona (1981), Infância (1991) y Zig Zag (1996) siguen en ECM. Entrada: Dança das Cabeças.", origin: "rec", pick: true },

  // ----- INDUSTRIAL / POST-ROCK -----
  { name: "Talk Talk", genre: "Art Rock / Post-Rock", y: 1981, p: 2, c: 1, via: "Post-rock", desc: "La reinvención más radical del rock británico: de un synth-pop correcto en The Party's Over (1982) e It's My Life (1984) a The Colour of Spring (1986) y luego a inventar el post-rock. Spirit of Eden (1988) y Laughing Stock (1991) se grabaron con músicos de jazz y de clásica improvisando durante meses a oscuras, y ese material se editó después hasta volverlo composición: silencios enormes, estallidos repentinos, armonías abiertas. Son tres discos enormes y dos que no lo son; el disco en solitario de Mark Hollis (1998) es la continuación. Hollis murió en 2019. Entrada: Spirit of Eden.", origin: "rec", pick: true },
  { name: "Swans", genre: "Experimental / Post-Punk", y: 1982, p: 1, c: 1, via: "Industrial", desc: "La sustancia es la construcción por acumulación: piezas de veinte minutos donde una célula de bajo y batería se repite hasta que el cambio de un solo elemento reordena la pieza entera, con percusión metálica y guitarras en afinaciones abiertas. Los primeros discos, de Filth (1983) a Holy Money, son más brutales que ricos; desde Children of God (1987) y Soundtracks for the Blind (1996), y sobre todo en la etapa reunida, de The Seer (2012) y To Be Kind a The Glowing Man, The Beggar y Birthing (2025), está su mejor escritura. Birthing cerró esa era y el directo final sale en octubre de 2026. Entrada: To Be Kind.", origin: "rec", pick: true },
  { name: "Ministry", genre: "Industrial Metal", desc: "Al Jourgensen empezó haciendo synth-pop (With Sympathy, de 1983, del que reniega públicamente), pasó por EBM con Twitch (1986) y terminó inventando el metal industrial de guitarras. El mapa: The Land of Rape and Honey (1988), The Mind Is a Terrible Thing to Taste (1989) y Psalm 69 (1992) son la cumbre; Filth Pig (1996), lento y pesado, y Dark Side of the Spoon (1999) bajan; la trilogía rapidísima de los dos mil, de Animositisomina (2003) a Houses of the Molé (2004) y Rio Grande Blood (2006), vuelve arriba; Relapse (2012), From Beer to Eternity (2013) y AmeriKKKant (2018) bajan otra vez, y Moral Hygiene (2021) y Hopiumforthemasses (2024) se mantienen. Se acaba: Hate to Go (Take Out or Delivery), el último, sale el 30 de octubre de 2026, y la gira de despedida europea arranca en abril de 2027. Entra por The Land of Rape and Honey o Psalm 69.", origin: "rec", p: 2, y: 1981, c: 1 },
  { name: "Godflesh", genre: "Industrial Metal", desc: "Metal industrial con caja de ritmos en lugar de baterista como decisión estética, riffs lentísimos repetidos sin variación y un bajo enorme que lleva la armonía mientras la guitarra hace de bloque. El mapa: Streetcleaner (1989) es la cumbre y Pure (1992) está cerca; Selfless (1994) mete groove y Songs of Love and Hate (1996), con batería humana, todavía más; Us and Them (1999) coquetea con el drum and bass y es el más flojo, y Hymns (2001) cierra la primera etapa; la vuelta, con A World Lit Only by Fire (2014), Post Self (2017) y Purge (2023), está a la altura. Se está cerrando: Decay, su décimo disco y penúltimo, sale el 25 de septiembre de 2026 en Relapse, y el último se graba a finales de año. Ya no habrá directos (Broadrick pasó por cirugía abdominal), aunque Jesu y JK Flesh siguen. Entra por Streetcleaner.", origin: "rec", p: 1, y: 1988, c: 2 },
  { name: "Skinny Puppy", genre: "Industrial / Electronic", desc: "El pulso nunca es del todo mecánico ni del todo humano: cEvin Key toca en directo una percusión armada con batería acústica, bidones y módulos electrónicos, y la superpone a las secuencias. Y usa el sampler como collage narrativo, no como adorno: las voces y los ruidos cuentan algo en vez de rellenar. El mapa: Bites (1985) y Mind: The Perpetual Intercourse (1986) abren; de Cleanse Fold and Manipulate (1987) a VIVIsectVI (1988), Rabies (1989), Too Dark Park (1990) y Last Rights (1992) está la cumbre; The Process (1996), grabado en plena ruptura, es irregular, y la vuelta, de The Greater Wrong of the Right (2004) a Weapon (2013), baja algo. Se despidieron con una gira en diciembre de 2023. Entra por Too Dark Park o Last Rights.", origin: "rec", p: 1, y: 1982, c: 2 },
  { name: "Author & Punisher", genre: "Industrial Doom", origin: "rec", y: 2004, p: 2, c: 2, via: "Industrial", desc: "Doom industrial de una sola persona: tempo lentísimo y aplastante con la percusión rígida como una máquina, sin swing ninguno, y la voz procesada hasta volverse otra capa de la masa. La dinámica va a tirones en vez de fluir, y eso es lo que lo separa del drone. El mapa: los primeros discos son más de ruido; Ursus Americanus (2012), Women & Children (2013) y Melk en Honing (2015) afinan el sonido, y Beastland (2018) y Krüller (2022), más melódico, son la cumbre. Entrada: Beastland." },
  { name: "Slint", genre: "Post-Rock / Slowcore (US)", y: 1986, p: 3, via: "Post-rock", desc: "Spiderland (1991) fijó el post-rock y el math rock americano: dinámicas de silencio a violencia, compases desplazados y voz hablada. Es austero a propósito: la gracia está en la tensión y en cómo se retiene, no en la riqueza instrumental, y Tweez (1989), el debut, está muy por debajo. Entrada: Spiderland.", origin: "rec", pick: true },
  { name: "This Heat", genre: "Post-Punk / Experimental", desc: "Piezas que arrancan como post-punk y se desmontan en bucles de cinta, drones de órgano y percusión sola, sin volver nunca al punto de partida, con Charles Hayward tocando la batería como voz principal y no como base. Solo dos discos, This Heat (1979) y Deceit (1981), más el EP Health and Efficiency, y los dos sostienen esa escritura: el primero más abstracto y de montaje, Deceit más tenso y rítmico. Entrada: Deceit.", origin: "rec", p: 1, y: 1976, c: 1 },
  { name: "Tortoise", genre: "Post-Rock / Krautrock (US)", y: 1990, p: 2, via: "Post-rock", desc: "Post-rock cruzado con jazz, dub y krautrock: dos baterías a la vez, vibráfono, marimba y John McEntire en la producción. De lo más complejo y menos obvio del género. Millions Now Living Will Never Die (1996) y TNT (1998) son la cumbre; a mediados de los 2000 bajan, y vuelven bien con The Catastrophist (2016) y Touch (octubre de 2025), su primer disco en nueve años. Entrada: Millions Now Living Will Never Die.", origin: "rec", pick: true },
  { name: "Sigur Rós", genre: "Post-Rock (IS)", desc: "Post-rock lentísimo de crescendo, con guitarra frotada generando un colchón sostenido, falsete muy agudo encima y cuerdas y metales entrando en las cimas. Es de una belleza enorme, pero armónicamente estático y de estructura simple: siempre la misma curva de crecer y estallar. ÁTTA (2023) es el último. Entra por Ágætis byrjun.", origin: "rec", p: 3, y: 1994, c: 2 },
  { name: "Mogwai", genre: "Post-Rock (UK)", y: 1995, p: 1, via: "Post-rock", desc: "Treinta años y once discos moviéndose de verdad: de la dinámica silencio-a-muro de Young Team (1997) a los discos con electrónica y voz procesada, como Rave Tapes, y a las bandas sonoras. La constante es que las piezas se construyen por presión acumulada y no por estribillo, casi siempre sin voz. Muy parejos, con Happy Songs for Happy People, The Hawk Is Howling y As the Love Continues (2021) entre lo mejor; The Bad Fire salió en enero de 2025. Entrada: Young Team.", origin: "rec", pick: true },
  { name: "Mono", genre: "Post-Rock (JP)", y: 1999, p: 2, via: "Post-rock", desc: "Pasaron del post-rock de dinámica suave-muro a una composición orquestal de verdad, con secciones de cuerda escritas. Muy parejos de Hymn to the Immortal Wind (2009) a OATH (2024) y Snowdrop (junio de 2026), con orquesta de diez músicos y coro, su primer disco sin Steve Albini, que murió en 2024. Entrada: Hymn to the Immortal Wind.", origin: "rec", pick: true },
  { name: "A Silver Mt. Zion", genre: "Post-Rock / Chamber", y: 1999, p: 2, via: "Post-rock", desc: "El proyecto hermano de Godspeed You! Black Emperor, pero con voz humana quebrada, cuerdas y una crudeza emocional que GY!BE nunca permite. El mapa: He Has Left Us Alone... (2000) y Born into Trouble as the Sparks Fly Upward (2001) son lo más de cámara; Horses in the Sky (2005) y 13 Blues for Thirteen Moons (2008) son la cumbre, y Kollaps Tradixionales (2010) y Fuck Off Get Free We Pour Light on Everything (2014) siguen arriba. Entrada: Horses in the Sky.", origin: "rec", pick: true },
  { name: "Don Caballero", genre: "Math Rock / Instrumental", desc: "Instrumental sin voz, y aquí la batería de Damon Che es el motor compositivo: toca patrones que cambian de métrica bajo riffs de guitarra repetidos, con redobles largos que funcionan como frase melódica, de modo que la tensión viene de la percusión y no de la armonía. Las guitarras trabajan en bucles entrelazados que se desfasan entre sí. El mapa: For Respect (1993), Don Caballero 2 (1995), What Burns Never Returns (1998) y American Don (2000) son la obra, con la misma lógica y distinto grado de densidad; World Class Listening Problem (2006), ya Che con músicos nuevos, se sostiene, y Punkgasm (2008), con voz, es el único flojo. Entra por What Burns Never Returns.", origin: "rec", p: 1, y: 1991, c: 2 },
  { name: "Fantômas", genre: "Avant-garde Metal", y: 1998, p: 2, c: 3, via: "Art rock", desc: "[Comodín] Mike Patton con Dave Lombardo a la batería, Buzz Osborne y Trevor Dunn: metal escrito como partitura, con cortes brutales y la voz como instrumento sin letra. Fantômas (1999) son viñetas de cómic hechas música y Suspended Animation (2005) un calendario de dibujos animados; The Director's Cut (2001) son versiones de bandas sonoras y Delìrivm Cordia (2004), una sola pieza de 74 minutos, es el más árido. Entrada: Fantômas.", origin: "rec", pick: true },

  // ----- BLACKGAZE / ATMOSFÉRICO -----
  { name: "Alcest", genre: "Blackgaze / Shoegaze (FR)", desc: "Capas de guitarra con chorus y delay formando un colchón brillante, voz limpia y suave de Neige casi susurrada y solo a ratos trémolo y blast beats por debajo. Es de las cosas más bellas del metal, pero es paisaje y contraste, no complejidad. Écailles de lune (2010), Shelter, Kodama (2016) y Les Chants de l'Aurore (2024). Entrada: Écailles de lune.", origin: "rec", p: 2, y: 2000, c: 2 },
  { name: "Deafheaven", genre: "Blackgaze / Post-Metal", y: 2010, p: 2, c: 1, via: "Blackgaze", desc: "Sunbather (2013) cruza black metal con shoegaze y post-rock, y desde ahí evolucionan: New Bermuda, más pesado, Ordinary Corrupt Human Love, más luminoso, Infinite Granite (2021), que elimina los gritos por completo y es el más flojo, y Lonely People with Power (2025), que vuelve al peso. Entrada: Sunbather.", origin: "rec", pick: true },
  { name: "Agalloch", genre: "Atmospheric Black / Folk", y: 1995, p: 1, via: "Blackgaze", desc: "Cinco discos y ninguno flojo, con un arco claro: de la crudeza de Pale Folklore (1999) a la construcción larga de The Mantle (2002) y Ashes Against the Grain (2006), donde acústicas y eléctricas se alternan dentro del mismo tema y las piezas se desarrollan por dinámica y no metiendo un riff nuevo cada vez; Marrow of the Spirit (2010) es el más áspero y The Serpent & the Sphere (2014), el último, el más contemplativo. Se separaron en 2016. Entrada: The Mantle.", origin: "rec", pick: true },

  // ----- LATINOAMÉRICA -----
  { name: "Luis Alberto Spinetta", genre: "Prog / Art Rock (AR)", y: 1967, p: 1, c: 1, via: "Latinoamérica", desc: "Guitarrista y compositor que cambió de lenguaje en cada proyecto sin bajar la exigencia armónica: psicodelia en Almendra (1969), rock pesado y retorcido en Pescado Rabioso, con Artaud (1973) como cumbre, jazz-prog oscuro de trío en Invisible, de Durazno sangrando (1975) a El jardín de los presentes (1976), y fusión de acordes abiertos en Spinetta Jade con Alma de diamante (1980). En solitario, A 18' del sol (1977), Kamikaze (1982), Pelusón of Milk (1991), Silver Sorgo (2001) y Para los árboles (2003) están a la misma altura. Lo que une todo es una armonía de jazz aplicada al rock, con progresiones que no resuelven donde se espera; solo el último disco de Spinetta Jade, Madre en años luz (1984), con sonido de sintetizador de los ochenta, baja algo. Murió en 2012. Entrada: Artaud.", origin: "rec", pick: true },
  { name: "Charly García", genre: "Prog / Art Rock (AR)", y: 1972, p: 2, c: 1, via: "Latinoamérica", desc: "De Sui Generis al prog puro de La Máquina de Hacer Pájaros y al jazz-rock de Serú Girán, con Pedro Aznar al bajo fretless llevando líneas melódicas, y de ahí a un solista que absorbe new wave y funk sin perder su armonía de piano. Su racha de los ochenta, Yendo de la cama al living (1982), Clics modernos, Piano bar y Parte de la religión (1987), es de lo más alto del rock en español; de mediados de los noventa en adelante la escritura se deshace. Entrada: Bicicleta (Serú Girán), luego Clics modernos.", origin: "rec", pick: true },
  { name: "Os Mutantes", genre: "Psych Rock / Tropicália (BR)", desc: "Psicodelia brasileña que mete bossa nova, orquestación, distorsión y collage de cinta dentro de la misma canción, con armonías vocales a tres voces y cambios de tono bruscos que rompen la canción a mitad y la recomponen en otro estilo. Absurdo a propósito y radical para su año. De Os Mutantes (1968) a Mutantes, A Divina Comédia ou Ando Meio Desligado (1970), Jardim Elétrico y Mutantes e Seus Cometas no País do Baurets (1972) es una racha impecable; los discos de la vuelta, de Haih (2009) a Zzyzx, quedan muy por debajo. Entrada: Os Mutantes (1968).", origin: "rec", p: 2, y: 1966, c: 1 },
  { name: "Meridian Brothers", genre: "Experimental / Cumbia (CO)", y: 1998, p: 2, c: 1, via: "Latinoamérica", desc: "Eblis Álvarez desarma la cumbia, la salsa y el vallenato y los rearma con electrónica lo-fi, guitarras con efectos y armonía torcida a propósito, con un humor absurdo que no rebaja la escritura. Colombiano y reconocido fuera: Desesperanza (2012), ¿Dónde estás María? (2017) y Cumbia Siglo XXI (2020). Entrada: ¿Dónde estás María?", origin: "rec", pick: true },
  { name: "Divididos", genre: "Hard Rock / Folk (AR)", y: 1988, p: 2, via: "Latinoamérica", desc: "Power trio argentino de Ricardo Mollo y Diego Arnedo: riff pesadísimo con el folklore andino integrado de verdad, no de adorno, y temas que pasan del hard rock al folklore o al blues sin cambiar de formación. El mapa: 40 dibujos ahí en el piso (1989) y Acariciando lo áspero (1991) abren; La era de la boludez (1993) es la cumbre; Otroletravaladna (1995), más experimental, y Gol de mujer (1998) están cerca; Narigón del siglo (2000), Vengo del placard de otro (2002) y Amapola del 66 (2010) siguen; en 2018 regrabaron el debut como Haciendo cosas raras, y Divididos (noviembre de 2025) es el primero de material nuevo en quince años. Entrada: La era de la boludez.", origin: "rec", pick: true },
  { name: "Los Jaivas", genre: "Prog Rock / Folk (CL)", y: 1963, p: 2, via: "Latinoamérica", desc: "Prog andino chileno: charango, zampoña y trutruca dentro de estructuras progresivas largas, con la batería de Gabriel Parra mezclando rock y ritmos del altiplano. La ventana (1972), Los Jaivas (1975, el del indio), Canción del sur (1977) y Alturas de Machu Picchu (1981), que musicaliza el poema de Neruda, son la cumbre; buena parte de lo demás es folk y pop andino más sencillo. Gira de 45 aniversario en 2026-2027. Entrada: Alturas de Machu Picchu.", origin: "rec", pick: true },
  { name: "Fulano", genre: "Jazz Rock / Avant (CL)", y: 1984, p: 2, via: "Latinoamérica", desc: "Jazz-rock chileno instrumental y disonante, con saxo, flauta, teclados y una sección rítmica muy ágil, más la voz de Arlette Jequier en algunos temas: prácticamente el RIO latinoamericano, con carga política. Fulano (1987), En el búnker (1989), El infierno de los payasos (1993) y Trabajos inútiles (1997) son la etapa fuerte; Animal en extinción (2015) baja. Entrada: El infierno de los payasos.", origin: "rec", pick: true },
  { name: "Congreso", genre: "Jazz Fusion / Folk (CL)", y: 1969, p: 2, via: "Latinoamérica", desc: "Fusión chilena desde 1969, liderada por el batería y compositor Sergio Tilo González, así que el pulso manda sobre todo: jazz, prog y folclor latinoamericano en la misma frase, con la voz y los vientos de Francisco Sazo. El mapa: El Congreso (1971) abre; Terra Incógnita (1975) y Viaje por la cresta del mundo (1981) son la cumbre; Pájaros de arcilla (1984) y Para los arqueólogos del futuro (1989) siguen; La canción que te debía (2017) y Luz de flash (2022) son los últimos, y en 2025 celebraron los cincuenta años de Terra Incógnita. Entrada: Viaje por la cresta del mundo.", origin: "rec", pick: true },
  { name: "Milton Nascimento", genre: "Jazz / MPB (BR)", y: 1967, p: 2, via: "Latinoamérica", desc: "Clube da Esquina (1972), a medias con Lô Borges: armonía brasileña de una complejidad que desarma, con acordes que modulan por sitios inesperados, arreglos de cuerda y guitarras de Minas Gerais, y una de las voces más impresionantes que han existido. Milagre dos Peixes (1973) y Minas (1975) están al mismo nivel. Entrada: Clube da Esquina.", origin: "rec", pick: true },
  { name: "Aterciopelados", genre: "Alt Rock (CO)", y: 1990, p: 2, female: true, via: "Latinoamérica", desc: "Andrea Echeverri y Héctor Buitrago: rock alternativo colombiano que mete bambuco, cumbia, rock y electrónica con identidad propia. El Dorado (1995), La pipa de la paz (1996) y Caribe atómico (1998) son la cumbre; luego giran a lo electrónico y lo folk. Entrada: La pipa de la paz.", origin: "rec", pick: true },
  { name: "Kraken", genre: "Heavy / Prog Metal (CO)", y: 1984, p: 3, via: "Latinoamérica", desc: "Heavy metal de Medellín, pionero en Colombia: temas épicos de varias secciones, guitarras dobladas, teclados y la voz de Elkin Ramírez, de registro casi operístico, llevando letras poéticas en español al centro de la canción. La escritura es la del heavy clásico de los ochenta, y su peso está en la voz y en lo que significó para el rock en español más que en la complejidad instrumental. Elkin murió en 2017 y la banda siguió; Kraken VII salió en 2024. Entrada: Kraken II.", origin: "rec", pick: true },
  { name: "Triana", genre: "Prog Rock / Flamenco (ES)", y: 1974, p: 2, via: "Latinoamérica", desc: "Prog andaluz: flamenco de verdad, con cante jondo y compás, dentro de estructuras de rock progresivo, fusión real y no decorado turístico. El patio (1975), Hijos del agobio (1977) y Sombra y luz (1979) son lo que importa; después bajan, y Jesús de la Rosa murió en 1983. Entrada: El patio.", origin: "rec", pick: true },
  { name: "Hermeto Pascoal", genre: "Avant-garde Jazz (BR)", desc: "[Comodín] Multiinstrumentista brasileño que escribía armonía de jazz sobre ritmos del nordeste (baião, frevo, forró) en métricas cambiantes, con temas que pasan de un unísono endiablado de flauta, saxo y teclado a improvisación colectiva y vuelven a encajar. Sacaba melodía del habla: transcribía la entonación de una frase y la armonizaba como tema. A Música Livre de Hermeto Pascoal (1973), Slaves Mass, Zabumbê-bum-á, Cérebro Magnético, Lagoa da Canoa, Município de Arapiraca y Brasil Universo (1986) sostienen un nivel altísimo. Murió el 13 de septiembre de 2025, a los 89 años. Entrada: Slaves Mass.", origin: "rec", p: 1, y: 1964, c: 3 },
  { name: "Los Pirañas", genre: "Psych / Instrumental (CO)", y: 2010, p: 2, via: "Latinoamérica", desc: "Trío instrumental colombiano de Eblis Álvarez, Mario Galeano (Frente Cumbiero) y Pedro Ojeda (Romperayo): guitarra surf y psicodélica retorcida sobre ritmos caribeños y champeta. El mapa: Toma tu jabón Kapax (2011) abre; Historia natural (2019) y Una oportunidad más de triunfar en la vida (2025), su quinto disco, son la cumbre. Entrada: Una oportunidad más de triunfar en la vida (2025).", origin: "rec", pick: true },
  { name: "Santa Sabina", genre: "Gothic / Prog Rock (MX)", y: 1989, p: 2, female: true, via: "Latinoamérica", desc: "Rock gótico y progresivo mexicano con Rita Guerrero, cantante de formación clásica: teatralidad oscura, arreglos con cuerda y estructuras largas, cantado en español. Guerrero murió en 2011. El mapa: Santa Sabina (1992), Símbolos (1994), la cumbre, Babel (1996), el acústico Mar adentro (2000) y Espiral (2003). Entrada: Symbolvm.", origin: "rec", pick: true },
  { name: "Caifanes", genre: "Alt Rock (MX)", y: 1987, p: 2, via: "Latinoamérica", desc: "Rock oscuro mexicano con percusión prehispánica integrada de verdad, la guitarra de Alejandro Marcovich con escalas de raíz árabe y la voz de Saúl Hernández. Cuatro discos y los cuatro a gran nivel: Caifanes (1988), El Diablito, El Silencio (1992), producido por Adrian Belew, y El Nervio del Volcán (1994). Entrada: El Silencio.", origin: "rec", pick: true },
  { name: "Uchpa", genre: "Hard Rock / Blues (PE)", y: 1993, p: 2, via: "Latinoamérica", desc: "Hard rock y blues cantado integramente en quechua, fusionado con huayno, jarawi y pumpin. El nombre significa cenizas, por lo que quedo tras el conflicto armado peruano; su lider Fredy Ortiz fue policia en esa guerra. El mapa: Qauka Kausay (1995) y Qukman Muskiy (2000) son los discos de referencia, y siguen tocando. Entrada: Qauka Kausay.", origin: "rec", pick: true },
  { name: "Secos & Molhados", genre: "Glam Rock / MPB (BR)", y: 1971, p: 2, via: "Latinoamérica", desc: "Glam teatral brasileño de 1973 con maquillaje facial completo y la voz de Ney Matogrosso, un contratenor de registro agudísimo, sobre poesía brasileña musicalizada. Vendieron más que los Beatles en Brasil ese año. Entrada: su homónimo de 1973.", origin: "rec", pick: true },

  // ----- ASIA -----
  { name: "Sheena Ringo", genre: "Art Pop / J-Rock (JP)", desc: "Escribe y arregla ella los discos, y esos arreglos son de verdad (big band de jazz con sección de metales escrita, orquesta de pop de era Showa, electrónica), con armonía que se sale del pop japonés estándar y una voz que fuerza el timbre a propósito. Matiz: Tokyo Jihen no es su banda de acompañamiento sino un grupo donde los demás también componen. El mapa: Muzai Moratorium (1999), Shōso Strip (2000) y Kalk Samen Kuri no Hana (2003), la cumbre; con Tokyo Jihen, de Kyōiku (2004) a Adult (2006) y Variety (2007); en solitario otra vez, Sanmon Gossip (2009), Hi Izuru Tokoro (2014), Sandokushi (2019) y Hōjōya (2024). Entra por Kalk Samen Kuri no Hana.", origin: "rec", p: 2, y: 1998, c: 1, female: true },
  { name: "Boredoms", genre: "Noise / Experimental (JP)", y: 1986, p: 2, c: 1, via: "Asia", desc: "Yamantaka Eye llevó la banda del ruido impenetrable de Soul Discharge y Pop Tatari al trance tribal de Super Ae (1998) y Vision Creation Newsun (1999), piezas largas de repetición con varias baterías a la vez. Después vinieron Seadrum/House of Sun y los conciertos 77 Boadrum, con 77 bateristas en espiral. Entrada: Vision Creation Newsun.", origin: "rec", pick: true },
  { name: "Susumu Hirasawa", genre: "Prog / Electronic (JP)", desc: "[Comodín] Suena a prog electrónico hiperactivo: secuencias muy rápidas y capas de coros procesados de su propia voz apiladas hasta formar un muro, todo sobre escalas del sudeste asiático que le dan giros melódicos que no salen del repertorio occidental. Es denso y agotador en el buen sentido, con muy poco aire. Compuso para Satoshi Kon (Paprika) y para Berserk. unZIP (oct 2025) es su primer Kaku P-MODEL en siete años. El mapa: con P-Model, desde 1979, new wave eléctrico y cada vez más raro; en solitario, de The Ghost in Science (1989) a Sim City (1995), Siren (1996) y Philosopher's Propeller (2000) está la cumbre, y lo que hizo para Satoshi Kon y Berserk va aparte. Entra por Siren.", origin: "rec", p: 2, y: 1979, c: 3 },
  { name: "Yellow Magic Orchestra", genre: "Synth Pop / Electronic (JP)", y: 1978, p: 2, c: 1, via: "Asia", desc: "Sakamoto, Hosono y Takahashi inventaron el technopop trabajando con un secuenciador Roland MC-8 en una época en que había que programar cada nota como datos numéricos, y Takahashi tocaba la batería encima con una precisión mecánica deliberada para casar con la máquina. Armonía de Sakamoto tomada de la clásica y del exotica. Terminaron sampleados por medio hip-hop y por toda la electrónica de Detroit. El mapa: Yellow Magic Orchestra (1978) abre; Solid State Survivor (1979) es la cumbre pop; X∞Multiplies (1980) mete sketches; BGM y Technodelic (1981), más oscuros y con samplers, son lo más experimental; Naughty Boys y Service (1983) cierran, y Technodon (1993) fue la vuelta. Takahashi murió en enero de 2023 y Sakamoto en marzo. Entrada: Solid State Survivor.", origin: "rec", pick: true },
  { name: "Ling Tosite Sigure", genre: "Math Rock / Post-Hardcore (JP)", y: 2002, p: 1, female: true, via: "Asia", desc: "Trío japonés de math y post-hardcore: TK a la guitarra y a un falsete desgarrado, 345 al bajo y a los gritos, y Pierre Nakano en una batería de precisión de metrónomo dentro del caos, con cambios de sección bruscos que encajan al milímetro. El mapa: #4 (2005), Inspiration Is Dead (2007), just A moment (2009), still a Sigure virgin? (2010), i'mperfect (2013), #5 (2018) y Last Aurorally (2023), muy parejos. Entrada: just A moment.", origin: "rec", pick: true },
  { name: "Ningen Isu", genre: "Doom / Heavy Metal (JP)", y: 1987, p: 2, via: "Asia", desc: "Devoción a Black Sabbath desde 1987, pero con kimonos, estética yokai y letras de literatura japonesa, con riffs de doom y heavy setentero muy bien tocados. Mahoroba (noviembre de 2025) es su disco número 24. Entrada: Mahoroba.", origin: "rec", pick: true },
  { name: "Silica Gel", genre: "Art Rock / Psych (KR)", y: 2013, p: 2, via: "Asia", desc: "Art rock psicodélico coreano, lleno de ideas y de cambios dentro del mismo tema, con guitarras procesadas y electrónica; ganaron Musician of the Year en los Korean Music Awards de 2024. Power Andre 99 (2023) y Ballad of You (20 de agosto de 2026). Entrada: Power Andre 99.", origin: "rec", pick: true },
  { name: "Omnipotent Youth Society", genre: "Post-Rock / Folk Rock (CN)", y: 1996, p: 2, via: "Asia", desc: "Post-rock y folk rock chino con arreglos de vientos y una densidad compositiva rarísima para el rock de su país. Dos discos en doce años porque graban hasta quedar conformes: el homónimo de 2010 e Inside the Cable Temple (2020), que vendió doscientas mil copias en medio día. Entrada: el homónimo de 2010.", origin: "rec", pick: true },
  { name: "Chthonic", genre: "Symphonic Black Metal (TW)", y: 1995, p: 2, via: "Asia", desc: "Black metal sinfónico taiwanés con el erhu, el violín de dos cuerdas, llevando melodías completas en contrapunto con el trémolo, no como adorno, y escalas de la música tradicional de la isla dentro del riff. El mapa: los tres primeros (1998-2002) son más crudos; Seediq Bale (2005), Mirror of Retribution (2009), Takasago Army (2011) y Bu-Tik (2013) son la cumbre, y Battlefields of Asura (2018), el último, va más a lo melódico. Su vocalista, Freddy Lim, llegó a legislador nacional. Entrada: Takasago Army.", origin: "rec", pick: true },
  { name: "Fishmans", genre: "Dub / Psych Pop (JP)", y: 1987, p: 2, via: "Asia", desc: "Dub y psicodelia japonesa: bajo y batería de dub muy presentes, teclados y guitarras en capas y la voz aguda de Shinji Sato flotando encima. Kūchū Camp (1996), Long Season (1996), una sola pieza de 35 minutos que se despliega sin repetirse, y Uchū Nippon Setagaya (1997) son la cumbre; Sato murió en 1999, a los 33. Entrada: Long Season.", origin: "rec", pick: true },
  { name: "Senyawa", genre: "Experimental / Folk (ID)", desc: "Dos personas, nada más. Rully Shabara pasa de canto gutural a grito con técnicas vocales extendidas, y Wukir Suryadi hace de base con un instrumento de bambú, piel y cuerdas de acero que pasa por distorsión. El resultado es ritual, crudo e intensísimo de timbre, pero las piezas son de estructura mínima: una idea que se repite y crece, que impacta más de lo que desarrolla. El mapa: Senyawa (2010) abre; Acaraki (2014) y Menjadi (2015) siguen; Sujud (2018) y Alkisah (2021) son la cumbre, y Vajranala (2024) es el último. Entra por Alkisah.", origin: "rec", p: 2, y: 2010, c: 3 },
  { name: "Jambinai", genre: "Post-Metal / Folk (KR)", y: 2009, p: 1, via: "Asia", desc: "El geomungo, el haegeum y el piri llevan las líneas principales, no adornan: pasan de casi silencio a muros de distorsión manteniendo los instrumentos coreanos al frente, con piezas que crecen por acumulación de capas en vez de volver a un estribillo. El mapa: tres discos parejos, Différance (2012), A Hermitage (2016), el más logrado, y ONDA (2019), más oscuro y lento. Coreanos. Entrada: A Hermitage.", origin: "rec", pick: true },
  { name: "Envy", genre: "Screamo / Post-Rock (JP)", y: 1992, p: 2, via: "Asia", desc: "Screamo japonés cruzado con post-rock: crescendos enormes, guitarras que pasan del arpegio limpio al muro y spoken word en japonés encima. A Dead Sinking Story (2003) e Insomniac Doze (2006) son la cumbre, y siguen a buen nivel tras volver en 2018. Entrada: A Dead Sinking Story.", origin: "rec", pick: true },
  { name: "Melt-Banana", genre: "Noise / Punk (JP)", y: 1992, p: 2, female: true, via: "Asia", desc: "Noise punk a hipervelocidad: canciones de 30 segundos ejecutadas con precision de reloj suizo, con la voz de Yasuko Onuki usada como instrumento agudo. El mapa: Speak Squeak Creak (1994) y Scratch or Stitch (1995) abren; Charlie (1998), Teeny Shiny (2000) y Cell-Scape (2003) son la cumbre; Bambi's Dilemma (2007) y Fetch (2013) se mantienen, y 3+5 (2024), el primero en once años, está a la altura. Entrada: Fetch.", origin: "rec", pick: true },
  { name: "Ichiko Aoba", genre: "Folk / Chamber (JP)", y: 2010, p: 2, female: true, via: "Asia", desc: "Folk de camara de delicadeza extrema pero compositivamente denso: Windswept Adan es un ciclo entero sobre una isla imaginaria. Luminescent Creatures (feb 2025) lo hizo con el pianista Taro Umebayashi dirigiendo un ensamble. El mapa: de Kamisori Otome (2010) a 0 (2013) es voz y guitarra de cuerdas de nailon; Mahoroboshiya (2016) y qp (2018) siguen; Windswept Adan (2020) abre la etapa de ensamble y es la cumbre, y Luminescent Creatures (febrero de 2025) está a su altura. Entrada: Windswept Adan.", origin: "rec", pick: true },
  { name: "Acid Mothers Temple", genre: "Psych Rock / Drone (JP)", y: 1995, p: 3, via: "Asia", desc: "Colectivo psicodélico japonés hiperprolífico: drones cósmicos, la guitarra de Kawabata Makoto y jams de veinte minutos que se desarman. Entrada: La Novia.", origin: "rec", pick: true },
  { name: "Second Hand Rose", genre: "Folk Rock / Teatral (CN)", y: 1999, p: 3, via: "Asia", desc: "Rock con errenzhuan, la opera folclorica del noreste chino, y un frontman travestido con estetica de teatro popular. Fusion real, no cosmetica. El mapa: el debut homónimo (2004) y Yule Jianghu (2006) son los discos de referencia. Entrada: su homonimo.", origin: "rec", pick: true },

  // ----- DOOM / GÓTICO -----
  { name: "Ulver", genre: "Experimental / Electronic (NO)", desc: "La reinvención es de verdad la más extrema de la música pesada (black metal noruego, folk acústico, electrónica, trip-hop, cámara, ambient y synth-pop ochentero), pero reinventarse mucho no es lo mismo que ser complejo. Hoy suenan a sintetizadores cálidos y producción impecable sobre estructuras de canción bastante directas, con la voz de Kristoffer Rygg al frente: hermoso y muy bien hecho, no exigente. Neverland (dic 2025) es completamente electrónico. El mapa: Bergtatt (1995), Kveldssanger (1996) y Nattens madrigal (1997) son black y folk; Themes from William Blake's The Marriage of Heaven and Hell (1998) es el puente; Perdition City (2000), Shadows of the Sun (2007) y Messe I.X–VI.X (2013) son la cumbre electrónica y orquestal; The Assassination of Julius Caesar (2017) abre la etapa synth-pop, que sigue en Flowers of Evil (2020), Liminal Animals (2024) y Neverland (2025). Entra por Bergtatt, luego Perdition City.", origin: "rec", p: 2, y: 1993, c: 1 },
  { name: "Paradise Lost", genre: "Gothic / Death Doom (UK)", desc: "Death/doom a medio tiempo con melodías de guitarra muy cantables y armonías gemelas por encima, y voz que alterna limpio grave y gutural. Es melódico y pesado, pero no busca complejidad rítmica ni estructural. La categoría 1 se queda porque la reinvención sí es real, y de las gordas: inventaron el gothic metal con Gothic (1991), se fueron al synth-pop y el darkwave con Host perdiendo media base de fans, y volvieron al death/doom sin pedir perdón. Ascension salió en 2025. Entra por Gothic.", origin: "rec", p: 2, y: 1988, c: 1 },
  { name: "My Dying Bride", genre: "Death Doom (UK)", desc: "Doom lentísimo con el violín como voz principal y no de adorno, largos desarrollos de diez minutos y la voz desgarrada de Aaron Stainthorpe alternando lamento y gutural. Es de una tristeza enorme y muy bien ejecutado, pero estructuralmente es repetición y crecimiento, no complejidad. Turn Loose the Swans (1993), The Angel and the Dark River y The Dreadful Hours (2001) son lo mejor, y A Mortal Binding (2024) mantiene el nivel. Entrada: Turn Loose the Swans.", origin: "rec", p: 2, y: 1990, c: 2 },
  { name: "Candlemass", genre: "Epic Doom Metal (SE)", desc: "Riffs de Leif Edling lentísimos y enormes, repetidos con muy poca variación para que pesen, con la voz operística de Messiah Marcolin encima como contraste. El efecto depende de la repetición y del volumen, no del desarrollo: es doom épico de manual porque ellos escribieron el manual. El mapa: Epicus Doomicus Metallicus (1986), Nightfall (1987), Ancient Dreams (1988) y Tales of Creation (1989) son la cumbre; Chapter VI (1992) cambia de cantante; Dactylis Glomerata (1998) y From the 13th Sun (1999) son lo más flojo; la vuelta, de Candlemass (2005) a King of the Grey Islands (2007), Death Magic Doom (2009) y Psalms for the Dead (2012), está a buen nivel, y The Door to Doom (2019) y Sweet Evil Sun (2022) recuperan a Johan Längquist, la voz del debut. Entra por Nightfall.", origin: "rec", p: 2, y: 1984, c: 2 },
  { name: "Theatre of Tragedy", genre: "Gothic / Doom Metal (NO)", y: 1993, p: 3, c: 1, female: true, via: "Doom/Gótico", desc: "Pioneros del dueto de voz femenina limpia contra gutural, el molde que luego usan Draconian y Tristania, y después se fueron al electropop industrial con Musique. Entrada: Velvet Darkness They Fear.", origin: "rec", pick: true },
  { name: "Tiamat", genre: "Gothic / Psych Metal (SE)", y: 1987, p: 3, c: 1, via: "Doom/Gótico", desc: "Pasaron del death metal sueco al rock gótico y psicodélico atmosférico, lento y espacial. Wildhoney (1994) es el punto de giro y lo mejor; lo posterior, de A Deeper Kind of Slumber a The Scarred People (2012), es más atmósfera que escritura. Entrada: Wildhoney.", origin: "rec", pick: true },
  { name: "Sleep", genre: "Stoner / Doom Metal", y: 1990, p: 2, via: "Doom/Gótico", desc: "Stoner y doom de riffs gigantes y lentísimos: Sleep's Holy Mountain (1992), Dopesmoker (2003), una sola pieza de 63 minutos que la discográfica rechazó y tardó años en salir, y The Sciences (2018). Al Cisneros y Matt Pike montaron después Om y High on Fire. Entrada: Dopesmoker.", origin: "rec", pick: true },
  { name: "Electric Wizard", genre: "Stoner / Doom Metal (UK)", y: 1993, p: 3, via: "Doom/Gótico", desc: "Dopethrone (2000): la afinación más grave y el sonido más sucio y saturado del doom. No es complejo, es interesante: una identidad sonora que no se confunde con nada. Come My Fanatics... (1997) está a la altura. Entrada: Dopethrone.", origin: "rec", pick: true },
  { name: "Saint Vitus", genre: "Doom Metal", y: 1978, p: 3, via: "Doom/Gótico", desc: "Uno de los dos pilares americanos del doom tradicional de los ochenta, con Wino al frente y una crudeza deliberada. Born Too Late (1986). Entrada: Born Too Late.", origin: "rec", pick: true },
  { name: "Trouble", genre: "Psychedelic Doom Metal", y: 1979, p: 3, via: "Doom/Gótico", desc: "El otro pilar americano del doom de los ochenta, más melódico y psicodélico que Saint Vitus. Psalm 9 (1984) y Manic Frustration (1992). Entrada: Psalm 9.", origin: "rec", pick: true },
  { name: "SubRosa", genre: "Doom Metal / Chamber", y: 2005, p: 2, female: true, via: "Doom/Gótico", desc: "Doom de Salt Lake City con dos violines eléctricos como instrumentos principales, no de adorno: disonantes y chirriantes, tejiendo las melodías sobre riffs lentos, liderado por mujeres. More Constant Than the Gods (2013) y For This We Fought the Battle of Ages (2016). Entrada: More Constant Than the Gods.", origin: "rec", pick: true },
  { name: "Messa", genre: "Doom Metal / Jazz (IT)", y: 2014, p: 2, female: true, via: "Doom/Gótico", desc: "Doom italiano con saxofón, jazz y escalas de Oriente Medio, con la voz de Sara Bianchin encima: de lo más inquieto instrumentalmente del género hoy. Feast for Water (2018), Close (2022) y The Spin (2025). Entrada: Close.", origin: "rec", pick: true },
  { name: "Warning", genre: "Doom Metal (UK)", y: 1994, p: 2, via: "Doom/Gótico", desc: "Doom británico de Patrick Walker: la repetición convertida en duelo, con riffs lentos y la voz al frente. Watching from a Distance (2006) es de los discos más devastadores del género, y Rituals of Shame (junio de 2026), su primer disco en veinte años, está a la altura. Entrada: Watching from a Distance.", origin: "rec", pick: true },
  { name: "40 Watt Sun", genre: "Doom / Slowcore (UK)", y: 2009, p: 3, via: "Doom/Gótico", desc: "El proyecto de Patrick Walker, de Warning, despojando el doom hasta casi lo acústico, con canciones larguísimas, lentas y desnudas. Muy emotivo, pero mínimo por dentro. The Inside Room (2011) y Perfect Light (2016). Entrada: The Inside Room.", origin: "rec", pick: true },
  { name: "Bell Witch", genre: "Funeral Doom Metal", y: 2010, p: 1, c: 3, via: "Doom/Gótico", desc: "[Comodín] Dúo de bajo y batería, sin guitarra: Dylan Desmond toca un bajo de seis cuerdas con tapping que cubre todo el rango, melodía y armonía, y Jesse Shreibman lleva la batería y el órgano. Longing (2012), Four Phantoms, Mirror Reaper (2017), una sola pieza de 84 minutos en memoria de su batería fallecido Adrian Guerra, y Future's Shadow Part 1: The Clandestine Gate (2023). Entrada: Mirror Reaper.", origin: "rec", pick: true },
  { name: "Ahab", genre: "Funeral Doom Metal (DE)", y: 2004, p: 2, via: "Doom/Gótico", desc: "Funeral doom náutico alemán: discos conceptuales completos basados en Moby-Dick, y luego en Poe y Verne, lentos, inmensos y literarios, con voz limpia y gutural. The Call of the Wretched Sea (2006) y The Boats of the Glen Carrig (2015) son la cumbre. Entrada: The Call of the Wretched Sea.", origin: "rec", pick: true },
  { name: "Skepticism", genre: "Funeral Doom Metal (FI)", y: 1991, p: 2, via: "Doom/Gótico", desc: "Funeral doom finlandés con órgano de iglesia como instrumento principal, a velocidad de procesión, que fundó el género. Stormcrowfleet (1995) y Lead and Aether (1998) son la cumbre. Entrada: Stormcrowfleet.", origin: "rec", pick: true },
  { name: "Virgin Black", genre: "Gothic Doom Metal (AU)", y: 1995, p: 2, via: "Doom/Gótico", desc: "Gothic doom australiano con orquesta y coro reales: su trilogía Requiem está compuesta con estructura de misa de réquiem de verdad. Teatral y operístico al extremo. El mapa: Sombre Romantic (2001) y Elegant... and Dying (2003) abren; Requiem – Mezzo Forte (2007), la cumbre, y Requiem – Fortissimo (2008) son las dos partes publicadas de la trilogía. Entrada: Requiem - Mezzo Forte.", origin: "rec", pick: true },
  { name: "Esoteric", genre: "Funeral Doom Metal (UK)", y: 1992, p: 2, via: "Doom/Gótico", desc: "Funeral doom psicodélico británico: piezas de veinte a treinta minutos con capas de guitarra procesada que se deshacen, densas de textura y no solo lentas. Muy parejos: Epistemological Despondency (1994), The Maniacal Vale, Subconscious Dissolution into the Continuum, The Pernicious Enigma, A Pyrrhic Existence (2019). Entrada: The Maniacal Vale.", origin: "rec", pick: true },

  // ----- HIP-HOP / JAZZ MODERNO -----
  { name: "Outkast", genre: "Hip-Hop / Funk", y: 1992, p: 1, c: 1, via: "Hip-hop/Jazz", desc: "Del rap sureño al funk psicodélico con instrumentación en vivo, y cada disco cambia de sistema: ATLiens es espacial y mínimo, Aquemini mete banda tocando, Stankonia acelera hasta rozar el drum and bass, y Speakerboxxx/The Love Below es un doble donde cada mitad es un disco solista distinto. André 3000 abandonó el rap y hoy saca discos de flauta. El mapa: Southernplayalisticadillacmuzik (1994) abre; ATLiens (1996), Aquemini (1998), Stankonia (2000) y Speakerboxxx/The Love Below (2003) son la cumbre; Idlewild (2006), banda sonora, baja, y André 3000 sacó en solitario New Blue Sun (2023), todo de flauta. Entrada: Aquemini.", origin: "rec", pick: true },
  { name: "Flying Lotus", genre: "Experimental Hip-Hop / Jazz", y: 2006, p: 1, c: 1, via: "Hip-hop/Jazz", desc: "Sobrino-nieto de Alice Coltrane. Del beat-tape al jazz fusión con banda real (You're Dead!, con Herbie Hancock): programación de ritmos que se descuadra a propósito, con capas de jazz tocado encima. Fue quien produjo y lanzó a Thundercat. El mapa: 1983 (2006) abre; Los Angeles (2008), Cosmogramma (2010), Until the Quiet Comes (2012) y You're Dead! (2014) son la cumbre, sin bajón; Flamagra (2019) está cerca, y el EP Big Mama (2026) es lo último. Entrada: Cosmogramma.", origin: "rec", pick: true },
  { name: "Madlib", genre: "Hip-Hop / Jazz", y: 1993, p: 2, c: 1, via: "Hip-hop/Jazz", desc: "El productor camaleon absoluto; y como Yesterdays New Quintet se invento un quinteto de jazz falso donde toca el mismo todos los instrumentos y le puso nombre a cada musico ficticio. El mapa: como Quasimoto, The Unseen (2000); como Yesterdays New Quintet, Angles Without Edges (2001); Shades of Blue (2003), sobre el catálogo de Blue Note; Madvillainy (2004), con MF DOOM, es la cumbre; la serie Beat Konducta, Piñata (2014) y Bandana (2019), con Freddie Gibbs, y Sound Ancestors (2021), con Four Tet, siguen arriba. Entrada: Shades of Blue.", origin: "rec", pick: true },
  { name: "Shabaka Hutchings", genre: "Jazz / Experimental (UK)", y: 2011, p: 2, c: 1, via: "Hip-hop/Jazz", desc: "Saxofonista británico: lideró Sons of Kemet, con tuba y dos baterías tocando a la vez sobre ritmos caribeños y de jazz, y The Comet Is Coming, jazz cósmico con sintetizador, y en 2023 dejó el saxo por las flautas para grabar música de cámara meditativa en Perceive Its Beauty, Acknowledge Its Grace. El mapa: con Sons of Kemet, Burn (2013), Lest We Forget What We Came Here to Do (2015), Your Queen Is a Reptile (2018) y Black to the Future (2021), la cumbre; con The Comet Is Coming, de Channel the Spirits (2016) a Hyper-Dimensional Expansion Beam (2022); con los Ancestors, Wisdom of Elders (2016) y We Are Sent Here by History (2020); en solitario, Perceive Its Beauty, Acknowledge Its Grace (2024). Entrada: Your Queen Is a Reptile (Sons of Kemet).", origin: "rec", pick: true },
  { name: "MF DOOM", genre: "Hip-Hop / Rap", y: 1988, p: 1, via: "Hip-hop/Jazz", desc: "Rimas internas densísimas con esquemas que cruzan el final del verso en vez de cerrarlo, sobre producción de collage: diálogos de dibujos animados de los sesenta y bucles de jazz oscuro. Y no es un disco suelto: Operation Doomsday, MM..FOOD y Madvillainy con Madlib sostienen lo mismo, además de lo que sacó como Viktor Vaughn y King Geedorah, cada uno con otra voz y otra producción. Murió en 2020. El mapa: Operation: Doomsday (1999) abre; en 2003-2004 llega la cumbre, con Madvillainy (con Madlib), MM..Food, Vaudeville Villain como Viktor Vaughn y Take Me to Your Leader como King Geedorah; Born Like This (2009), Key to the Kuffs (2012, como JJ DOOM) y Czarface Meets Metal Face (2018) siguen a buen nivel. Entrada: Madvillainy.", origin: "rec", pick: true },
  { name: "The Roots", genre: "Hip-Hop / Jazz Rap", desc: "Hip-hop tocado por una banda en vivo en lugar de programado, y ahí está la diferencia: Questlove toca el groove ligeramente detrás del pulso, dejando que respire en vez de cuadrarlo, y el bajo y los teclados responden a la voz como en un grupo de jazz. Y evolucionaron de verdad: undun es un disco conceptual narrado en orden cronológico inverso que cierra con un cuarteto de cuerdas. El mapa: Organix (1993) y Do You Want More?!!!??! (1995) abren; Illadelph Halflife (1996), Things Fall Apart (1999) y Phrenology (2002) son la cumbre; The Tipping Point (2004) es el más flojo; Game Theory (2006), Rising Down (2008), How I Got Over (2010), undun (2011) y ...And Then You Shoot Your Cousin (2014) vuelven arriba. Entra por Things Fall Apart o undun.", origin: "rec", p: 1, y: 1987, c: 2 },
  { name: "A Tribe Called Quest", genre: "Jazz Rap / Hip-Hop", y: 1985, p: 2, via: "Hip-hop/Jazz", desc: "Pioneros del sampleo de jazz, pero el dato clave: en The Low End Theory metieron a Ron Carter tocando contrabajo de verdad (el bajista de Miles Davis) en un disco de rap de 1991. El mapa: People's Instinctive Travels and the Paths of Rhythm (1990) abre; The Low End Theory (1991) y Midnight Marauders (1993) son la cumbre; Beats, Rhymes and Life (1996) y The Love Movement (1998) bajan, y We Got It from Here... Thank You 4 Your Service (2016), grabado antes de morir Phife Dawg, vuelve arriba. Entrada: The Low End Theory.", origin: "rec", pick: true },
  { name: "Kamasi Washington", genre: "Jazz / Spiritual Jazz", desc: "Jazz espiritual modal con coro y cuerdas encima, tempos que respiran y solos largos sobre una armonía bastante estable. Es majestuoso y emocionante, pero armónicamente más sencillo que Coltrane o Mingus. The Epic (2015), Heaven and Earth (2018) y Fearless Movement (2024). Entrada: The Epic.", origin: "rec", p: 2, y: 2004, c: 2 },
  { name: "BADBADNOTGOOD", genre: "Jazz / Hip-Hop", y: 2010, p: 2, via: "Hip-hop/Jazz", desc: "Trio de jazz salido del mundo del hip-hop; Talk Memory tiene arreglos orquestales del brasileno Arthur Verocai. Han grabado con Ghostface Killah y Tyler. El mapa: BBNG (2011) y BBNG2 (2012) son versiones de hip-hop; III (2014), Sour Soul (2015, con Ghostface Killah) y IV (2016) son la cumbre, y Talk Memory (2021) va más al jazz orquestal. Entrada: IV, luego Talk Memory.", origin: "rec", pick: true },
  { name: "Makaya McCraven", genre: "Jazz / Experimental", y: 2012, p: 2, via: "Hip-hop/Jazz", desc: "Baterista y productor: graba sesiones de improvisación de jazz en vivo y luego las corta y reensambla como si fueran beats, así que es composición por edición con la batería al mando. In the Moment (2015), Universal Beings (2018) e In These Times (2022). Entrada: Universal Beings.", origin: "rec", pick: true },
  { name: "J Dilla", genre: "Hip-Hop / Instrumental", desc: "[Comodín] Programaba la batería deliberadamente desalineada, sin cuantizar, dejando el bombo y la caja caídos unos milisegundos fuera de la rejilla, de modo que el groove cojea y respira como si lo tocara una persona cansada. Eso cambió cómo se toca el instrumento: hoy los bateristas estudian el Dilla time como técnica y una generación entera de soul y hip-hop se construyó sobre esa idea. Donuts son 31 piezas de loops que armó en una cama de hospital con un sampler portátil, y salió tres días antes de que muriera. El mapa: con Slum Village, Fan-Tas-Tic Vol. 2 (2000); en solitario, Welcome 2 Detroit (2001), Champion Sound (2003, con Madlib como Jaylib) y Donuts (2006), la cumbre; The Shining (2006) salió póstumo. Entra por Donuts.", origin: "rec", p: 1, y: 1995, c: 3 },
  { name: "Irreversible Entanglements", genre: "Free Jazz / Experimental", y: 2015, p: 2, female: true, via: "Hip-hop/Jazz", desc: "Free jazz improvisado con la poesía hablada de Moor Mother encima: político e incendiario, con saxo y trompeta en contrapunto libre sobre contrabajo y batería. Who Sent You? (2020) y Protect Your Light (2023). Entrada: Who Sent You?", origin: "rec", pick: true },
  { name: "Standing on the Corner", genre: "Experimental / Jazz", y: 2016, p: 3, via: "Hip-hop/Jazz", desc: "Colectivo experimental de Nueva York: collage de jazz, soul, ruido, gospel y grabaciones de campo, sin formato de canción. Entrada: Red Burns.", origin: "rec", pick: true },
  { name: "Ezra Collective", genre: "Jazz / Afrobeat (UK)", y: 2012, p: 2, via: "Hip-hop/Jazz", desc: "Jazz londinense con afrobeat, reggae y calipso, liderado por el baterista Femi Koleoso, con su hermano TJ al bajo; ganaron el Mercury Prize de 2023 con Where I'm Meant to Be. Here Because of Hope (11 de septiembre de 2026), en tres movimientos que siguen la música negra de África al Caribe y a Londres, entró número uno en Reino Unido. Entrada: Where I'm Meant to Be.", origin: "rec", pick: true },

  // ----- THRASH TÉCNICO / DEATH CLÁSICO -----
  { name: "Napalm Death", genre: "Grindcore / Industrial", desc: "Grindcore, o sea velocidad y brevedad extremas sobre riffs deliberadamente simples, sin desarrollo. Lo que sí vale es que no se quedaron quietos en cuarenta años: metieron industrial, pasajes de ruido y disonancia real a partir de Fear Emptiness Despair, y el blast beat que inventó Mick Harris cuenta porque cambia cómo suena todo lo que vino después. Sacaron disco a medias con los Melvins, Savage Imperial Death March, en abril de 2026. El mapa: Scum (1987) y From Enslavement to Obliteration (1988) fundan el grindcore; Harmony Corruption (1990) y Utopia Banished (1992) giran al death; Fear, Emptiness, Despair (1994), Diatribes e Inside the Torn Apart meten groove e industrial; desde Enemy of the Music Business (2000) vuelven a la velocidad, y Smear Campaign (2006), Utilitarian (2012), Apex Predator – Easy Meat (2015) y Throes of Joy in the Jaws of Defeatism (2020) son de lo más variado que han hecho. Entrada: Utopia Banished.", origin: "rec", p: 2, y: 1981, c: 1 },
  { name: "Kreator", genre: "Thrash Metal (DE)", desc: "Thrash rápido con melodías de guitarra épicas encima del riff y voz rasposa de Mille Petrozza, muy bien ejecutado y bastante directo de estructura. De Pleasure to Kill (1986) a Coma of Souls (1990) está lo mejor; los discos experimentales de los noventa bajan, vuelven bien de Violent Revolution (2001) a Phantom Antichrist (2012), y Hate Über Alles (2022) y Krushers of the World (enero de 2026) quedan por debajo. Entrada: Coma of Souls.", origin: "rec", p: 2, y: 1982, c: 1 },
  { name: "Hypocrisy", genre: "Melodic Death Metal (SE)", y: 1990, p: 2, c: 1, via: "Thrash/Death", desc: "Peter Tägtgren llevó la banda del death brutal a un death melódico atmosférico, casi espacial, con temática de abducciones, y en paralelo montó Pain, puro metal industrial. Muy parejos de Abducted (1996) a Virus (2005) y Worship (2021); solo Catch 22 (2002) baja. Entrada: Abducted.", origin: "rec", pick: true },
  { name: "Dark Angel", genre: "Technical Thrash Metal", desc: "Aquí la batería ES la escritura: Gene Hoglan compone las partes como si fueran riffs, con patrones que cambian de figura bajo el mismo riff de guitarra y subdivisiones que desplazan el acento, y por eso los temas duran ocho minutos sin repetirse. Darkness Descends (1986) y Leave Scars (1989) son la cumbre y Time Does Not Heal (1991) está cerca; We Have Arrived (1985) es más básico. Volvieron en septiembre de 2025 con Extinction Level Event, su primer disco desde 1991, dedicado a Jim Durkin, muerto en 2023, y está claramente por debajo. Entrada: Darkness Descends.", origin: "rec", p: 1, y: 1981, c: 2 },
  { name: "Obituary", genre: "Death Metal", desc: "Death metal de Florida a medio tiempo, muy afinado hacia abajo, con riffs sencillos que se quedan en el bolsillo del ritmo y la voz agónica de John Tardy. Una sola cosa, hecha muy bien, más centrada en el ambiente que en la ejecución. Slowly We Rot (1989) y Cause of Death (1990) son la cumbre. Entrada: Cause of Death.", origin: "rec", p: 3, y: 1984, c: 2 },
  { name: "Suffocation", genre: "Brutal Technical Death", desc: "El brutal death que sí está construido: Terrance Hobbs escribe riffs que se desarrollan y se recolocan en lugar de amontonarse, con cambios de tempo dentro del tema y secciones que vuelven transformadas, y la batería sostiene esa arquitectura en lugar de solo golpear. Effigy of the Forgotten (1991), Breeding the Spawn y Pierced from Within (1995) son la cumbre, y de Souls to Deny (2004) a Blood Oath y ...Of the Dark Light (2017) mantienen el nivel; Pinnacle of Bedlam y Hymns from the Apocrypha (2023) bajan algo. Entrada: Effigy of the Forgotten o Pierced from Within.", origin: "rec", p: 1, y: 1988, c: 2 },
  { name: "Cryptopsy", genre: "Technical Death Metal (CA)", desc: "Death técnico canadiense donde la batería de Flo Mounier es el eje: alterna blast beats con figuras sincopadas que cambian bajo el mismo riff y varía la subdivisión dentro del compás, con riffs disonantes que no repiten. Blasphemy Made Flesh (1994), None So Vile (1996), con la voz de Lord Worm, y Whisper Supremacy (1998) son la cumbre; And Then You'll Beg (2000) y sobre todo The Unspoken King (2008), con giro al deathcore, son el bajón, y de As Gomorrah Burns (2023) a An Insatiable Violence (2025) recuperan el nivel. Entrada: None So Vile.", origin: "rec", p: 2, y: 1988, c: 2 },
  { name: "Cryptic Shift", genre: "Technical Death / Thrash (UK)", y: 2015, p: 2, via: "Thrash/Death", desc: "Death técnico y thrash con fusión de jazz, de guitarras a lo Allan Holdsworth y estructuras desmesuradas. Visitations from Enceladus (2020) y Overspace & Supertime (2026), cinco temas en ochenta y dos minutos, uno de más de media hora, recibido como uno de los discos de death del año. Entrada: Overspace & Supertime.", origin: "rec", pick: true },
  { name: "Destruction", genre: "Technical Thrash Metal (DE)", y: 1982, p: 2, via: "Thrash/Death", desc: "El más técnico del trío alemán: Schmier canta y toca el bajo a la vez, con líneas que se van por su cuenta en vez de seguir la guitarra. De Infernal Overkill (1985) a Release from Agony (1987) está lo mejor, y la vuelta con All Hell Breaks Loose (2000) y The Antichrist (2001) también. Birth of Malice salió en marzo de 2025. Entrada: Eternal Devastation.", origin: "rec", pick: true },
  { name: "Sodom", genre: "Thrash Metal (DE)", y: 1981, p: 2, via: "Thrash/Death", desc: "El más crudo, directo y punk del trío alemán, y muy parejo: de Persecution Mania (1987) y Agent Orange (1989) a Genesis XIX (2020). Sacaron The Arsonist en junio de 2025 y entraron en hiato indefinido justo después. Entrada: Agent Orange.", origin: "rec", pick: true },
  { name: "Overkill", genre: "Thrash Metal", y: 1980, p: 2, via: "Thrash/Death", desc: "Más de cuarenta años con altibajos claros: de Feel the Fire (1985) a Horrorscope (1991) a gran nivel, un bajón en los noventa y los dos mil, y otro pico de Ironbound (2010) a Scorched (2023). D.D. Verni lleva el bajo tan al frente que muchas veces él es el riff principal, y Bobby Blitz sigue cantando agudísimo. Entrada: Horrorscope.", origin: "rec", pick: true },
  { name: "Toxik", genre: "Technical Thrash Metal", y: 1985, p: 2, via: "Thrash/Death", desc: "Thrash técnico casi imposible: Josh Christian tocaba en 1987 cosas que no tenían sentido para la época, con arreglos que rozan el prog. World Circus (1987) y Think This (1989) son la cumbre; volvieron con Dis Morta (2022), algo por debajo. Entrada: Think This.", origin: "rec", pick: true },
  { name: "Forbidden", genre: "Technical Thrash Metal", y: 1985, p: 2, via: "Thrash/Death", desc: "Twisted into Form (1990): thrash con armonías vocales reales, arreglos que respiran y Paul Bostaph, luego en Slayer, en una batería muy por encima de la media del género. Forbidden Evil (1988) está cerca; los noventa bajan, y Omega Wave (2010) vuelve bien. El 23 de octubre sale Forbidden, su primer disco en dieciséis años. Entrada: Twisted into Form.", origin: "rec", pick: true },
  { name: "Bloodbath", genre: "Death Metal (SE)", y: 1998, p: 2, via: "Thrash/Death", desc: "Supergrupo sueco fundado por miembros de Katatonia, con Mikael Åkerfeldt a la voz al inicio y Nick Holmes, de Paradise Lost, desde 2014: death de la vieja escuela hecho por gente que normalmente compone prog. Nightmares Made Flesh (2004) es la cumbre. Entrada: Nightmares Made Flesh.", origin: "rec", pick: true },
  { name: "Martyr", genre: "Technical Death Metal (CA)", y: 1994, p: 1, via: "Thrash/Death", desc: "Death técnico de Quebec con Daniel Mongrain a la guitarra, luego guitarrista de Voivod, y su hermano François al bajo: armonía rarísima, riffs de raíz jazzística y compases cambiantes en la línea de Cynic y Atheist. Tres discos y los tres sobresalientes: Hopeless Hopes (1997), Warp Zone (2000) y Feeding the Abscess (2006). Entrada: Warp Zone.", origin: "rec", pick: true },
  { name: "Believer", genre: "Technical Thrash Metal", desc: "[Comodín] No es thrash con un violín de adorno al final: en Sanity Obscure (1990) hay una pieza con soprano clásica y cuarteto de cuerda encima del riff, y Dimensions (1993) abre con una suite de cámara de varios movimientos antes de que entre la banda, todo escrito para que las cuerdas lleven contrapunto contra la guitarra en vez de doblarla. El riff de fondo ya es técnico y de compás cambiante por su cuenta. Nadie más hizo esto en el thrash. Pero son esos dos discos: el debut, Extraction from Mortality (1989), es thrash más corriente, y la vuelta con Gabriel (2009) y Transhuman (2011) baja. Entrada: Sanity Obscure.", origin: "rec", p: 2, y: 1986, c: 3 },
  { name: "Spiral Architect", genre: "Progressive Death Metal (NO)", desc: "Un solo disco, A Sceptic's Universe (2000): compases que cambian sin parar, estructuras que no se repiten y polirritmias con contrapunto real, con Asgeir Mickelson guiando los cambios a la batería y Lars Norberg tocando líneas de bajo independientes, en la línea de Watchtower cruzado con Psychotic Waltz. La voz de Øyvind Hægeland es un gusto adquirido. Entrada: A Sceptic's Universe.", origin: "rec", p: 2, y: 1993, c: 2 },
  { name: "Incantation", genre: "Death Metal", y: 1989, p: 2, via: "Thrash/Death", desc: "Death cavernoso que alterna blast beats con doom arrastrado dentro de la misma canción, con riffs que suenan grabados dentro de una cueva. Onward to Golgotha (1992), Mortal Throne of Nazarene y Diabolical Conquest (1998) son la cumbre; lo posterior es desigual, con buenos momentos en Vanquish in Vengeance (2012) y Unholy Deification (2023). Entrada: Onward to Golgotha.", origin: "rec", pick: true },
  { name: "Terrorizer", genre: "Grindcore / Death Metal", y: 1986, p: 3, via: "Thrash/Death", desc: "World Downfall (1989): un solo disco esencial de grindcore, grabado con Pete Sandoval, luego en Morbid Angel, definiendo lo que significaba rápido en 1989. Los discos de la vuelta quedan muy por debajo. Entrada: World Downfall.", origin: "rec", pick: true },
  { name: "Deicide", genre: "Death Metal", y: 1987, p: 4, via: "Thrash/Death", desc: "Pionero indiscutible, pero formulaico y construido sobre el shock mas que sobre la musica; no evoluciona entre discos. Su unico gancho real es Steve Asheim en la bateria. Entrada: Legion.", origin: "rec", pick: true },

  // ----- GUITARRA INSTRUMENTAL -----
  { name: "Dixie Dregs", genre: "Prog Rock / Fusion", y: 1970, p: 1, c: 1, via: "Guitarra instrumental", desc: "Instrumental entero, sin una sola voz, mezclando bluegrass, prog, fusión y música clásica dentro del mismo tema, con violín y guitarra turnándose la melodía y la batería de Rod Morgenstein cambiando de estilo por debajo. Free Fall (1977), What If (1978), Night of the Living Dregs y Dregs of the Earth (1980) son la cumbre; Unsung Heroes e Industry Standard (1982), con algo más de canción, bajan un poco. Entrada: What If.", origin: "rec", pick: true },
  { name: "Shawn Lane", genre: "Jazz Fusion / Instrumental", y: 1985, p: 2, c: 1, via: "Guitarra instrumental", desc: "Una velocidad a la guitarra casi sin comparación, pero eso es lo de menos: lo que importa son los ritmos búlgaros e indios y la microtonalidad, sobre todo en el trío con el bajista Jonas Hellborg y el batería Jeff Sipe, que suena mejor que su obra en solitario. Murió en 2003, a los 40. Entrada: Temporal Analogues of Paradise (1996, con Hellborg y Sipe).", origin: "rec", pick: true },
  { name: "Freak Kitchen", genre: "Prog Metal (SE)", y: 1992, p: 2, c: 1, via: "Guitarra instrumental", desc: "Metal progresivo sueco con humor negro: Mattias IA Eklundh escribe riffs en compases impares con cuartos de tono y fraseo derivado del konnakol indio, así que la guitarra suena rítmica y descolocada a la vez. Técnica extrema al servicio de canciones raras, no del lucimiento. El mapa: Appetizer (1994) y Spanking Hour (1996) abren; de Dead Soul Men (2000) a Move (2002), Organic (2005) y Land of the Freaks (2009) está la cumbre, y Cooking with Pagans (2014), Confusion to the Enemy (2018) y Everyone Gets Bloody (2024) se mantienen. Entrada: Land of the Freaks.", origin: "rec", pick: true },
  { name: "Allan Holdsworth", genre: "Jazz Fusion / Instrumental", y: 1969, p: 1, via: "Guitarra instrumental", desc: "Construye los solos con escalas simétricas y acordes de más de cuatro notas que no pertenecen a la tonalidad de la base, y el legato es tan continuo que no se oye el ataque de cada nota: suena más a viento que a guitarra. Lo sostiene de I.O.U. (1982) a Metal Fatigue, Atavachron, Sand, Secrets, Hard Hat Area y The Sixteen Men of Tain (2000), y también en su etapa con Soft Machine y Bruford. Quedan fuera Velvet Darkness (1977), que él mismo repudió, y Flat Tire (2001), más flojo. Entrada: Metal Fatigue.", origin: "rec", pick: true },
  { name: "Jason Becker", genre: "Neoclassical / Instrumental", desc: "Dos etapas muy distintas. Perpetual Burn (1988) es shred neoclásico, arpegios barridos a velocidad extrema sobre armonía menor armónica, virtuosismo como fin. Lo posterior, compuesto nota a nota con la mirada tras perder el movimiento por la ELA, es otra cosa: piezas orquestales con arreglo de cuerda y desarrollo temático real, y ahí hay composición de verdad. Entra por Triumphant Hearts (2018) antes que por Perpetual Burn.", origin: "rec", p: 2, y: 1986, c: 2 },
  { name: "Guthrie Govan", genre: "Jazz Fusion / Instrumental", y: 2006, p: 2, via: "Guitarra instrumental", desc: "El guitarrista de The Aristocrats en solitario: Erotic Cakes (2006), su único disco propio, es una clase magistral de fusión con sentido del humor, del jazz-rock al funk y el metal. Entrada: Erotic Cakes.", origin: "rec", pick: true },
  { name: "Panzerballett", genre: "Jazz Metal (DE)", y: 2004, p: 2, via: "Guitarra instrumental", desc: "Jazz metal alemán de Jan Zehrfeld: riffs de djent y metal en compases imposibles, saxo, guitarra y batería en unísonos rapidísimos y armonía de jazz, con temas ajenos, de ABBA a estándares de jazz o Meshuggah, reescritos hasta volverse otra cosa. Muy parejos: Starke Stücke (2008), Tank Goodness (2012), Breaking Brain, Planet Z (2020) y Übercode Œuvre (2025), con varios baterías invitados, de Virgil Donati a Marco Minnemann y Anika Nilles. Entrada: Tank Goodness.", origin: "rec", pick: true },
  { name: "Tribal Tech", genre: "Jazz Fusion", y: 1984, p: 2, via: "Guitarra instrumental", desc: "Scott Henderson toca la guitarra desde el blues pero sale de la tonalidad a cada frase, Gary Willis lleva el bajo fretless como segunda voz y Kirk Covington la batería con fraseo de jazz y peso de rock. Muy parejos durante toda su obra, de Dr. Hee (1987) a Illicit (1992), Reality Check (1995), Thick (1999), improvisado casi entero en el estudio, y X (2012). Entrada: Illicit.", origin: "rec", pick: true },
  { name: "Béla Fleck and the Flecktones", genre: "Jazz Fusion / Bluegrass", desc: "Béla Fleck toca líneas de bebop en un banjo de cinco cuerdas, un instrumento que no está pensado para esa armonía, y Victor Wooten al bajo usa doble pulgar y slap melódico para llevar contramelodías en vez de acompañar. Es virtuosismo enorme sobre estructuras de fusión bastante convencionales y con groove accesible, y ahí está el techo comparado con Mahavishnu o Weather Report. Los dos primeros discos (1990-1991) y Outbound (2000) son lo mejor. Entrada: Flight of the Cosmic Hippo.", origin: "rec", p: 2, y: 1988, c: 2 },
  { name: "Blotted Science", genre: "Technical Death / Instrumental", desc: "[Comodín] Metal instrumental sin una sola voz, con riffs atonales y angulares que no resuelven nunca donde esperas, cambios de compás continuos y el bajo de Alex Webster haciendo líneas propias en vez de doblar la guitarra. Es denso y agotador de seguir, en el buen sentido. Lo compuso Ron Jarzombek, de Watchtower, con un sistema de doce tonos propio. The Machinations of Dementia (2007) y el EP The Animation of Entomology (2011). Entrada: The Machinations of Dementia.", origin: "rec", p: 2, y: 2007, c: 3 },
  { name: "Michael Manring", genre: "Jazz Fusion / Instrumental", y: 1986, p: 2, c: 3, via: "Guitarra instrumental", desc: "[Comodín] Cambia la afinación de las cuerdas mientras toca, así que la armonía se mueve por debajo de una nota que sigue sonando: un solo bajo haciendo melodía, bajo y armonía a la vez, sin overdubs. El mapa: Unusual Weather (1986), Toward the Center of the Night (1989) y Drastic Measures (1991) abren; Thonk (1994) y Soliloquy (2005), a bajo solo, son la cumbre. Entrada: Soliloquy.", origin: "rec", pick: true },
  { name: "Stick Men", genre: "Prog Rock / Instrumental", y: 2007, p: 2, via: "Guitarra instrumental", desc: "Tony Levin al Chapman Stick, Pat Mastelotto a la batería y Markus Reuter a la touch guitar, todos de la órbita de King Crimson: instrumentos de tapping que cubren bajo y armonía a la vez, así que el trío suena como un sexteto, en temas instrumentales de métrica cambiante. El mapa: Soup (2010), Open (2012), Deep (2013), la cumbre, y Prog Noir (2016). Entrada: Deep.", origin: "rec", pick: true },
  // ----- AÑADIDOS POR PETICIÓN DE KEN -----
  { name: "Spawn of Possession", genre: "Technical Death Metal (SE)", y: 1997, p: 1, via: "Thrash/Death", desc: "Death técnico sueco de riffs laberínticos y tono neoclásico que se pliegan sobre sí mismos, sin caer en la velocidad por la velocidad. Tres discos y los tres sobresalientes: Cabinet (2003), Noctambulant (2006) e Incurso (2012), su obra maestra; cuatro de sus miembros siguieron en 2024 como Retromorphosis. Entrada: Incurso.", origin: "rec", pick: true },
  { name: "Retromorphosis", genre: "Technical Death Metal (SE)", y: 2024, p: 2, via: "Thrash/Death", desc: "La continuación real de Spawn of Possession: cuatro de los cinco miembros de su formación final se reagruparon en 2024 bajo este nombre, y Psalmus Mortis (2025) retoma justo donde quedó Incurso. Entrada: Psalmus Mortis.", origin: "rec", pick: true },
  { name: "Dying Fetus", genre: "Brutal Technical Death", y: 1991, p: 2, via: "Thrash/Death", desc: "John Gallagher compone toda la música y su estilo de riff es de los más reconocibles y técnicos del death brutal: figuras de groove con desplazamientos que cambian de subdivisión dentro del compás, con el bajo siguiéndolas nota a nota y una batería muy técnica. La fórmula es estable, pero el nivel sube con los años: Destroy the Opposition (2000) y Stop at Nothing son la base, y Reign Supreme (2012), Wrong One to Fuck With (2017) y Make Them Beg for Death (2023) son la cumbre. Entrada: Reign Supreme.", origin: "rec", pick: true },
  { name: "Consider the Source", genre: "Prog Fusion / Instrumental", y: 2004, p: 2, via: "Guitarra instrumental", desc: "Trío instrumental de Nueva York: guitarra de doble mástil sin trastes tocando escalas árabes y turcas con cuartos de tono sobre estructuras de prog y fusión, con bajo y batería en compases impares. World War Trio, publicado en tres partes, es su obra más ambiciosa. El mapa: Esperanto (2007) y That's What's Up (2010) abren; World War Trio (2015), en tres partes, es la cumbre, y You Are Literally a Mountain (2019), Hybrid Vol. 1 (2021) y The Stare (2024) siguen esa línea. Entrada: World War Trio.", origin: "rec", pick: true }
];

// ===========================================================================
// === INSTRUMENTISTAS Y COMPOSITORAS (ago 2026) =============================
// Eje distinto al de "voz femenina": aquí la mujer ES la sustancia
// instrumental o compositiva. Todas justificadas por el instrumento, la
// técnica o el sistema de composición, nunca por quién es.
// ===========================================================================
const INSTRUMENTISTAS = [
  { name: "Hiromi", genre: "Jazz Fusion (JP)", y: 1999, p: 1, via: "Mujeres instrumentistas", desc: "Pianista y compositora que cruza stride, post-bop, rock progresivo, clásica y fusión dentro de una misma pieza, con técnica descomunal. En el Trio Project, con Anthony Jackson al bajo de seis cuerdas y Simon Phillips a la batería, los tres instrumentos son protagonistas, y con Sonicwonder cambió a un cuarteto con trompeta y electrónica: Sonicwonderland (2023) y Out There (2025). Muy pareja disco a disco. Entrada: Move, o Alive.", origin: "rec", pick: true, female: true },
  { name: "Jlin", genre: "Electronic / Experimental", y: 2011, p: 2, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Salió del footwork de Chicago y lo convirtió en composición: polirritmias de percusión programada que se superponen y se desplazan, con la complejidad rítmica como materia prima. Perspective, escrita para el ensamble Third Coast Percussion, fue finalista del Pulitzer de música en 2023; Black Origami (2017) y Akoma (2024), con Björk y Philip Glass, son sus discos. Es electrónica pura, sin instrumento tocado. Entrada: Black Origami, luego Akoma.", origin: "rec", pick: true, female: true },
  { name: "Mary Halvorson", genre: "Avant-garde Jazz / Guitar", y: 2002, p: 2, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Guitarrista de jazz de sonido propio: púa percusiva, saltos de cuerda y un pedal de delay manipulado como pitch-shifter, así que las notas se doblan y se tuercen a mitad, con escritura para sexteto y octeto llena de contrapunto. Amaryllis y Belladonna (2022) y Cloudward (2024). Entrada: Amaryllis.", origin: "rec", pick: true, female: true },
  { name: "Sarah Longfield", genre: "Prog / Instrumental", y: 2013, p: 2, via: "Mujeres instrumentistas", desc: "Guitarrista de ocho cuerdas con enfoque pianístico: tapping a dos manos que usa el mástil como un teclado, con línea de bajo y melodía a la vez sobre base djent. Disparity (2018) es donde mejor se oye. El mapa: Collapse//Cascade (2014) abre y Disparity (2018) es la cumbre. Entrada: Disparity.", origin: "rec", pick: true, female: true },
  { name: "Anika Nilles", genre: "Jazz Fusion / Prog", y: 2013, p: 2, via: "Mujeres instrumentistas", desc: "Baterista y compositora alemana; su banda Nevell hace fusión de jazz, funk y prog escrita por ella, construida sobre polirritmias (3 contra 4, 4 contra 3) usadas como material compositivo y no como adorno. Tres discos: Pikalar (2017), For a Colorful Soul (2020) y False Truth (2025). Tocó con Jeff Beck y es la baterista de la gira de regreso de Rush en 2026. Entrada: For a Colorful Soul.", origin: "rec", pick: true, female: true },
  { name: "Anna Meredith", genre: "Electronic / Art Pop (UK)", desc: "Compositora escocesa de formación clásica, que escribió para la BBC Symphony, y se pasó a la electrónica sin dejar de componer como compositora: la métrica se reinventa casi en cada sección, con clarinete, tuba, chelo y sintetizadores entrando y saliendo como voces de una partitura y no como capas de producción. Son dos discos, Varmints (2016), que ganó el Scottish Album of the Year, y FIBS (2019), nominado al Mercury. Entra por FIBS.", origin: "rec", p: 2, y: 2012, c: 1 },
  { name: "Lucrecia Dalt", genre: "Experimental / Electronic (CO)", y: 2005, p: 2, c: 1, via: "Mujeres instrumentistas", desc: "Colombiana, de las artistas experimentales más respetadas del momento: electrónica, bolero y percusión trabajados como textura y ritmo, con la voz casi hablada. ¡Ay! (2022) fue disco del año para The Wire, y A Danger to Ourselves (2025) lo construyó con el percusionista Alex Lázaro sobre la interacción de líneas de bajo, ritmos y textura. Entrada: ¡Ay!", origin: "rec", pick: true, female: true },
  { name: "Wendy Carlos", genre: "Synth / Electronic", y: 1968, p: 1, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Buscando sistemáticamente picos de consonancia fuera del temperamento occidental dio con tres escalas que NO se repiten a la octava, alfa, beta y gamma; las usó en Beauty in the Beast (1986) y suenan genuinamente ajenas, porque la referencia armónica que el oído espera no existe. Antes de eso, Switched-On Bach: mil cien horas grabando cada voz por separado en un Moog monofónico y montándolas a mano, dando expresión línea a línea en vez de teclear acordes. Compuso para La Naranja Mecánica, El Resplandor y Tron. El mapa: Switched-On Bach (1968) y The Well-Tempered Synthesizer (1969) abren; Sonic Seasonings (1972), casi ambient, y la banda sonora de La Naranja Mecánica (1972) siguen; Switched-On Bach II (1973) y Switched-On Brandenburgs (1979) cierran la etapa Bach; Digital Moonscapes (1984) y Beauty in the Beast (1986), con las escalas alfa, beta y gamma, son lo más propio; Secrets of Synthesis (1987), Switched-On Bach 2000 (1992) y Tales of Heaven and Hell (1998) cierran. Entrada: Switched-On Bach, luego Beauty in the Beast.", origin: "rec", pick: true, female: true },
  { name: "Delia Derbyshire", genre: "Experimental / Electronic", y: 1962, p: 3, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Creó el tema de Doctor Who en 1963 cortando y empalmando cinta a mano, midiendo longitudes físicas, antes de que existieran los sintetizadores comerciales: electrónica de osciladores y montaje, con melodías y ritmos que suenan mucho más modernos que su fecha. Su obra es fragmentaria, sobre todo música para la BBC; el único disco propiamente dicho es An Electric Storm (1969), de White Noise. Entrada: An Electric Storm.", origin: "rec", pick: true, female: true },
  { name: "Kylesa", genre: "Sludge / Psych Metal", y: 2001, p: 2, via: "Mujeres instrumentistas", desc: "Sludge de Savannah con dos baterías a la vez, abiertas a izquierda y derecha en la mezcla, y Laura Pleasants a la guitarra y la voz junto a Phillip Cope. Static Tensions (2009) y Spiral Shadow (2010) son la cumbre; tras un parón desde 2016 volvieron a los escenarios en 2025. Entrada: Spiral Shadow.", origin: "rec", pick: true, female: true },
  { name: "Zeena Parkins", genre: "Avant-garde / Experimental", y: 1984, p: 2, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Toca el arpa fuera de todo lo que se supone que hace: estira las cuerdas más allá de su rango para doblar la afinación, las prepara con objetos y las enruta por procesamiento analógico y digital, pasando de texturas delicadas a retroalimentación distorsionada dentro de una misma pieza. Improvisación libre, no repertorio. Ha trabajado con Björk y Anthony Braxton. El mapa: con Skeleton Crew, The Country of Blinds (1986); en solitario, Nightmare Alley (1993), Isabelle (1995) y Pan-Acousticon (1999); y con Björk, el arpa de Vespertine (2001). Entrada: The Adorables.", origin: "rec", pick: true, female: true },
  { name: "Kali Malone", genre: "Clásica moderna / Órgano (US)", y: 2014, p: 2, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Compone para órgano de tubos con sistemas de afinación históricos y entonación justa, reinterpretando métodos de polifonía de hace siglos: acordes que cambian muy despacio y batimientos entre voces que se oyen como ritmo. The Sacrificial Code (2019) y Does Spring Hide Its Joy (2023), este con Stephen O'Malley a la guitarra y Lucy Railton al chelo. Entrada: The Sacrificial Code.", origin: "rec", pick: true, female: true },
  { name: "Ikue Mori", genre: "Experimental / Electronic", y: 1977, p: 2, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Montó DNA, banda clave del no-wave, con una batería completamente propia: kit mínimo, todo el peso en los toms, patrones entrecortados pero propulsivos. Luego improvisó con cajas de ritmos y encontró cómo hacerlas sonar rotas quitándoles la cuantización, y hacia 2000 pasó al portátil. Lleva décadas colaborando con John Zorn. El mapa: con DNA, de No New York (1978) a los EP de 1981; en solitario, casi todo en Tzadik, de Hex Kitchen (1995) y Garden (1996) a One Hundred Aspects of the Moon (2000).", origin: "rec", pick: true, female: true },
  { name: "Terri Lyne Carrington", genre: "Jazz / Fusion", y: 1989, p: 2, via: "Mujeres instrumentistas", desc: "Baterista, compositora y productora, no solo intérprete: cuatro Grammys, NEA Jazz Master, y fundó el Berklee Institute of Jazz and Gender Justice. The Mosaic Project (2011), Money Jungle: Provocative in Blue (2013) y Waiting Game (2019) son lo mejor; We Insist 2025!, con Christie Dashiell, reimagina la Freedom Now Suite de Max Roach y estuvo nominado al Grammy de 2026. Entrada: The Mosaic Project.", origin: "rec", pick: true, female: true },
  { name: "Divide and Dissolve", genre: "Doom Metal / Instrumental (AU)", y: 2015, p: 2, c: 3, via: "Mujeres instrumentistas", desc: "[Comodín] Takiaya Reed toca saxofón y guitarra y Sylvie Nehill la batería: doom instrumental con el saxo como instrumento pesado, no como adorno jazzístico. Gas Lit (2021) e Insatiable (2023). Entrada: Gas Lit.", origin: "rec", pick: true, female: true },
  { name: "Hildur Guðnadóttir", genre: "Clásica moderna / Chelo (IS)", y: 2006, p: 2, via: "Mujeres instrumentistas", desc: "Chelista de formación clásica cuya obra se construye desde el chelo: capas de chelo procesado, drones y voz en piezas lentas de mucha densidad armónica. Antes de las bandas sonoras tocó y grabó con Sunn O))), Throbbing Gristle, Pan Sonic y Múm, así que viene del drone y lo industrial. Without Sinking (2009), Saman y las bandas sonoras de Chernobyl y Joker (2019). Entrada: Without Sinking.", origin: "rec", pick: true, female: true },
  { name: "Esperanza Spalding", genre: "Jazz / Fusión (US)", y: 2006, p: 2, via: "Mujeres instrumentistas", desc: "Bajista, compositora y vocalista: canta mientras toca líneas de contrabajo y bajo eléctrico que van por su cuenta. Emily's D+Evolution (2016) es un disco conceptual de prog angular con guitarra eléctrica, fusión rítmicamente densa y cambios de acorde poco ortodoxos, lo más complejo de su obra. El mapa: Esperanza (2008) y Chamber Music Society (2010) abren; Radio Music Society (2012) está cerca; Emily's D+Evolution (2016) y 12 Little Spells (2018) son la cumbre, y Songwrights Apothecary Lab (2021) y Milton + esperanza (2024) siguen. Entrada: Emily's D+Evolution.", origin: "rec", pick: true, female: true },
  { name: "Kaki King", genre: "Instrumental / Math Rock", y: 2003, p: 2, via: "Mujeres instrumentistas", desc: "Guitarrista que viene de la batería y usa la guitarra como instrumento rítmico: la toca plana sobre el regazo, con tapping a dos manos y golpes percusivos sobre la caja, así que melodía, bajo y percusión salen a la vez del mismo instrumento. Legs to Make Us Longer (2004) es donde esa escritura sale más clara; después se abre a banda, lap steel y piezas audiovisuales. El mapa: Everybody Loves You (2003) y Legs to Make Us Longer (2004) son la guitarra sola; ...Until We Felt Red (2006), Dreaming of Revenge (2008) y Junior (2010) meten banda y voz; Glow (2012) vuelve al instrumental y es de lo mejor, y The Neck Is a Bridge to the Body (2015) es su pieza audiovisual. Entrada: Legs to Make Us Longer.", origin: "rec", pick: true, female: true },
  { name: "Meshell Ndegeocello", genre: "Jazz / Soul / Funk", y: 1993, p: 2, c: 1, via: "Mujeres instrumentistas", desc: "Bajista, compositora y productora con una carrera que ha cambiado de piel muchas veces, del funk y el neo soul de Plantation Lullabies (1993) a Comet, Come to Me y sus discos de Blue Note, y muy pareja en todas. The Omnichord Real Book (2023) ganó el primer Grammy al mejor disco de jazz alternativo: doble, sin género fijo, entre neo soul, funk, afrobeat, hip-hop y experimental. Le siguió No More Water: The Gospel of James Baldwin (2024), y el 2 de octubre sale Synonym, un disco de duetos. Entrada: The Omnichord Real Book.", origin: "rec", pick: true, female: true },
  { name: "BIG|BRAVE", genre: "Experimental / Sludge Metal (CA)", y: 2012, p: 2, via: "Mujeres instrumentistas", desc: "Robin Wattie a la guitarra y la voz en un trío de Montreal que hace metal hipnótico y monolítico cruzado con drone y folk. Vital (2021) y nature morte (2023) son la cumbre; en 2025 sacaron OST, improvisado e instrumental, y en junio de 2026 in grief or in hope, un disco sin batería construido sobre armónicos y amplificadores. Entrada: Vital.", origin: "rec", pick: true, female: true },
  { name: "Crypta", genre: "Death Metal (BR)", y: 2019, p: 3, via: "Mujeres instrumentistas", desc: "Death metal brasileño fundado por Fernanda Lira, al bajo y la voz, y Luana Dametto, a la batería, ambas ex de Nervosa. Dos discos sólidos y bien recibidos, competentes pero dentro de la plantilla del género. Entrada: Shades of Sorrow.", origin: "rec", pick: true, female: true }
];

// ===========================================================================
// === BARRIDO ANCESTRAL Y DE CONTENEDORES (ago 2026) ========================
// Encontrado con el método nuevo: en vez de preguntar "que saco esta banda",
// enumerar ancestros de los tier 1, sellos, productores, festivales, premios
// y escenas, y cruzar hacia atras. Saco ~215 ausentes; esto es lo que pasa
// el filtro #1. Lote 1.
// ===========================================================================
const ANCESTROS = [
  // ----- LOS ANCESTROS DE TUS TIER 1 -----
  { name: "Queen", genre: "Art Rock / Hard Rock", desc: "Brian May graba capas de guitarra armonizadas entre sí para imitar una sección de metales o una orquesta, escribiendo cada voz por separado, y las canciones encadenan secciones sin volver al estribillo. The Prophet's Song lleva un canon vocal a varias voces hecho solo con la voz de Mercury superpuesta. Y reinventaban de disco a disco: ópera, funk, rockabilly, synth-pop, gospel. De Queen II (1974) a Jazz (1978) es la racha; Hot Space (1982) es el punto bajo, e Innuendo (1991) vuelve arriba. Entra por A Night at the Opera, luego Jazz.", origin: "rec", p: 1, y: 1970, c: 1 },
  { name: "Miles Davis", genre: "Jazz Fusion", y: 1955, p: 1, c: 1, via: "Ancestros", desc: "Cambió de sistema cinco veces y en cada uno escribió algo que antes no existía: el nonet de Birth of the Cool, el quinteto de hard bop, Kind of Blue montado sobre modos en vez de sobre cambios de acorde, el segundo quinteto tocando sin cifrado fijo, y Bitches Brew grabado como improvisación larga y armado después en la mesa de edición. De 1955 a 1975 casi no hay disco flojo, On the Corner incluido; los de los ochenta, de Decoy y You're Under Arrest a Tutu, Amandla y Doo-Bop, bajan mucho. Entrada: Kind of Blue, luego Bitches Brew.", origin: "rec", pick: true },
  { name: "Celtic Frost", genre: "Avant-garde Metal / Thrash (CH)", desc: "Into the Pandemonium (1987) metió orquesta completa, soprano, timbales y cuerdas en un disco de metal extremo, más una versión de new wave y percusión tribal, cuando eso no se hacía. Tom G. Warrior lo explicó así: odiaban los límites no escritos de la escena metal. Y no es solo el arreglo: los riffs van a medios tiempos pesadísimos con acentos desplazados y su famoso golpe de voz corta la frase en sitios raros. To Mega Therion (1985) es la otra cumbre, y Monotheist (2006) volvió a cambiarlo todo otra vez. La excepción es Cold Lake (1988), un giro al glam que el propio Warrior repudió. Entrada: Into the Pandemonium, luego To Mega Therion.", origin: "rec", p: 1, y: 1984, c: 1 },
  { name: "Bathory", genre: "Black Metal / Viking Folk (SE)", desc: "Quorthon lo hizo casi todo solo, en dos etapas con lenguajes distintos. La primera, de Bathory (1984) a The Return y Under the Sign of the Black Mark (1987), es black metal primitivo y rapidísimo, y fijó la plantilla del género. La segunda, de Blood Fire Death (1988) a Hammerheart (1990) y Twilight of the Gods (1991), inventa el viking metal: tempos lentos y machacones, coros épicos de una sola voz multiplicada, pasajes acústicos entre medias y grabación cruda a propósito. Requiem y Octagon (1994-95), una vuelta al thrash, son lo más flojo; Blood on Ice (1996) y Nordland I y II (2002-03) regresan a lo épico. Quorthon murió en 2004, a los 38. Enorme de atmósfera y deliberadamente primitivo de ejecución. Entra por Hammerheart.", origin: "rec", p: 2, y: 1983, c: 1 },
  { name: "Can", genre: "Krautrock / Experimental (DE)", y: 1968, p: 2, c: 1, via: "Ancestros", desc: "El krautrock más rítmico: Jaki Liebezeit tocaba un kit de jazz casi solo de toms y caja, en patrones hipnóticos que apenas cambian, y sobre ellos el bajo de Holger Czukay y la guitarra de Michael Karoli improvisan y se montan después en la edición de cinta. Monster Movie (1969), Tago Mago, Ege Bamyasi, Future Days y Soon Over Babaluma (1974) son cinco discos seguidos de primer nivel; desde Flow Motion (1976) la escritura se diluye hacia un rock más convencional y lo de 1977 a 1989 es lo más flojo. Entrada: Tago Mago, luego Future Days.", origin: "rec", pick: true },
  { name: "Killing Joke", genre: "Post-Punk / Industrial (UK)", y: 1978, p: 1, c: 1, via: "Ancestros", desc: "Acordes abiertos de guitarra repetidos como un solo gesto sobre un bajo que lleva la melodía y una batería casi tribal: la canción avanza por presión acumulada y no por progresión de acordes. El mapa: Killing Joke (1980), What's THIS For...! (1981), Revelations (1982), Fire Dances (1983) y Night Time (1985) son la primera cumbre; Brighter Than a Thousand Suns (1986) y Outside the Gate (1988) se ablandan y son lo más flojo; Extremities, Dirt & Various Repressed Emotions (1990) y Pandemonium (1994) vuelven a la dureza; Democracy (1996) es irregular, y de Killing Joke (2003), con Dave Grohl a la batería, y Hosannas from the Basements of Hell (2006) a la formación original reunida en Absolute Dissent (2010), MMXII (2012) y Pylon (2015) está de lo mejor que hicieron. Geordie Walker murió en 2023. Entrada: Killing Joke (1980).", origin: "rec", pick: true },
  { name: "Led Zeppelin", genre: "Hard Rock (clásico)", y: 1968, p: 1, via: "Ancestros", desc: "John Bonham toca detrás del pulso con un sonido de bombo enorme y un pie derecho que hace tresillos rapidísimos con un solo pedal, y su forma de colocar el golpe es de las más estudiadas que existen; John Paul Jones toca bajo, teclados y mandolina, y escribe los arreglos. Y los discos son más raros de lo que su fama sugiere: el III es folk acústico y Houses of the Holy tiene funk y reggae. El mapa: Led Zeppelin I y II (1969), III (1970), el IV (1971), Houses of the Holy (1973) y Physical Graffiti (1975) son la cumbre; Presence (1976) está cerca, e In Through the Out Door (1979) y Coda (1982) cierran por debajo. Entrada: Physical Graffiti.", origin: "rec", pick: true },
  { name: "Motörhead", genre: "Heavy Metal / Speed (UK)", y: 1975, p: 2, via: "Ancestros", desc: "El puente entre punk y metal del que sale el thrash: velocidad, el bajo distorsionado de Lemmy tocado como guitarra rítmica y el doble bombo de Phil Taylor. No es complejo, es inconfundible. Lemmy murió en diciembre de 2015 y el grupo terminó ahí. El mapa: de Overkill (1979), Bomber y Ace of Spades (1980) a Iron Fist (1982) está lo esencial; Orgasmatron (1986) y 1916 (1991) son los mejores de la etapa media, y de Inferno (2004) a Bad Magic (2015) la calidad se mantuvo hasta el final. Entrada: Ace of Spades, luego Overkill.", origin: "rec", pick: true },
  { name: "Possessed", genre: "Death / Thrash Metal", y: 1983, p: 2, via: "Ancestros", desc: "Seven Churches (1985) es, para mucha gente, el primer disco de death metal: thrash acelerado con voz gutural y riffs cromáticos que anticipan el género. El mapa: Seven Churches (1985) y Beyond the Gates (1986), más pulido y menos salvaje; Jeff Becerra quedó parapléjico en 1989 y volvió con Revelations of Oblivion (2019), a buen nivel. Entrada: Seven Churches.", origin: "rec", pick: true },
  { name: "Wishbone Ash", genre: "Hard Rock (clásico)", y: 1969, p: 2, via: "Ancestros", desc: "Inventaron la armonía de guitarras gemelas: dos guitarras solistas tocando líneas armonizadas en lugar de una solista y una rítmica, la técnica que luego definen Thin Lizzy e Iron Maiden. Argus (1972) es el disco donde queda establecida. El mapa: Wishbone Ash (1970), Pilgrimage (1971) y Argus (1972) son la cumbre; Wishbone Four (1973) y There's the Rub (1974) siguen, y desde New England (1976) el nivel baja poco a poco. Entrada: Argus.", origin: "rec", pick: true },
  { name: "Blue Öyster Cult", genre: "Hard Rock (clásico)", y: 1967, p: 2, c: 1, via: "Ancestros", desc: "Rock ocultista con letras crípticas y conceptos de ciencia ficción, mucho más raro y literario de lo que su fama de banda de un solo éxito sugiere; Ghost viene directamente de aquí. Imaginos es un disco conceptual delirante. El mapa: Blue Öyster Cult (1972), Tyranny and Mutation (1973) y Secret Treaties (1974) son la cumbre; Agents of Fortune (1976) y Spectres (1977) están cerca; lo de los ochenta es irregular salvo Imaginos (1988); The Symbol Remains (2020) fue la vuelta, y Ghost Stories (2024) cierra con material de archivo. Entrada: Secret Treaties.", origin: "rec", pick: true },
  { name: "Mayhem", genre: "Black Metal (NO)", y: 1984, p: 2, via: "Ancestros", desc: "Black metal noruego en su forma definitiva: De Mysteriis Dom Sathanas (1994) tiene la batería de Hellhammer con blast beats de precisión casi mecánica y riffs de trémolo disonantes, y los discos posteriores se fueron a terrenos más raros: Grand Declaration of War (2000) y Ordo ad Chao (2007), experimentales, Esoteric Warfare y Daemon, más clásicos, y Liturgy of Death (2026). Entrada: De Mysteriis Dom Sathanas.", origin: "rec", pick: true },
  { name: "Darkthrone", genre: "Black Metal (NO)", y: 1986, p: 2, c: 1, via: "Ancestros", desc: "Pilar del black noruego que además muta de verdad: empezaron como death metal técnico en Soulside Journey (1991), se pasaron al black más crudo posible en A Blaze in the Northern Sky, Under a Funeral Moon y Transilvanian Hunger (1994), y desde The Cult Is Alive (2006) hacen crust y heavy metal setentero. Pocas discografías cambian tanto de piel. Entrada: A Blaze in the Northern Sky.", origin: "rec", pick: true },
  { name: "Melvins", genre: "Sludge / Experimental", desc: "Cómo suenan: riffs bajísimos tocados a tempos absurdamente lentos y estirados hasta incomodar, con Dale Crover haciendo de batería una parte protagonista y no una base, y una discografía que salta del drone más pesado al punk más rápido y a discos de puro ruido, a veces dentro del mismo álbum. Sacaron disco conjunto con Napalm Death en 2026. El mapa: Gluey Porch Treatments (1987) y Ozma (1989) son lo más crudo; de Bullhead (1991) y Lysol (1992) a Houdini (1993), Stoner Witch (1994) y Stag (1996) está la cumbre; con dos baterías, de (A) Senile Animal (2006) a Nude with Boots (2008) y The Bride Screamed Murder (2010), llega la segunda, y lo posterior, hasta Tarantula Heart (2024), es irregular. Entra por Bullhead, luego Lysol.", origin: "rec", p: 2, y: 1983, c: 1 },
  { name: "My Bloody Valentine", genre: "Shoegaze / Dream Pop (IE)", y: 1983, p: 2, via: "Ancestros", desc: "Kevin Shields inventó la técnica de glide guitar, tocando con la palanca de trémolo durante todo el acorde para que suene desafinado y líquido, y la usó para apilar capas hasta que la guitarra se vuelve textura. Tres discos: Isn't Anything (1988), Loveless (1991), la cumbre, y m b v (2013), veintidós años después. De ahí salen el blackgaze y parte del sonido de Deftones. Entrada: Loveless.", origin: "rec", pick: true },
  { name: "Sonic Youth", genre: "Noise Rock / Experimental", y: 1981, p: 2, c: 1, via: "Ancestros", desc: "Guitarras en afinaciones alternativas inventadas canción a canción, preparadas con baquetas y destornilladores, que suenan a disonancias abiertas y a feedback controlado en vez de acordes, sobre la batería de Steve Shelley. EVOL (1986), Sister, Daydream Nation (1988) y Goo son la cumbre; lo posterior alterna discos notables como Murray Street con otros más rutinarios. Entrada: Daydream Nation.", origin: "rec", pick: true },
  { name: "The Velvet Underground", genre: "Art Rock / Experimental", y: 1965, p: 3, c: 1, via: "Ancestros", desc: "La viola eléctrica con drone de John Cale, que venía de la vanguardia minimalista, metida dentro de canciones de rock en 1967, con la batería de Moe Tucker de pie y sin platillos marcando un pulso primitivo. The Velvet Underground & Nico y White Light/White Heat (1968), con los diecisiete minutos de ruido y repetición de Sister Ray, son lo radical; después se vuelven una banda de canciones. Su peso es más de influencia que de escritura instrumental. Entrada: White Light/White Heat.", origin: "rec", pick: true },
  { name: "Helmet", genre: "Alt Metal / Noise Rock", y: 1989, p: 2, via: "Ancestros", desc: "Page Hamilton venía del jazz y aplicó esa formación a riffs de una sola nota, staccato y con los silencios colocados como parte del ritmo: el groove está en lo que no suena. Strap It On, Meantime y Betty funcionan con la misma mecánica. El mapa: Strap It On (1990), Meantime (1992) y Betty (1994), con más swing y jazz, son la cumbre; Aftertaste (1997) cierra la etapa clásica; desde Size Matters (2004), con Hamilton y músicos nuevos, el nivel baja, y Left (2023) es el último. Hamilton prepara su primer disco en solitario. Entrada: Meantime.", origin: "rec", pick: true },
  { name: "Funkadelic", genre: "Funk / Psych Rock", y: 1968, p: 2, c: 1, via: "Ancestros", desc: "Funk psicodélico con guitarras de rock: el solo de Eddie Hazel en Maggot Brain, diez minutos grabados de una sola toma, es de los grandes de la guitarra, y de aquí vienen OutKast, Thundercat y Flying Lotus. El mapa: Funkadelic (1970) y Free Your Mind... and Your Ass Will Follow (1970) abren; Maggot Brain (1971) es la cumbre; America Eats Its Young (1972), Cosmic Slop (1973) y Standing on the Verge of Getting It On (1974) están cerca, y One Nation Under a Groove (1978) es el último gran disco. Entrada: Maggot Brain.", origin: "rec", pick: true },
  { name: "Fela Kuti", genre: "Afrobeat / Funk (NG)", y: 1969, p: 2, via: "Ancestros", desc: "Inventó el afrobeat cruzando ritmos africanos con improvisación de jazz: polirritmia, secciones de metales y desarrollos instrumentales de veinte y treinta minutos sobre la batería de Tony Allen. Brian Eno le presentó su música a Talking Heads y de ahí salió la polirritmia de Remain in Light. El mapa: Expensive Shit (1975), Zombie (1976), Sorrow Tears and Blood (1977) y Shuffering and Shmiling (1978) son la cumbre con Tony Allen; sin él, Army Arrangement (1985) y Beasts of No Nation (1989). Murió en 1997. Entrada: Zombie.", origin: "rec", pick: true },
  { name: "Pentagram", genre: "Doom Metal", y: 1971, p: 3, via: "Ancestros", desc: "Proto-doom americano que grabó en los setenta sin publicar casi nada, y por eso su influencia llegó tarde. Riffs de Sabbath lentos y sencillos: más valor histórico que instrumental. Relentless (1985) y Day of Reckoning (1987). Entrada: Relentless.", origin: "rec", pick: true },
  { name: "Glenn Branca", genre: "Avant-garde / Experimental", y: 1979, p: 2, c: 3, via: "Ancestros", desc: "[Comodín] Compuso sinfonías para orquestas de guitarras eléctricas, cien de ellas en la 13 y la 16: el material no son acordes sino masas de armónicos que baten entre sí, con la afinación como parte de la composición y crescendos que se vuelven casi físicos. En sus grupos tocaron Thurston Moore y Lee Ranaldo, y su sello publicó los primeros discos de Swans. El mapa: The Ascension (1981) abre; las sinfonías 1 y 3 (Gloria, 1983), la 6, Devil Choirs at the Gates of Heaven (1989), y la 13, Hallucination City, para cien guitarras, son la cumbre; The Ascension: The Sequel (2010) y The Third Ascension (2016) cierran. Murió en 2018. Entrada: The Ascension.", origin: "rec", pick: true },

  // ----- SELLOS, PRODUCTORES Y ESCENAS -----
  { name: "Zu", genre: "Avant-garde / Jazz Metal (IT)", y: 1997, p: 2, c: 3, via: "Sellos y escenas", desc: "[Comodín] Trío romano de saxofón barítono, bajo y batería, sin guitarra: instrumentación de jazz con la agresión del metal extremo, todo instrumental, con bajo y saxo atacando riffs al unísono. Bromio (1999) y Carboniferous (2009), editado por Ipecac, son la cumbre. Entrada: Carboniferous.", origin: "rec", pick: true },
  { name: "Behold... The Arctopus", genre: "Prog / Instrumental", desc: "Metal instrumental de Brooklyn escrito con la lógica de la música clásica del siglo XX: sin voz, con Colin Marston a la Warr guitar cubriendo bajo y guitarra a la vez y motivos atonales superpuestos en métricas distintas, de una densidad brutal. Skullgrid (2007) es la referencia; Horrorscension (2012) se vuelve tan abstracto que cuesta seguirlo, y Cognitive Emancipation (2016) y Hapeleptic Overtrove (2020) recuperan parte del foco. Entrada: Skullgrid.", origin: "rec", p: 2, y: 2001, c: 2 },
  { name: "Amenra", genre: "Post-Metal / Sludge (BE)", y: 1999, p: 2, via: "Sellos y escenas", desc: "Post-metal belga y núcleo del colectivo Church of Ra: su serie de Masses construye cada tema por acumulación hasta el estallido, con la voz desgarrada de Colin H. van Eeckhout y pasajes casi en silencio. Mass V, Mass VI (2017) y De doorn (2021). Entrada: Mass VI.", origin: "rec", pick: true },
  { name: "Thinking Plague", genre: "Avant-garde / Chamber Rock", y: 1982, p: 2, via: "Sellos y escenas", desc: "RIO americano de Mike Johnson: música de cámara disonante con vientos, voz femenina y guitarra en contrapunto, en compases que no se asientan y con armonía cercana a la clásica del siglo XX. In This Life (1989), In Extremis (1998) y A History of Madness (2003) son la cumbre; los dos primeros y Decline and Fall quedan por debajo. Entrada: In Extremis.", origin: "rec", pick: true },
  { name: "Samla Mammas Manna", genre: "Avant-garde / Chamber Rock (SE)", y: 1969, p: 1, via: "Sellos y escenas", desc: "Uno de los cinco grupos del concierto fundacional del Rock in Opposition, en 1978: virtuosismo con referencias circenses y humor absurdo, comparado con la escritura de Zappa, con los teclados de Lars Hollmer y la guitarra de Coste Apetrea corriendo en unísonos rapidísimos sobre cambios de compás constantes e instrumentos raros en el rock. Samla Mammas Manna (1971), Måltid (1973), Klossa Knapitatet (1974) y los discos como Zamla Mammaz Manna sostienen ese nivel; Kaka (1999), la vuelta, baja algo. Entrada: Måltid.", origin: "rec", pick: true },
  { name: "Nik Bärtsch's Ronin", genre: "Jazz Fusion / Chamber (CH)", y: 2001, p: 2, via: "Sellos y escenas", desc: "Pianista suizo con un concepto propio que llama ritual groove music: piezas modulares numeradas, patrones entrelazados en compases pares e impares que se superponen y pulsos polimétricos. Minimalismo a lo Steve Reich con el groove de un grupo de funk. Stoa (2006), Holon (2008), Llyrìa (2010) y Awase (2018). Entrada: Stoa.", origin: "rec", pick: true },
  { name: "Virus", genre: "Avant-garde Metal (NO)", y: 2000, p: 2, via: "Sellos y escenas", desc: "Czral hizo primero Ved Buens Ende, black avant de acordes disonantes, y luego Virus para llevarlo más lejos del metal: guitarras disonantes y angulosas de la escuela del Voivod de Nothingface, un bajo protagonista que reclama atención constante y su voz grave. Carheart (2003), The Black Flux, The Agent That Shapes the Desert (2011) y Memento Collider (2016). Entrada: Carheart.", origin: "rec", pick: true },
  { name: "Pyrrhon", genre: "Dissonant Death Metal", y: 2008, p: 2, via: "Sellos y escenas", desc: "Death disonante de Brooklyn, comparable a Gorguts y Ulcerate pero con más grindcore y math rock encima, con la batería y la guitarra de Dylan DiLella tirando cada una por su lado. De The Mother of Virtues (2014) a What Passes for Survival, Abscess Time y Exhaust (2024), cada disco más extremo. Entrada: The Mother of Virtues.", origin: "rec", pick: true },
  { name: "Ad Nauseam", genre: "Dissonant Death Metal (IT)", desc: "La guitarra derecha y la izquierda viven bajo ritmos distintos y se cortan mutuamente a través de los compases, unificándose solo en los clímax, con una afinación propia para alejarse de los patrones melódicos habituales y una armonía que se oye heredera de Stravinsky, Xenakis, Scelsi y Ligeti. Dos discos, Nihil Quam Vacuitas Ordinatum Est (2015) e Imperative Imperceptible Impulse (2021), el mejor. Durísimo de escuchar. Entrada: Imperative Imperceptible Impulse.", origin: "rec", p: 1, y: 2011, c: 2 },
  { name: "Il Balletto di Bronzo", genre: "Prog Rock (IT)", y: 1969, p: 2, via: "Sellos y escenas", desc: "El lado negro del prog italiano: en Ys (1972), uno de los rarísimos discos de prog italiano oscuro, Gianni Leone, una especie de Keith Emerson italiano, teje una trama opresiva y claustrofóbica con órgano, moog, mellotron y espineta. Sirio 2222 (1970), el debut, es rock psicodélico más sencillo. Entrada: Ys.", origin: "rec", pick: true },
  { name: "Motorpsycho", genre: "Prog Rock / Psych (NO)", y: 1989, p: 1, c: 1, via: "Sellos y escenas", desc: "Noruegos que en treinta y cinco años han saltado del psych pesado al prog, al hard rock setentero y a las piezas largas con orquesta, casi sin un disco flojo: Timothy's Monster (1994), Blissard, Trust Us (1998), Let Them Eat Cake, Phanerothyme, Heavy Metal Fruit (2010), The Death Defying Unicorn (2012), con orquesta, la trilogía The Tower, The Crucible y The All Is One (2017-2020), su doble homónimo de 2025 y The Gaia II Space Corps (febrero de 2026). Temas de quince y veinte minutos que se desarrollan de verdad, con una base rítmica que empuja como un grupo de jazz. Entrada: The Tower.", origin: "rec", pick: true },
  { name: "Shakti", genre: "Jazz Fusion (IN)", desc: "Fusión indo-británica de John McLaughlin con L. Shankar al violín y Zakir Hussain a la tabla. Todo va montado sobre talas, los ciclos rítmicos indios de siete, nueve o más tiempos, y el violín y la guitarra se turnan frases construidas sobre esos ciclos, con pasajes de konnakol (percusión recitada con la voz) marcando la subdivisión antes de tocarla. Es de lo rítmicamente más complejo del catálogo entero, y lo sostienen desde los tres discos de los setenta hasta This Moment (2023), su primer disco de estudio en 46 años. Zakir Hussain murió en diciembre de 2024 y McLaughlin dio el grupo por terminado; Mind Explosion (2025), grabado en la gira del 50 aniversario, es el cierre. Entrada: A Handful of Beauty.", origin: "rec", p: 1, y: 1973, c: 2 },
  { name: "Konono Nº1", genre: "Experimental / Funk (CD)", y: 1966, p: 2, c: 3, via: "Sellos y escenas", desc: "[Comodín] Tres likembes congoleños repartidos en grave, medio y agudo tocan patrones cortos que se repiten y se desfasan entre sí, así que la música avanza por el roce entre las tres capas y no por acordes, sobre percusión de ollas, sartenes y piezas de coche. Y la decisión que lo define: adoptaron como material las distorsiones que su propio equipo producía sin querer. El mapa: Congotronics (2004) es la cumbre; Live at Couleur Café (2007), Assume Crash Position (2010) y Konono Nº1 Meets Batida (2016) siguen. Entrada: Congotronics.", origin: "rec", pick: true },

  // ----- LA DECADA QUE FALTABA: 2020s -----
  { name: "The Callous Daoboys", genre: "Mathcore / Avant-garde", y: 2016, p: 2, via: "Escena 2020s", desc: "Mathcore con violinista fundadora (Amber Christman) y saxofón (Rich Castillo) dentro de la formación, no de invitados, que cruzan los riffs rotos con melodía y cambios de estilo bruscos. Es la línea de Dillinger, The Fall of Troy y The Number Twelve Looks Like You actualizada, con instrumentación ampliada. El mapa: Die on Mars (2019) es más crudo; Celebrity Therapist (2022) e I Don't Want to See You in Heaven (mayo de 2025) son la cumbre, y en 2026 han sacado dos temas nuevos. Entrada: Celebrity Therapist.", origin: "rec", pick: true },
  { name: "Slift", genre: "Psych Rock / Prog (FR)", y: 2016, p: 2, via: "Escena 2020s", desc: "Trío francés que cruza psych, space rock y stoner con la escala épica del post-rock: riffs repetidos hasta el trance, guitarras con delay en capas y una batería que empuja sin parar. Ummon (2020) e Ilion (2024), editado por Sub Pop, son su cumbre; Fantasia (2026) se recibió más tibio. Entrada: Ilion.", origin: "rec", pick: true },
  { name: "Green Carnation", genre: "Progressive Metal (NO)", y: 1990, p: 2, via: "Escena 2020s", desc: "Noruegos que pasaron del doom a un prog metal de estructuras largas: Light of Day, Day of Darkness (2001) es una sola pieza de sesenta minutos que alterna coros, metal y pasajes acústicos sin perder el hilo. Ahora publican una trilogía entera, A Dark Poem, con Shores of Melancholia (2025) y Sanguis (2026) en Season of Mist. Entrada: Light of Day, Day of Darkness.", origin: "rec", pick: true },
  { name: "Kardashev", genre: "Progressive Deathcore", y: 2012, p: 2, via: "Escena 2020s", desc: "Deathcore y death progresivo de Tempe, Arizona, cruzado con shoegaze, lo que ellos llaman deathgaze: guitarras en capas de reverb que forman muros armónicos sobre blast beats, pasajes etéreos con dinámica de verdad y voces que pasan del gutural al canto limpio. El mapa: Peripety (2015) abre; los EP The Almanac (2017) y The Baring of Shadows (2020) fijan el sonido; Liminal Rite (2022) y Alunea (abril de 2025), su secuela narrativa, son la cumbre, y en abril de 2026 sacaron Alunea en versión instrumental. Entrada: The Baring of Shadows, luego Alunea.", origin: "rec", pick: true },
  { name: "Nospūn", genre: "Progressive Metal", y: 2019, p: 2, via: "Escena 2020s", desc: "La crítica los describe combinando los cambios complejos de Between the Buried and Me con la rareza de Devin Townsend y Native Construct. Opus (2023) y el EP Ozai (2025). Entrada: Opus.", origin: "rec", pick: true }
];

// ===========================================================================
