const ANCESTROS_2 = [
  // ----- KRAUTROCK -----
  { name: "Neu!", genre: "Krautrock / Experimental (DE)", y: 1971, p: 3, via: "Ancestros", desc: "Klaus Dinger y Michael Rother, salidos de Kraftwerk, fijaron el beat motorik: un 4/4 mecánico que se repite sobre sí mismo mientras la guitarra y los efectos van cambiando el paisaje. Neu! (1972) y Neu! 75 son lo mejor; Neu! 2 rellena la segunda cara con su single a distintas velocidades. Hipnótico, pero muy sencillo por dentro. Entrada: Neu!.", origin: "rec", pick: true },
  { name: "Faust", genre: "Krautrock / Experimental (DE)", y: 1971, p: 2, c: 1, via: "Ancestros", desc: "El ala más destructiva del krautrock: collage de cinta, ruido industrial y canciones desarmadas a mitad, grabado en una escuela reconvertida en estudio. Faust (1971), So Far, The Faust Tapes y Faust IV (1973) son la cumbre; la vuelta de los noventa en adelante es mucho más irregular. Entrada: Faust IV, luego So Far.", origin: "rec", pick: true },

  // ----- DRONE Y SOUTHERN LORD -----
  { name: "Earth", genre: "Drone / Doom Metal", y: 1989, p: 2, c: 1, via: "Sellos y escenas", desc: "Dylan Carlson prácticamente creó el drone metal con Earth 2 (1993), un ejercicio monolítico y glacial, y después mutaron hacia una americana instrumental de guitarra limpia y reverberante sin perder la lentitud: Hex (2005), The Bees Made Honey in the Lion's Skull, Angels of Darkness, Demons of Light I y II y Full Upon Her Burning Lips (2019). Entrada: Earth 2, luego Hex.", origin: "rec", pick: true },
  { name: "Sunn O)))", genre: "Drone / Doom Metal", y: 1998, p: 2, via: "Sellos y escenas", desc: "Nacieron en 1998 como tributo a Earth y acabaron definiendo el drone metal moderno: muros de amplificadores y volumen físico, con colaboradores de fuera del metal. Monoliths & Dimensions (2009) es la cumbre, con metales y coro, y Life Metal (2019) está cerca. Entrada: Monoliths & Dimensions.", origin: "rec", pick: true },
  { name: "Om", genre: "Doom Metal / Ritual", y: 2003, p: 2, via: "Sellos y escenas", desc: "Al Cisneros salió de Sleep y montó esto: solo bajo y batería, sin guitarra, tocando doom ritual con cantos que parecen liturgia, con el bajo llevando toda la armonía. El mapa: Variations on a Theme (2005), Conference of the Birds (2006) y Pilgrimage (2007), la cumbre, son con Chris Hakius a la batería; desde God Is Good (2009), con Emil Amos, meten tanpura, chelo y voces, hasta Advaitic Songs (2012). Entrada: Pilgrimage.", origin: "rec", pick: true },
  { name: "Khanate", genre: "Drone / Doom Metal", y: 2000, p: 3, via: "Sellos y escenas", desc: "Stephen O'Malley (Sunn O)))) en su proyecto mas extremo: doom tan lento que se deshace, con alaridos de Alan Dubin encima. Brutal y muy exigente. Entrada: Things Viral.", origin: "rec", pick: true },
  { name: "Wolves in the Throne Room", genre: "Atmospheric Black Metal", y: 2003, p: 2, via: "Sellos y escenas", desc: "Black atmosférico de Olympia: temas larguísimos construidos como paisaje, con dinámica real entre lo crudo y lo ambiental. Two Hunters (2007), Black Cascade, Celestite (2014), todo sintetizadores, Thrice Woven (2017) y Primordial Arcana (2021). Entrada: Two Hunters.", origin: "rec", pick: true },

  // ----- PROG ESCANDINAVO E ITALIANO -----
  { name: "Änglagård", genre: "Prog Rock (SE)", y: 1991, p: 2, via: "Sellos y escenas", desc: "Hybris (1992) encendió el revival progresivo escandinavo: texturas empapadas de mellotron, compases complejos, flauta y melancolía nórdica, más oscuro e intenso que sus referentes setenteros. Tres discos, los tres a gran nivel: Hybris, Epilog (1994), instrumental, y Viljans öga (2012). Entrada: Hybris.", origin: "rec", pick: true },
  { name: "Anekdoten", genre: "Prog Rock (SE)", y: 1990, p: 2, via: "Sellos y escenas", desc: "La otra mitad del revival sueco, con el mellotron como instrumento central y una pesadez que viene del King Crimson de los setenta. Muy parejos: Vemod (1993), Nucleus (1995), From Within, Gravity, A Time of Day y Until All the Ghosts Are Gone (2015). Entrada: Vemod.", origin: "rec", pick: true },
  { name: "Wobbler", genre: "Prog Rock (NO)", y: 1999, p: 3, via: "Sellos y escenas", desc: "Noruegos que evocan a King Crimson, Genesis y Gentle Giant con folk y clásica escandinava encima: temas largos y complejos con mellotron, minimoog, Hammond y clavecín. Muy parejos: Hinterland (2005), Afterglow, Rites at Dawn (2011), From Silence to Somewhere (2017) y Dwellers of the Deep (2020). Entrada: From Silence to Somewhere.", origin: "rec", pick: true },
  { name: "Premiata Forneria Marconi", genre: "Prog Rock (IT)", y: 1970, p: 2, via: "Sellos y escenas", desc: "El prog italiano que sí cruzó fronteras: violín, flauta y virtuosismo camerístico con melodía mediterránea. Storia di un minuto y Per un amico (1972), Photos of Ghosts, L'isola di niente (1974) y Chocolate Kings (1975) son la cumbre; en los ochenta se van al pop y bajan, y la vuelta de los dos mil está a buen nivel. Entrada: Per un amico.", origin: "rec", pick: true },
  { name: "Museo Rosenbach", genre: "Prog Rock (IT)", y: 1971, p: 2, via: "Sellos y escenas", desc: "Un solo disco esencial, Zarathustra (1973), con una suite conceptual de veinte minutos sobre Nietzsche, mellotron pesado y guitarras de hard rock dentro del prog italiano. Volvieron décadas después, más por debajo. El mapa: Zarathustra (1973) es la obra; Exit (2000) y Barbarica (2013) son la vuelta. Entrada: Zarathustra.", origin: "rec", pick: true },

  // ----- RIO / AVANT-PROG -----
  { name: "Art Zoyd", genre: "Avant-garde / Chamber Rock (FR)", y: 1968, p: 2, via: "Sellos y escenas", desc: "Cámara oscura del Rock in Opposition: violín, contrabajo, metales y percusión, construyendo algo entre la música de cámara del siglo XX y el terror cinematográfico, en ostinatos que se aprietan hasta el agobio. Symphonie pour le jour où brûleront les cités (1976), Musique pour l'Odyssée, Génération sans futur y Phase IV (1982) son la cumbre; desde finales de los ochenta la electrónica y las bandas sonoras para cine mudo lo vuelven irregular. Entrada: Musique pour l'Odyssée.", origin: "rec", pick: true },
  { name: "Aksak Maboul", genre: "Avant-garde / Experimental (BE)", y: 1977, p: 2, c: 1, via: "Sellos y escenas", desc: "Grupo belga de Marc Hollander que se sumó al Rock in Opposition al ampliarse tras el concierto fundacional, por el lado juguetón: mezcla folk balcánico, minimalismo, jazz y electrónica primitiva sin quedarse en ninguno, con Fred Frith y Chris Cutler como invitados en el segundo disco. Onze danses pour combattre la migraine (1977), Un peu de l'âme des bandits (1980) y, cuarenta años después, Figures (2020), al mismo nivel. Entrada: Un peu de l'âme des bandits.", origin: "rec", pick: true },

  // ----- NOISE ROCK Y MATH DE CHICAGO -----
  { name: "Shellac", genre: "Noise Rock / Math Rock", y: 1992, p: 2, via: "Sellos y escenas", desc: "Steve Albini en su propia banda: trío de precisión quirúrgica, con el bajo de Bob Weston al frente, los silencios usados como ritmo y una grabación sin ninguna capa oculta. Todo lo que oyes es lo que había en la sala. Albini murió de un infarto el 7 de mayo de 2024, a los 61 años; el sexto disco de Shellac, To All Trains, salió diez días después. Aquí acaba una línea que empieza en Big Black. El mapa: At Action Park (1994), Terraform (1998), 1000 Hurts (2000), la cumbre, Excellent Italian Greyhound (2007), Dude Incredible (2014) y To All Trains (2024).", origin: "rec", c: 2 },
  { name: "The Jesus Lizard", genre: "Noise Rock / Post-Punk", y: 1987, p: 1, via: "Sellos y escenas", desc: "La guitarra angular y disonante de Duane Denison sobre una sección rítmica que funciona como maquinaria: el bajo de David Wm. Sims toca la línea principal, repetida sin variar y muy adelante en la mezcla, mientras Mac McNeilly acentúa a contratiempo y David Yow aúlla encima sin seguir el compás. Goat, Liar y Down funcionan con esa misma mecánica sin desafinarla. El mapa: Head (1990) abre; Goat (1991), Liar (1992) y Down (1994) son la cumbre; Shot (1996) y Blue (1998), ya en multinacional, bajan algo, y Rack (2024), el primero en veintiséis años, vuelve a la altura. Entrada: Goat.", origin: "rec", pick: true },
  { name: "U.S. Maple", genre: "Noise Rock / Experimental", y: 1995, p: 3, c: 1, via: "Sellos y escenas", desc: "Desmontaron el rock hasta dejar las piezas sueltas: riffs que no encajan a propósito, silencios largos y una voz que susurra y se rompe. Genuinamente incómodo y sin pares obvios. Entrada: Long Hair in Three Stages.", origin: "rec", pick: true },

  // ----- JAZZ NORDICO -----
  { name: "Supersilent", genre: "Jazz / Experimental (NO)", y: 1997, p: 2, via: "Sellos y escenas", desc: "Improvisación electroacústica total: nunca ensayan ni componen nada de antemano y aun así construyen piezas con arquitectura, con la trompeta procesada de Arve Henriksen, la electrónica y el ruido de Helge Sten y la batería de Jarle Vespestad. Discos numerados, del 1-3 (1997) en adelante, en Rune Grammofon. El mapa: 1-3 (1997) y 6 (2003) son la cumbre; de 4 (1998) a 8 (2007) con batería, y desde 10 (2010), ya sin Jarle Vespestad, más abstractos y electrónicos. Entrada: 6.", origin: "rec", pick: true },
  { name: "Arve Henriksen", genre: "Jazz / Ambient (NO)", y: 1994, p: 2, via: "Sellos y escenas", desc: "Toca la trompeta con una embocadura que la hace sonar como un shakuhachi japonés: aire, madera y casi nada de metal, sobre electrónica y ambient. Muy parejo de Sakuteiki (2001) a Cartography (2008) y The Height of the Reeds (2011). Entrada: Cartography.", origin: "rec", pick: true },
  { name: "Elephant9", genre: "Jazz Fusion (NO)", y: 2007, p: 2, via: "Sellos y escenas", desc: "Trío noruego de órgano Hammond, bajo y batería que toca fusión pesada con energía de rock setentero: el bajo de Nikolai Hængsle y la batería de Torstein Lofthus empujan temas largos mientras Ståle Storløkken se desboca en el órgano, a veces con Reine Fiske, de Dungen, a la guitarra. Muy parejos: Walk the Nile (2010), Atlantis (2012), Silver Mountain (2015), Psychedelic Backfire I y II (2019), Arrival of the New Elders (2021) y Mythical River (2024). Entrada: Walk the Nile.", origin: "rec", pick: true },

  // ----- POST-ROCK DE MONTREAL -----
  { name: "Do Make Say Think", genre: "Post-Rock (CA)", y: 1995, p: 2, via: "Sellos y escenas", desc: "La rama jazzística del sello Constellation: dos baterías a la vez, metales y guitarras entrelazadas construyendo un post-rock más cálido y orgánico que el de sus vecinos. & Yet & Yet (2000), Winter Hymn Country Hymn Secret Hymn (2003) y Stubborn Persistent Illusions (2017). Entrada: & Yet & Yet.", origin: "rec", pick: true },
  { name: "Esmerine", genre: "Post-Rock / Chamber (CA)", y: 2000, p: 3, via: "Sellos y escenas", desc: "Cámara post-rock nacida de Godspeed: marimba, chelo y percusión construyendo piezas sin guitarra eléctrica. Entrada: La Lechuza.", origin: "rec", pick: true },

  // ----- EJE ZORN / LASWELL / FRITH -----
  { name: "Painkiller", genre: "Avant-garde / Free Jazz Noise (US)", y: 1991, p: 2, via: "Sellos y escenas", desc: "John Zorn al saxo, Bill Laswell al bajo y Mick Harris, de Napalm Death, a la batería: grindcore y free jazz colisionando en piezas de dos minutos. El mapa: Guts of a Virgin (1991) y Buried Secrets (1992) son lo más grind; Execution Ground (1994) mete dub y ambient en piezas largas, y los directos Rituals y Talisman completan. Entrada: Guts of a Virgin.", origin: "rec", pick: true },
  { name: "Fred Frith", genre: "Avant-garde / Experimental (UK)", y: 1974, p: 2, c: 1, via: "Sellos y escenas", desc: "El guitarrista de Henry Cow: toca la guitarra acostada, con objetos, arcos y cadenas sobre las cuerdas, y el resultado son timbres percusivos y armónicos que la guitarra no suele dar. En solitario salta de la improvisación pura de Guitar Solos (1974) a Gravity (1980) y Speechless (1981), danzas en compases impares con aire de folk balcánico, lo más compuesto y accesible de su obra. Entrada: Gravity.", origin: "rec", pick: true },
  { name: "Praxis", genre: "Avant-garde / Funk Metal", y: 1992, p: 3, via: "Sellos y escenas", desc: "Bill Laswell juntando a Buckethead con Bootsy Collins y Brain a la batería: funk metal mutante con dub y ruido. Entrada: Transmutation.", origin: "rec", pick: true },

  // ----- CLASICA CONTEMPORANEA -----
  { name: "Steve Reich", genre: "Minimalismo / Percusión (US)", y: 1965, p: 1, c: 1, via: "Clásica contemporánea", desc: "Inventó el phasing: dos músicos tocan el mismo patrón a velocidades ligerísimamente distintas hasta que se desfasan y aparecen ritmos que nadie toca. Drumming (1971) es una hora entera para bongós, marimbas y glockenspiels construida así, y Music for 18 Musicians (1976) monta pulsos repetidos sobre un ciclo de once acordes. Lo sostiene de Different Trains y el Sextet a Double Sextet. Entrada: Music for 18 Musicians. ▸ Versión: Steve Reich and Musicians (ECM, 1978).", origin: "rec", pick: true },
  { name: "Terry Riley", genre: "Minimalismo / Clásica moderna (US)", y: 1964, p: 3, via: "Clásica contemporánea", desc: "In C son 53 frases cortas que cada músico repite las veces que quiera antes de pasar a la siguiente: la pieza nunca suena igual dos veces y la estructura la deciden los intérpretes. Entrada: In C, luego A Rainbow in Curved Air.", origin: "rec", pick: true },
  { name: "Julius Eastman", genre: "Minimalismo / Clásica moderna (US)", y: 1973, p: 2, c: 3, via: "Clásica contemporánea", desc: "[Comodín] Practicaba lo que llamaba música orgánica: repetición, improvisación y transformación gradual del material, con una intensidad y una rabia ausentes del minimalismo de su época, en piezas para varios pianos o para conjunto abierto como Gay Guerrilla o Femenine. Murió en 1990 en la indigencia y sus partituras se perdieron; se recuperaron décadas después. Entrada: Femenine.", origin: "rec", pick: true },
  { name: "Caroline Shaw", genre: "Clásica moderna / Vocal (US)", y: 2009, p: 3, female: true, via: "Clásica contemporánea", desc: "Ganó el Pulitzer con Partita for 8 Voices (2013), una obra para voces que usa respiración, susurro y habla como material compositivo junto a armonía coral de raíz barroca. Trabaja con So Percussion y con el Attacca Quartet cruzando cámara y percusión. Entrada: Partita for 8 Voices.", origin: "rec", pick: true },
  { name: "Meredith Monk", genre: "Clásica moderna / Vocal (US)", y: 1966, p: 3, c: 3, female: true, via: "Clásica contemporánea", desc: "[Comodín] Desarrolló una técnica vocal extendida propia: usa la voz como instrumento puro, sin palabras, con registros y timbres que nadie más produce, sobre piano, órgano o conjunto de cámara en patrones repetidos. Dolmen Music (1981) y Turtle Dreams (1983). Entrada: Dolmen Music.", origin: "rec", pick: true },

  // ----- ELECTRONICA COMPLEJA -----
  { name: "Autechre", genre: "Electronic / Experimental (UK)", y: 1987, p: 2, c: 1, via: "Sellos y escenas", desc: "Usan procesos algorítmicos y síntesis modular para generar ritmos y texturas impredecibles: escriben el sistema y luego deciden qué se queda, así que la máquina compone dentro de reglas suyas. Empujaron la complejidad rítmica al límite en Tri Repetae (1995) y cada disco desde entonces es más abstracto, de Confield a las NTS Sessions de ocho horas. Es electrónica pura, sin un instrumento tocado. El mapa: Incunabula (1993) y Amber (1994) son ambient-techno; Tri Repetae (1995), Chiastic Slide (1997) y LP5 (1998) son la cumbre rítmica; Confield (2001), Draft 7.30 (2003) y Untilted (2005) la llevan al límite; Oversteps (2010) y Exai (2013) se mantienen, y elseq 1-5 (2016), NTS Sessions (2018), SIGN y PLUS (2020) son lo último. Entrada: Tri Repetae.", origin: "rec", pick: true },
  { name: "Squarepusher", genre: "Electronic / Jazz Fusion (UK)", y: 1994, p: 2, via: "Sellos y escenas", desc: "Tom Jenkinson es bajista virtuoso de verdad y toca el bajo encima de su propia programación de breakbeats imposibles: jazz fusión disfrazado de electrónica, e influencia directa de Flying Lotus. Muy parejo de Hard Normal Daddy (1997) a Ultravisitor (2004) y Dostrotime (2024), y en Kammerkonzert (abril de 2026) se pasó a la música de cámara. Entrada: Music Is Rotted One Note, luego Go Plastic.", origin: "rec", pick: true },
  { name: "Aphex Twin", genre: "Electronic / Experimental (UK)", y: 1991, p: 2, c: 1, via: "Sellos y escenas", desc: "Richard D. James pasa del ambient más calmado a la percusión programada más violenta sin avisar, a veces dentro del mismo disco: Drukqs alterna piano preparado a lo Satie con drill and bass a doscientas pulsaciones. Lo sostiene treinta años, de Selected Ambient Works 85-92 y Richard D. James Album a Syro (2014) y los EPs recientes. Es electrónica pura, sin banda. El mapa: Selected Ambient Works 85-92 (1992) y Volume II (1994) son la cara ambient; ...I Care Because You Do (1995) y Richard D. James Album (1996) la de percusión rota; Drukqs (2001) mezcla las dos, y Syro (2014) es la vuelta, con Collapse y Cheetah en EP. Entrada: Selected Ambient Works 85-92, luego Drukqs.", origin: "rec", pick: true },

  // ----- NO OCCIDENTAL -----
  { name: "Mdou Moctar", genre: "Psych Rock / Folk (NE)", y: 2008, p: 2, via: "No occidental", desc: "Guitarrista tuareg de Níger que cruza el blues del desierto con psicodelia eléctrica salvaje: solos de una velocidad y un fraseo que no se parecen a nada del rock occidental, sobre ritmos de takamba y assouf y una banda que empuja como un grupo de rock. El mapa: Afelan (2013) y Sousoume Tamachek (2017) abren; Ilana: The Creator (2019) sube el volumen; Afrique Victime (2021) y Funeral for Justice (2024) son la cumbre, y Tears of Injustice (2025) rehace Funeral for Justice en acústico. Entrada: Afrique Victime.", origin: "rec", pick: true },
  { name: "Tinariwen", genre: "Psych Rock / Folk (ML)", y: 1979, p: 2, via: "No occidental", desc: "Fundaron el blues del desierto tuareg: guitarras eléctricas entrelazadas en bucles hipnóticos sobre percusión de mano y coros en llamada y respuesta, nacido en los campos de refugiados del Sáhara. El mapa: The Radio Tisdas Sessions (2001) abre; Amassakoul (2004), Aman Iman (2007) e Imidiwan (2009) son la cumbre; Tassili (2011), acústico, ganó el Grammy; Emmaar (2014), Elwan (2017) y Amadjar (2019) siguen; Amatssou (2023) lo produjo Daniel Lanois, y Hoggar (marzo de 2026) es el último. Entrada: Aman Iman.", origin: "rec", pick: true },
  { name: "Mulatu Astatke", genre: "Jazz / Funk (ET)", y: 1965, p: 2, c: 1, via: "No occidental", desc: "Inventó el ethio-jazz: se formó en Londres, Nueva York y Boston y volvió a Etiopía a cruzar jazz y ritmos latinos con las escalas pentatónicas etíopes, con el vibráfono y las congas en primer plano. Sonido inconfundible desde el primer compás, de Mulatu of Ethiopia (1972) a Mulatu Steps Ahead (2010) y Mulatu Plays Mulatu (2025). Entrada: Mulatu of Ethiopia.", origin: "rec", pick: true },
  { name: "Erkin Koray", genre: "Psych Rock / Anatolian (TR)", desc: "[Comodín] El pionero del rock psicodélico turco: electrificó el bağlama, el laúd de mástil largo, y lo metió en una banda de rock con fuzz, así que las melodías van por modos anatolios sobre un ritmo firme de rock. Complejo de estructura no es; interesante de sonido, mucho. Elektronik Türküler (1974) y Erkin Koray (1977). Murió en 2023. Entrada: Elektronik Türküler.", origin: "rec", p: 2, y: 1957, c: 3 },
  { name: "Anouar Brahem", genre: "Jazz / Chamber (TN)", y: 1991, p: 2, via: "No occidental", desc: "Laudista tunecino en ECM que cruza la tradición árabe con el jazz de cámara europeo, en formaciones mínimas y con muchísimo silencio. Muy parejo de Barzakh (1991) a Thimar, Le Pas du Chat Noir, The Astounding Eyes of Rita (2009), Blue Maqams (2017) y After the Last Sky (2025). Entrada: The Astounding Eyes of Rita.", origin: "rec", pick: true },
  { name: "Agam", genre: "Progressive Metal (IN)", desc: "No es prog con un adorno indio encima: construyen desde las ragas y los talas del carnático, la tradición del sur de India de ciclos rítmicos de precisión matemática, y esos ciclos encajan de forma natural con los compases impares y las polirritmias del prog. Se les reconoce haber definido el rock progresivo carnático. Su disco reciente es Arrival of the Ethereal. El mapa: The Inner Self Awakens (2012) abre, y el reciente Arrival of the Ethereal lo lleva más lejos.", origin: "rec", p: 2, y: 2007, c: 1, via: "No occidental" },
  { name: "Trilok Gurtu", genre: "Jazz Fusion (IN)", y: 1976, p: 2, via: "No occidental", desc: "Percusionista indio que toca sentado en el suelo un set a medio camino entre la tabla y la batería occidental, y lo usa para cruzar los ciclos rítmicos indios, el konnakol y el jazz. Tocó con John McLaughlin y en el grupo Oregon. Living Magic (1991) es la cumbre. El mapa: Usfret (1988) y Living Magic (1991) abren; Crazy Saints (1993) y Believe (1995) son la cumbre. Entrada: Living Magic.", origin: "rec", pick: true },

  // ----- POST-METAL Y HYDRA HEAD -----
  { name: "Sumac", genre: "Post-Metal / Sludge", y: 2014, p: 2, via: "Sellos y escenas", desc: "Aaron Turner después de Isis, llevando el post-metal hacia la improvisación libre: los discos recientes se graban casi sin composición previa, con la estructura apareciendo en el momento. El mapa: The Deal (2015) y What One Becomes (2016) son lo más escrito; Love in Shadow (2018) abre la improvisación, y May You Be Held (2020) y The Healer (2024) la llevan más lejos. Entrada: The Healer.", origin: "rec", pick: true },
  { name: "Jesu", genre: "Post-Metal / Shoegaze (UK)", y: 2003, p: 3, via: "Sellos y escenas", desc: "Justin Broadrick después de Godflesh: la misma pesadez mecánica pero envuelta en capas de shoegaze y melodía. Entrada: Jesu (2004).", origin: "rec", pick: true },
  { name: "Old Man Gloom", genre: "Post-Metal / Sludge", y: 1999, p: 3, via: "Sellos y escenas", desc: "Aaron Turner y Nate Newton alternando sludge demoledor con largos pasajes de ruido y collage sonoro. Discos construidos como bloques contrastados. Entrada: Christmas.", origin: "rec", pick: true },

  // ----- BLACK DISONANTE Y AVANT -----
  { name: "Krallice", genre: "Avant-garde Black Metal", y: 2007, p: 2, via: "Sellos y escenas", desc: "Mick Barr y Colin Marston escriben dos líneas de guitarra que no tocan nunca lo mismo, disonantes y desfasadas entre sí, sobre una batería que sostiene el pulso mientras la métrica se desplaza por encima. Muy prolíficos y desiguales: Krallice (2008), Dimensional Bleedthrough, Years Past Matter, Prelapsarian y Go Be Forgotten (2017) son lo mejor, y varios de los discos rápidos de los últimos años quedan por debajo. Entrada: Years Past Matter.", origin: "rec", pick: true },
  { name: "Liturgy", genre: "Avant-garde Black Metal", desc: "[Comodín] El comodín es por una cosa que sí se oye, no por su teoría: el burst beat, una batería que acelera y desacelera dentro del mismo compás en lugar de sostener el blast, lo que hace que el tema parezca respirar y tropezar a la vez. Sobre eso, tremolo de guitarra muy denso y voces agudas. Divide mucho a la gente, y el manifiesto que escribió Hunter Hunt-Hendrix sobre black metal trascendental es palabrería que no cuenta para nada aquí. Los discos recientes meten ópera y electrónica. El mapa: Renihilation (2009) y Aesthethica (2011), la cumbre, son black puro con burst beat; The Ark Work (2015), con metales de MIDI y voz cantada, divide mucho; H.A.Q.Q. (2019), Origin of the Alimonies (2020) y 93696 (2023) juntan la intensidad del principio con orquesta y electrónica. Entra por Aesthethica.", origin: "rec", p: 2, y: 2008, c: 3 },
  { name: "Ved Buens Ende", genre: "Avant-garde Black Metal (NO)", y: 1994, p: 2, via: "Sellos y escenas", desc: "Un solo disco, Written in Waters (1995): el bajo no dobla la raíz sino que lleva una tercera voz propia, los acordes tintinean sin resolver nunca y la batería de Carl-Michael Eide tiene fraseo de jazz, con voz limpia hablada encima, todo dentro del black noruego de 1995. Entrada: Written in Waters.", origin: "rec", pick: true },
  { name: "Panopticon", genre: "Atmospheric Black Metal / Folk", y: 2007, p: 1, c: 1, via: "Sellos y escenas", desc: "Austin Lunn toca todos los instrumentos y cruza black metal atmosférico con bluegrass y folk apalache de verdad: banjo, violín y voz limpia dentro del mismo tema, no en un interludio aparte. Kentucky y Roads to the North alternan pistas enteramente acústicas con black. El mapa: los cuatro primeros (2008-2011) son más crudos, con aire de crust; desde Kentucky (2012), Roads to the North (2014), Autumn Eternal (2015), The Scars of Man on the Once Nameless Wilderness (2018), ...And Again Into the Light (2021), The Rime of Memory (2023) y Laurentian Blue (2025) no bajan, y Det hjemsøkte hjertet (2026) es el último. Entrada: Kentucky.", origin: "rec", pick: true },
  { name: "Solefald", genre: "Avant-garde Black Metal (NO)", y: 1995, p: 2, c: 1, via: "Sellos y escenas", desc: "Black de vanguardia noruego que mete piano, saxo, voces limpias y letras en varios idiomas, cambiando de registro entre disco y disco. Neonism (1999), Pills Against the Ageless Ills y la pareja Icelandic Odyssey (2005-2006) son la cumbre. Entrada: Neonism.", origin: "rec", pick: true },

  // ----- MATH E INSTRUMENTAL -----
  { name: "Dysrhythmia", genre: "Prog / Instrumental", y: 1999, p: 2, via: "Sellos y escenas", desc: "Trío instrumental con Colin Marston al bajo llevando media armonía, Kevin Hufnagel a la guitarra y Jeff Eber a la batería: math y prog metal disonante sin voz, con estructuras que se reescriben cada pocos compases y bajo y guitarra en contrapunto en vez de doblarse. Pretest (2003) y Barriers and Passages (2006) son lo mejor; de Psychic Maps a Terminal Threshold (2019) y Coffin of Conviction (2024) la escritura se oscurece hacia el metal técnico, con altibajos. Entrada: Barriers and Passages.", origin: "rec", pick: true, c: 2 },
  { name: "And So I Watch You From Afar", genre: "Math Rock / Instrumental (IE)", y: 2005, p: 3, via: "Sellos y escenas", desc: "Math rock instrumental norirlandes con mucha mas energia y euforia que la media del genero: riffs entrelazados que van creciendo hasta estallar. Entrada: Gangs.", origin: "rec", pick: true },

  // ----- OTROS ANCESTROS -----
  { name: "Failure", genre: "Alt Rock / Space Rock", y: 1990, p: 2, via: "Ancestros", desc: "Space rock de los noventa con texturas de guitarra procesada y un bajo pesado que influyó directamente en Deftones y en medio metal alternativo atmosférico. Magnified (1994) y Fantastic Planet (1996), disco de culto que tardó veinte años en reconocerse, son la cumbre; la vuelta, de The Heart Is a Monster (2015) a Wild Type Droid (2021), mantiene el nivel. Entrada: Fantastic Planet.", origin: "rec", pick: true },
  { name: "At the Drive-In", genre: "Post-Hardcore", y: 1993, p: 2, via: "Ancestros", desc: "Post-hardcore angular y espasmódico: guitarras de Omar Rodríguez-López y Jim Ward en líneas que chocan, cambios de sección sin aviso y la voz de Cedric Bixler-Zavala al límite. In/Casino/Out (1998) y Relationship of Command (2000) son la cumbre y el punto de quiebre antes de The Mars Volta; in•ter a•li•a (2017), la vuelta, queda claramente por debajo. Entrada: Relationship of Command.", origin: "rec", pick: true },
  { name: "Comus", genre: "Folk / Avant-garde (UK)", y: 1969, p: 2, c: 3, via: "Ancestros", desc: "Folk ácido de 1971 que suena aterrador sin distorsión: violín y viola chirriantes, percusión de mano, guitarras acústicas rasgadas con furia y voces que gritan y susurran, en temas largos que cambian de clima sin avisar. Mikael Åkerfeldt de Opeth lo cita como influencia, y no hay nada parecido ni antes ni después. El mapa: First Utterance (1971) es la cumbre; To Keep from Crying (1974) es más amable, y tras volver en 2008 sacaron Out of the Coma (2012). Entrada: First Utterance.", origin: "rec", pick: true },
  { name: "Cocteau Twins", genre: "Dream Pop / Shoegaze (UK)", desc: "Robin Guthrie apila capas de guitarra con chorus y delay hasta que el instrumento deja de sonar a guitarra y se convierte en un colchón armónico brillante, y la voz de Fraser flota encima usada como textura y no como línea con letra. Es el sonido que fundó el dream pop, y de ahí sale el blackgaze. Precioso, pero armónicamente estático y de estructura simple. Entra por Heaven or Las Vegas.", origin: "rec", p: 3, y: 1979, c: 2 },
  { name: "Lingua Ignota", genre: "Avant-garde / Chamber", y: 2017, p: 3, c: 3, female: true, via: "Sellos y escenas", desc: "[Comodín] Kristin Hayter, de formación clásica, compone e interpreta todo: piano, voz operística, ruido industrial y silencio, en discos sobre la violencia que son más performance que canción. Caligula (2019) y Sinner Get Ready (2021); cerró el proyecto en 2023. Entrada: Caligula.", origin: "rec", pick: true },
  { name: "Emma Ruth Rundle", genre: "Post-Rock / Doom", y: 2011, p: 3, female: true, via: "Sellos y escenas", desc: "Guitarrista y compositora de rock oscuro y atmosférico, con afinaciones abiertas propias; su disco con Thou, May Our Chambers Be Full (2020), cruza su escritura con sludge. Entrada: On Dark Horses.", origin: "rec", pick: true },
  { name: "Tomahawk", genre: "Avant-garde Metal", y: 2000, p: 3, via: "Sellos y escenas", desc: "Otro Patton, con Duane Denison de The Jesus Lizard: rock angular y retorcido, y en Anonymous adaptaron melodias tradicionales de nativos americanos a estructuras de metal. Entrada: Anonymous.", origin: "rec", pick: true },
  { name: "Punch Brothers", genre: "Folk / Chamber", desc: "Chris Thile escribe suites largas con desarrollo temático real, en las que un motivo vuelve transformado varios movimientos después, y el grupo las toca con mandolina, banjo, violín, guitarra y contrabajo acústicos, sin batería, sosteniendo el pulso entre los cinco. Armonía de música de cámara sobre técnica de bluegrass, y la exigencia no baja de un disco a otro: The Blind Leaving the Blind son cuarenta minutos en cuatro movimientos, y The Phosphorescent Blues y All Ashore aplican lo mismo en formato corto. El mapa: Punch (2008) abre, con la suite The Blind Leaving the Blind; Antifogmatic (2010) y Who's Feeling Young Now? (2012) siguen; The Phosphorescent Blues (2015) es la cumbre, y el EP The Wireless (2015) la acompaña; All Ashore (2018) está cerca; Hell on Church Street (2022) versiona entero un disco de Tony Rice, y The Unsung Adventures of Punch Brothers (julio de 2026), todo instrumental, es el primero con Brittany Haas al violín. Entra por The Phosphorescent Blues.", origin: "rec", p: 1, y: 2006, c: 2 },

  // ----- ESCENA 2020s -----
  { name: "Chat Pile", genre: "Noise Rock / Sludge", y: 2019, p: 2, via: "Escena 2020s", desc: "Noise rock y sludge de Oklahoma con un sonido de bajo enorme y sucio y letras sobre la miseria americana. God's Country (2022) fue de los discos más aclamados de su escena y Cool World (2025) lo sostiene. Entrada: God's Country.", origin: "rec", pick: true },
  { name: "Dvne", genre: "Prog Metal / Sludge (UK)", y: 2013, p: 2, via: "Escena 2020s", desc: "Escoceses que cruzan sludge pesado con prog atmosférico y teclados, con temas largos de dinámica amplia y conceptos de ciencia ficción. Etemen Ænka (2021) y Voidkind (2024). Entrada: Etemen Ænka.", origin: "rec", pick: true },
  { name: "Geese", genre: "Art Rock / Experimental", y: 2017, p: 2, c: 1, via: "Escena 2020s", desc: "Rock neoyorquino que pasó del post-punk a un art rock retorcido y jazzístico, con una banda que toca cada vez más suelta y la voz de Cameron Winter desarmándose a propósito. Projector (2021), 3D Country (2023) y Getting Killed (2025), aclamado como uno de los discos de rock del año. Entrada: Getting Killed.", origin: "rec", pick: true },
  { name: "Squid", genre: "Post-Punk / Experimental (UK)", y: 2016, p: 2, c: 1, via: "Escena 2020s", desc: "Post-punk británico que se desborda hacia el krautrock, el jazz y la electrónica dentro de la misma canción, con Ollie Judge cantando desde la batería y piezas que crecen por capas. Bright Green Field (2021), O Monolith (2023) y Cowards (2025), cada uno más lejos del formato. Entrada: Bright Green Field.", origin: "rec", pick: true },
  { name: "OU", genre: "Progressive Metal / Djent (CN)", y: 2021, p: 2, via: "Escena 2020s", desc: "Prog metal chino con la voz etérea de Lynn Wu flotando por su cuenta sobre djent técnico en métricas cambiantes, con capas electrónicas integradas en el arreglo y no pegadas encima. one (2022) y II: Frailty (2024), los dos en InsideOut, sostienen el nivel. Entrada: one.", origin: "rec", pick: true }
];


// --- Nu Metal / Industrial: huecos detectados en el repaso de tiers (ago 2026) ---
const INDUSTRIAL_2026 = [
  { name: "Fear Factory", genre: "Industrial Metal", desc: "Su aporte es rítmico y muy concreto: Dino Cazares picando riffs staccato sincronizados nota a nota con el doble bombo mecánico de Raymond Herrera, de forma que guitarra y batería funcionan como un solo instrumento de percusión. Ese acoplamiento es la plantilla de la que sale medio metal moderno. Contrapeso honesto: las estructuras son estrofa-estribillo con voz limpia, y eso se vuelve fórmula según avanza la discografía. El mapa: Soul of a New Machine (1992) es death industrial; Demanufacture (1995) es la cumbre y Obsolete (1998) está cerca; Digimortal (2001) y Transgression (2005) bajan; Archetype (2004), Mechanize (2010), Genexus (2015) y Aggression Continuum (2021), el último con Burton C. Bell, recuperan el nivel. Su undécimo disco, el primero con Milo Silvestro, está grabado para finales de 2026 o principios de 2027. Entra por Demanufacture.", origin: "rec", p: 2, y: 1995, c: 2 },
  { name: "Strapping Young Lad", genre: "Industrial Metal / Extreme Metal", desc: "City es una pared de sonido con decenas de capas de guitarra y teclado apiladas hasta saturar el espectro, y con Gene Hoglan haciendo de columna compositiva, no de acompañamiento. Metal extremo industrial, denso y agresivo, muy distinto del prog que hace Devin Townsend con su nombre. El mapa: Heavy as a Really Heavy Thing (1995) es un esbozo; City (1997) y Alien (2005) son la cumbre; Strapping Young Lad (2003) y The New Black (2006) están cerca. Townsend lo cerró en 2007. Entra por City.", origin: "rec", p: 2, y: 1995, c: 2 },
];


// --- Prog / Djent: huecos detectados en el repaso de tiers (ago 2026) ---
const PROG_2026 = [
  { name: "Emerson, Lake & Palmer", genre: "Prog Rock", desc: "Keith Emerson metió el Moog y las adaptaciones de música clásica en el rock con una técnica de teclado que nadie tenía entonces, sobre el bajo y la voz de Greg Lake y la batería de Carl Palmer. Tarkus (1971) es una suite de veinte minutos en compases cambiantes. Emerson, Lake & Palmer (1970), Tarkus, Trilogy y Brain Salad Surgery (1973) son lo que importa; de Works (1977) en adelante bajan mucho. Aviso honesto: son la banda más grandilocuente del prog setentero y eso divide mucho. Entra por Tarkus.", origin: "rec", p: 2, y: 1970, c: 2 },
  { name: "Egg", genre: "Prog Rock (Canterbury)", desc: "El trío de órgano del que salen Hatfield and the North y National Health: Dave Stewart al órgano escribiendo en compases impares constantes y con armonía tomada de la música clásica, sin guitarra, sostenido por bajo y batería. Áspero y anguloso, bastante menos amable que el resto del Canterbury. Egg (1970), The Polite Force (1971) y The Civil Surface (1974). Entra por The Polite Force.", origin: "rec", p: 2, y: 1968, c: 2 },
  { name: "Psychotic Waltz", genre: "Prog Metal", desc: "Prog metal de San Diego muy poco conocido para lo bueno que es. Buddy Lackey canta y además toca flauta, piano y acústica, lo que les da un aire a Jethro Tull metido dentro del metal técnico. A Social Grace (1990) es de esos discos que no se parecen a nada de su momento. Se separaron, volvieron en 2010 con la formación original y sacaron The God-Shaped Void en 2020, veintitrés años después del anterior. Entra por A Social Grace.", origin: "rec", p: 2, y: 1990, c: 2 },
  { name: "Sieges Even", genre: "Technical Prog Metal (DE)", desc: "Prog metal técnico alemán construido sobre los hermanos Holzwarth, Oliver al bajo y Alex a la batería, que llevan la estructura en vez de acompañar. El debut, Life Cycle (1988), es abiertamente de la escuela de Watchtower, y Steps (1990) lleva los compases impares y los cortes al extremo; desde A Sense of Change (1991) se vuelven más propios y melódicos, y The Art of Navigating by the Stars (2005), con Arno Menses a la voz, es su cumbre. Entrada: The Art of Navigating by the Stars.", origin: "rec", p: 2, y: 1988, c: 2 }
];


// --- Banco pendiente de los repasos de tiers: prog + industrial (ago 2026) ---
const BANCO_2026 = [
  { name: "Zero Hour", genre: "Technical Prog Metal", desc: "Los gemelos Jasun y Troy Tipton, California, 1993. El bajo de Troy no acompaña: la escritura se apoya en sus líneas de tapping y legato, igual que Watchtower se apoya en Doug Keyser, así que aquí citar al músico sí es citar la sustancia. Estructuras muy retorcidas con voz limpia por encima. Historia dura: la banda se disolvió porque Troy se lesionó el brazo, y aunque se operó y volvió a tocar, ya no puede con las líneas de tapping que sostenían ese repertorio. Volvieron en 2022. Entra por The Towers of Avarice.", origin: "rec", p: 2, y: 1993, c: 2 },
  { name: "Miriodor", genre: "Avant Prog / RIO (CA)", desc: "Quebec, 1980, y más de cuarenta años en activo. RIO norteamericano en el terreno de Univers Zero y Art Zoyd: jazz, prog y música de cámara con compases cambiantes y temas que se pasan entre teclado, vientos y guitarra. Lo raro es que, siendo complejos hasta el extremo, resultan inmediatos de escuchar. Casi toda su obra está en Cuneiform. El mapa: de Rencontres y Miriodor (1986) a 3rd Warning (1991) y Jongleries Élastiques (1996) se fijan; Mekano (2001), Parade (2005), Avanti! (2009) y Cobra Fakir (2013) son la cumbre, y Signal 9 (2017) y Elements (2022) se mantienen. Entrada: Cobra Fakir.", origin: "rec", p: 2, y: 1980, c: 2 },
  { name: "Zevious", genre: "Prog / Instrumental", desc: "Trío instrumental de Nueva York: los primos Jeff y Michael Eber a batería y guitarra con Johnny DeBlase al bajo. Componen en polimetría, y sus referencias declaradas coinciden con lo que ya está en el catálogo: Mahavishnu Orchestra, Tony Williams Lifetime, Magma y King Crimson. Comparten gente con Dysrhythmia y Many Arms, o sea el mismo círculo de Behold... The Arctopus. Pasaron por Cuneiform y luego por Nefarious. El mapa: Zevious (2008) y After the Air Raid (2009) abren; Passing Through the Wall (2013) es la cumbre y Lowlands (2018) el último. Entra por Passing Through the Wall.", origin: "rec", p: 2, y: 2007, c: 2 },
  { name: "Planet X", genre: "Prog / Instrumental", desc: "Instrumental de fusión y metal con Derek Sherinian a los teclados, Virgil Donati a la batería y Tony MacAlpine a la guitarra. Sherinian dijo que quería una banda que diera miedo a otros músicos, y se nota: el virtuosismo va por delante de la idea, y hay reseñas que señalan que cuesta distinguir guitarra de teclado de tanta nota. Lo valioso es la escritura polirrítmica de Donati. Entrada: Universe.", origin: "rec", p: 3, y: 1999, c: 2 },
  { name: "U.K.", genre: "Prog Rock", desc: "Duraron dos discos y se deshicieron. El material que aguanta es el primero, el homónimo de 1978, con suites largas, compases raros y el violín eléctrico de Eddie Jobson llevando líneas principales en vez de adornar. Aviso de precisión: Holdsworth y Bruford solo están en ese primero; para Danger Money ya se habían ido a montar Bruford y entró Terry Bozzio. La crítica lo describe como prog de manual bien hecho, no como algo que rompa nada. Entra por U.K. (1978).", origin: "rec", p: 3, y: 1977, c: 2 },
  { name: "Foetus", genre: "Industrial / Orchestral", desc: "JG Thirlwell, australiano, lleva más de cuarenta años haciendo lo que casi nadie en el industrial: escribir de verdad. Sus discos apilan percusión, orquesta y electrónica en capas trabajadas, y ha llegado a usar orquestas y coros completos bajo el nombre The Foetus Symphony Orchestra. De ahí saltó a componer para cine y televisión. El mapa: Deaf (1981) y Ache (1982) abren; Hole (1984) y Nail (1985) son la cumbre; Thaw (1988) y Gash (1995) se mantienen, y Flow (2001), Love (2005) e Hide (2010) van cada vez más a lo orquestal. Entra por Nail o Hole.", origin: "rec", p: 2, y: 1981, c: 2 },
  { name: "Scorn", genre: "Industrial / Dub", desc: "El motor es la concepción rítmica de Mick Harris, que venía de Napalm Death: cogió el dub, con su bajo enorme y su espacio vacío entre golpes, y lo cruzó con el industrial hasta dejarlo lentísimo y opresivo. El mapa: Vae Solis (1992) aún es metal; Colossus (1993), Evanescence (1994) y Gyral (1995) son la cumbre; Logghi Barogghi (1996) y Zander (1997) van hacia la electrónica más seca, y de List of Takers (2004) a The Only Place (2019) y Cafe Mor (2022), la vuelta, se mantienen. Entra por Evanescence o Colossus.", origin: "rec", p: 2, y: 1991, c: 2 }
];


// --- Metalcore: huecos detectados en el repaso de tiers (ago 2026) ---
const MC_2026 = [
  { name: "Candiria", genre: "Metallic Hardcore / Jazz Fusion", desc: "Los instrumentistas son todos músicos formados en jazz, y eso no es una anécdota de biografía: les permite pasar de una sección de hard bop con solo de trompeta a hardcore puro dentro del mismo tema sin que suene a pegote. Muchos cambios de compás que ni se notan hasta la tercera escucha, y el hip-hop que meten está tocado con instrumentos en vivo, no montado con samples. Neoyorquinos, mezclan death metal, salsa, jazz y rap. Estuvieron años ignorados fuera del circuito hardcore. El mapa: Surrealistic Madness (1995) y Beyond Reasonable Doubt (1997) abren; The Process of Self.Development (1999) es la cumbre, con 300 Percent Density (2001) cerca; The Coma Imprint (2002) y lo posterior, de What Doesn't Kill You... (2004) a While They Were Sleeping (2016), van hacia un metal alternativo más directo. Entra por The Process of Self.Development, que es el más parejo de todos.", origin: "rec", p: 2, y: 1992, c: 2 },
  { name: "Refused", genre: "Hardcore Punk / Experimental (SE)", desc: "Suecos, y el disco por el que están aquí es The Shape of Punk to Come (1998): hardcore al que le metieron jazz, electrónica, palabra hablada y estructuras que abandonan el formato canción a mitad, en un momento en que nadie en el género hacía eso. Se les copió durante veinte años. Anunciaron su separación definitiva en 2024 (retrasada porque Dennis Lyxzén sufrió un infarto), giraron por Norteamérica en marzo y abril de 2025 y se despidieron en Suecia a final de año. Salió edición de 25 aniversario y un disco de tributo con Quicksand, IDLES y Touché Amoré. Entra por The Shape of Punk to Come.", origin: "rec", p: 2, y: 1991, c: 1 },
  { name: "Rolo Tomassi", genre: "Chaotic Post-Hardcore (UK)", desc: "De Sheffield, y lo suyo es el rango: pasan de hardcore a toda velocidad a pasajes de solo piano y voz dentro del mismo disco sin que chirríe. Eva Korman alterna limpios y guturales con un control raro de ver, y James Spence al piano no hace de relleno atmosférico: sostiene notas repetidas o cierra los temas con modulaciones complicadas, y se le oyen hasta los pedales. Técnica de verdad con melodías que además se pegan. El mapa: Hysterics (2008) y Cosmology (2010) son caos más juvenil; Astraea (2012) y Grievances (2015) maduran, y Time Will Die and Love Will Bury It (2018) y Where Myth Becomes Memory (2022) son la cumbre. Entra por Where Myth Becomes Memory.", origin: "rec", p: 2, y: 2005, c: 2 },
  { name: "Coalesce", genre: "Metallic Hardcore", desc: "De Kansas City, y el otro pilar del hardcore matemático de los noventa junto a Botch. Jes Steineger escribe los riffs como bloques que se cortan en seco y se recolocan en otro sitio, sin transición, así que el tema avanza a empujones en vez de fluir; Sean Ingram grita encima con una voz completamente rota. Áspero e incómodo a propósito, y sin la elegancia de Botch, que es justo lo que los distingue. El mapa: Give Them Rope (1997), Functioning on Impatience (1998) y 0:12 Revolution in Just Listening (1999), la cumbre; volvieron con Ox (2009), a buen nivel. Entra por 0:12 Revolution in Just Listening.", origin: "rec", p: 2, y: 1994, c: 2 }
];


// --- Death / Tech Death: huecos detectados en el repaso de tiers (ago 2026) ---
const DM_2026 = [
  { name: "Augury", genre: "Technical Death Metal (CA)", desc: "Death técnico de Quebec donde el bajo no acompaña: Dominic Lapointe toca un fretless que lleva la melodía principal buena parte del disco, con solos propios y glissandos, mientras las guitarras hacen armonía por debajo y la voz alterna gutural y agudo. Concealed (2004) y Fragmentary Evidence (2009) son la cumbre, e Illusive Golden Age (2018) queda algo por debajo. Entrada: Fragmentary Evidence.", origin: "rec", p: 1, y: 2001, c: 2 },
  { name: "Nocturnus", genre: "Technical Death Metal (US)", desc: "Tampa, 1990, y su disco The Key fue el primer death metal con teclados melódicos al frente: Louis Panzer no hace colchón de fondo, toca líneas y solos que se turnan con la guitarra, sobre riffs técnicos y letras de ciencia ficción en vez de las de siempre. En su momento sonó fuera de sitio y hoy se oye como el antepasado de todo el death con teclado que vino después. El mapa: The Key (1990) es la cumbre; Thresholds (1992), con otro cantante, se vuelve más progresivo, y Ethereal Tomb (1999) baja. Entra por The Key.", origin: "rec", p: 2, y: 1987, c: 2 },
  { name: "Discordance Axis", genre: "Grindcore / Technical", desc: "Grindcore de Nueva Jersey, y de los pocos donde la brevedad extrema no implica simpleza: Rob Marton escribe riffs disonantes y angulares que cambian de figura cada pocos segundos en vez de repetir el mismo trémolo, Dave Witte toca blast beats con una precisión casi matemática y Jon Chang grita en un registro agudísimo. En Jouhou se fueron a propósito hacia lo técnico. The Inalienable Dreamless está considerado de los mejores discos de grindcore que existen. El mapa: Ulterior (1995), Jouhou (1997) y The Inalienable Dreamless (2000), la cumbre; se separaron poco después. Entra por The Inalienable Dreamless.", origin: "rec", p: 2, y: 1992, c: 2 }
];


// --- Avant-garde: huecos detectados en el repaso de tiers (ago 2026) ---
const AV_2026 = [
  { name: "Sun Ra", genre: "Avant-garde Jazz / Big Band", desc: "Dirigió durante décadas una orquesta enorme, la Arkestra, y ahí está la sustancia: escritura de big band que arranca en el swing más ortodoxo y se desmonta en improvisación colectiva de veinte instrumentos a la vez, con él mismo entre los primeros en meter teclados eléctricos y sintetizadores en el jazz cuando aún eran aparatos de laboratorio. La mitología cósmica que se montó alrededor es aparte y no cuenta aquí. El mapa: Jazz in Silhouette (1959) es big band escrita; The Futuristic Sounds of Sun Ra (1962), The Magic City (1965) y The Heliocentric Worlds (1965-66) abren el free; Atlantis (1969), Space Is the Place (1973) y Lanquidity (1978) son la cumbre de su etapa eléctrica. Murió en 1993. Entra por The Magic City o Space Is the Place.", origin: "rec", p: 2, y: 1952, c: 1 },
  { name: "Alice Coltrane", genre: "Spiritual Jazz / Experimental", desc: "Metió el arpa en el jazz como instrumento principal, no decorativo: hace glissandos que cubren el registro entero y funcionan como armonía y percusión a la vez, sobre modos indios y drones de tambura, con arreglos de cuerda escritos por ella. Después se fue a los órganos Wurlitzer y a la música devocional, cada vez más lejos de la forma canción. El mapa: A Monastic Trio (1968) abre; Journey in Satchidananda (1971), Universal Consciousness (1971), World Galaxy (1972) y Lord of Lords (1972) son la cumbre; Eternity (1976) y Transcendence (1977) cierran la etapa de sello, y lo del ashram, de Turiya Sings (1982) a Divine Songs (1987), es música devocional. Murió en 2007. Entra por Journey in Satchidananda. (compositora)", origin: "rec", p: 2, y: 1968, c: 2, female: true },
  { name: "Colin Stetson", genre: "Experimental / Solo Saxophone", desc: "Una persona, un saxofón bajo, sin overdubs, sin loops y sin delay: todo lo que oyes está tocado de una sola vez. Usa respiración circular para no parar nunca de sonar (inspira por la nariz mientras expulsa por la boca), canta dentro del instrumento mientras toca para generar una segunda voz, y lleva micrófonos en las llaves para que el golpeteo de los dedos haga de percusión. El resultado suena a banda entera y no lo es. Digitaciones raras y armónicos por todas partes. El mapa: New History Warfare Vol. 1 (2008), Vol. 2: Judges (2011) y Vol. 3: To See More Light (2013), la cumbre; Never Were the Way She Was (2015), con Sarah Neufeld, y All This I Do for Glory (2017) siguen, y la banda sonora de Hereditary (2018) es aparte. Entra por New History Warfare Vol. 2: Judges.", origin: "rec", p: 2, y: 2007, c: 2 },
  { name: "The Necks", genre: "Experimental / Improvised Jazz (AU)", desc: "Trío australiano de piano, contrabajo y batería que lleva desde 1987 haciendo una sola cosa: piezas de una hora, normalmente una por disco, que empiezan con una célula mínima y la van transformando por acumulación sin cortes ni temas. No componen de antemano, así que la estructura se decide mientras suena, y el pulso de Tony Buck en la batería sostiene la tensión. Exige paciencia. El mapa: Sex (1989) abre; Aquatic (1994), Hanging Gardens (1999), Aether (2001) y Drive By (2003) son la cumbre; de Chemist (2006) y Silverwater (2009) a Open (2013), Unfold (2017), Body (2018) y Travel (2023) no bajan. Entrada: Sex o Drive By.", origin: "rec", p: 2, y: 1987, c: 2 }
];


