const SYNTH_2026B = [
  { name: "Shackleton", genre: "Electronic / Bass Music (UK)", desc: "Música electrónica de Lancashire construida casi solo con percusión: capas de tambores, marimbas y gongs en polirritmos que se superponen y se desfasan, con influencias africanas, árabes e indias, bajos de dub profundísimos y voces recitadas; los temas duran diez o veinte minutos y cambian sin que se note el corte. El mapa: Three EPs (2009) es la cumbre de la etapa de pista; Music for the Quiet Hour (2012) y Freezing Opening Thawing (2014) abren la forma larga; Devotional Songs (2016), con el cantante Ernesto Tomasini, Sferic Ghost Transmits (2017), con Vengeance Tenfold, y Primal Forms (2020), con el clarinetista Wacław Zimpel, son las colaboraciones; Departing Like Rivers (2021), The Scandal of Time (2023) y Euphoria Bound (2026) siguen. Entrada: Three EPs, luego Music for the Quiet Hour.", p: 2, origin: "rec", y: 2004, via: "Sellos y escenas", c: 2 },
  { name: "Floating Points", genre: "Electronic (UK)", desc: "Sam Shepherd mezcla electrónica y músicos reales: en Elaenia una banda en directo toca sobre sintetizadores modulares, con armonía de jazz y crescendos largos, y Promises es una pieza de cuarenta y seis minutos en nueve movimientos construida sobre un único motivo de siete notas que se repite en clave, piano y celesta mientras Pharoah Sanders improvisa al saxo y la London Symphony Orchestra entra y sale. El mapa: Elaenia (2015) abre; Crush (2019) es más de pista y más áspero; Promises (2021) es la cumbre; Cascade (2024) vuelve al club, y la música de ballet Mere Mortals, estrenada en 2024, tiene disco en 2026. Entrada: Promises, luego Elaenia.", p: 2, origin: "rec", y: 2009, via: "Sellos y escenas", c: 2 },
  { name: "Isao Tomita", genre: "Synth / Electronic (JP)", desc: "Orquestación con sintetizador llevada al detalle: en un Moog III, voz por voz en cinta multipista, rehízo a Debussy, Músorgski, Stravinski y Holst con timbres inventados, silbidos sintéticos, voces que parecen humanas y un uso del espacio estéreo, y luego cuadrafónico, que mueve cada línea por la sala. Snowflakes Are Dancing le llevó catorce meses. Es la otra gran obra de ese oficio junto a la de Wendy Carlos. El mapa: Snowflakes Are Dancing (1974), Pictures at an Exhibition (1975), Firebird (1976) y The Planets (1976) son la cumbre; Kosmos (1978), Bermuda Triangle (1979) y Grand Canyon (1982) siguen, y Canon of the Three Stars (1984) cierra la etapa. Murió en 2016. Entrada: Snowflakes Are Dancing.", p: 2, origin: "rec", y: 1972, via: "Sellos y escenas", c: 2 },
  { name: "Raymond Scott", genre: "Jazz / Electronic (US)", desc: "Jazz descriptivo de los años treinta, escrito nota a nota en vez de improvisado: piezas de tres minutos como Powerhouse o Twilight in Turkey cambian de tempo y de escena varias veces, con un sexteto tocando unísonos rapidísimos, y Carl Stalling las usó en más de cien dibujos de Warner. Después montó Manhattan Research y construyó el Electronium, un sintetizador que componía por algoritmo, y su segunda obra es electrónica pionera. El mapa: las grabaciones del Quintette (1937-1939), recogidas en Reckless Nights and Turkish Twilights (1992), son la cumbre; Soothing Sounds for Baby (1964) es minimalismo electrónico antes de tiempo, y Manhattan Research, Inc. (2000) y Three Willow Park (2017) recogen el archivo electrónico. Murió en 1994. Entrada: Reckless Nights and Turkish Twilights, luego Manhattan Research, Inc.", p: 2, origin: "rec", y: 1936, via: "Sellos y escenas", c: 2 },
];

